    check("pygame.time.wait" not in swap, "no wait on the render thread")
    check("LOUDNESS_HOLD_LAST_FRAME_MS" in source and hasattr(gov, "LOUDNESS_HOLD_LAST_FRAME_MS"), "the hold time lives in the governor table (R7)")


