def suite_guide_settled_days():
    check(gov.GUIDE_LIVE_HOURS == 24.0, "the live part of the guide is 24 hours and lives in the governor")
    ns = {"_GUIDE_LIVE_HOURS": 24.0}
    exec(main_function_code("_settle_future_rows"), ns)
    settle = ns["_settle_future_rows"]
    H = 3600.0
    def rows(start_h, count, length_h, estimate_from=None, tag="new"):
        out = []
        for i in range(count):
            st = (start_h + i * length_h) * H
            out.append({"path": "%s%d" % (tag, i), "planned_start": st, "used_length": length_h * H, "slot_key": "c@%d" % ((start_h + (i - i % 6) * length_h) * H), "position": i % 6,
                        "length_source": "estimate" if estimate_from is not None and st >= estimate_from * H else "measured", "guide_entry": {}})
        return out
    first = rows(10, 40, 2, estimate_from=30)
    check(settle(first, [], 0.0) == sorted(first, key=lambda r: r["planned_start"]), "with nothing saved yet the whole new future is used, so the guide fills at once")
    saved = [dict(r, path="old%d" % i, length_source=None) for i, r in enumerate(rows(10, 40, 2))]
    out = settle(rows(10, 40, 2, estimate_from=30, tag="new"), saved, 0.0)
    news = [r for r in out if r["path"].startswith("new")]
    olds = [r for r in out if r["path"].startswith("old")]
    check(news and max(r["planned_start"] for r in news) == 32 * H and min(r["planned_start"] for r in olds) == 34 * H,
          "inside the first 24 hours the new rows are used, with the rest of the cycle that crosses that line; past it a day with estimated lengths keeps the rows saved before")
    out2 = settle(rows(10, 40, 2, estimate_from=60, tag="new"), saved, 0.0)
    news2 = [r for r in out2 if r["path"].startswith("new")]
    check(max(r["planned_start"] for r in news2) == 56 * H and all(r["planned_start"] >= 58 * H for r in out2 if r["path"].startswith("old")),
          "a day past the first 24 hours whose lengths are all measured is redrawn whole with the cycle that crosses its end; the next day, still estimated, stays as it was")
    # WARNING: owner log 2026-11-23: a cycle taken half new and half saved gave two rows one key, so a row was lost and the guide drew OFF AIR.
    longer = [dict(r, length_source=None) for r in rows(10, 40, 3, tag="old")]
    for label, settled in (("saved cycles longer than the new ones", settle(rows(10, 40, 2, estimate_from=30, tag="new"), longer, 0.0)),
                           ("saved cycles shorter than the new ones", settle(rows(10, 40, 3, estimate_from=30, tag="new"), saved, 0.0))):
        keys = [(r["slot_key"], r["position"]) for r in settled]
        check(len(keys) == len(set(keys)), "%s: no two settled rows share a cycle and place, so none is lost when they are saved" % label)
        ends = sorted((r["planned_start"], r["planned_start"] + r["used_length"]) for r in settled)
        check(all(b[0] >= a[1] - 0.5 for a, b in zip(ends, ends[1:])), "%s: no settled rows overlap" % label)
        holes = [(a[1] / H, b[0] / H) for a, b in zip(ends, ends[1:]) if b[0] > a[1] + 0.5]
        check(not [h for h in holes if h[1] <= 48], "%s: the first day and the cycle after it have no hole the guide would draw as OFF AIR (%s)" % (label, holes[:2]))
    out3 = settle(rows(10, 40, 2, tag="new"), saved, 0.0)
    check(all(r["path"].startswith("new") for r in out3), "once every day is measured the whole future is new")
    check(settle(saved, saved, 0.0) is None, "nothing is written when the settled future equals what is saved, so the guide is not rebuilt for nothing")
    src = MAIN_SRC[MAIN_SRC.index("def _hub_future_for_channel"):]
    src = src[:src.index("_hub_future_logged = {}")]
    check(src.index("_settle_future_rows(_rows, _hub_f.future_rows_between(") < src.index("_hub_f.replace_future_rows(_channel, _rows)")
          and "if _rows is None:" in src, "the future rows are settled against what is saved before they are written")


def suite_future_rows_follow_the_server_zone():
    # WARNING: owner log 2026-11-23: a streaming computer one hour off its server saved every future row an hour late.
    for offset in (None, 3600, -5 * 3600, 9 * 3600 + 1800):
        ns = {"datetime": datetime, "broadcast_clock": types.SimpleNamespace(server_utc_offset=lambda o=offset: o)}
        exec(main_function_code("_broadcast_epoch_of"), ns)
        wall = datetime.datetime(2026, 11, 24, 6, 30, 0)
        abs_second = wall.toordinal() * 86400 + 6 * 3600 + 1800
        want = wall.timestamp() if offset is None else wall.replace(tzinfo=datetime.timezone(datetime.timedelta(seconds=offset))).timestamp()
        check(ns["_broadcast_epoch_of"](abs_second) == want, "offset %s: a broadcast wall time is read in the zone the broadcast clock is in" % offset)
        if offset is not None:
            aware_now = wall.replace(tzinfo=datetime.timezone(datetime.timedelta(seconds=offset)))
            check(ns["_broadcast_epoch_of"](abs_second) == aware_now.timestamp(), "offset %s: it is the same second the broadcast clock's own now() gives at that wall time" % offset)
    check("schedule_planner.loop_plan(" in get_function_source("_hub_loop_plan") and "broadcast_epoch_of(ordinal * 86400)" in open(_script("schedule_planner.py"), encoding="utf-8").read(),
          "the loop plan turns each day's midnight into a clock second in the broadcast clock's zone")
    for name in ("_write_missed_blocks_to_hub", "_hub_future_for_channel"):
        src = get_function_source(name)
        check("_broadcast_epoch_of(" in src and "_moment.timestamp()" not in src and "datetime.time(0)).timestamp()" not in src,
              "%s turns broadcast wall times into clock seconds in the broadcast clock's zone" % name)


def suite_scan_turns():
    import performance_governor as pg
    pg._scan_turns.clear()
    t = 1000.0
    pg.scan_report_head("loudness", (2, 1), now=t)
    pg.scan_report_head("duration", (3, 4), now=t)
    pg.scan_report_head("picture_box", (3, 6), now=t)
    check(pg._scan_more_urgent("duration", (3, 4), now=t + 1) and pg._scan_more_urgent("picture_box", (3, 6), now=t + 1),
          "lengths and picture boxes far ahead wait while loudness has a next show waiting")
    check(not pg._scan_more_urgent("loudness", (2, 1), now=t + 1) and pg.scan_is_most_urgent("loudness", now=t + 1),
          "loudness takes the turn and may use the threads the others leave")
    pg.scan_report_head("loudness", (1, 0), now=t + 2)
    pg.scan_report_head("duration", (2, 0), now=t + 2)
    check(pg._scan_more_urgent("duration", (2, 0), now=t + 3), "an unscanned commercial airing soon goes ahead of the next shows")
    check(not pg._scan_more_urgent("duration", (2, 0), now=t + 2 + pg.SCAN_TURN_STALE_SECONDS + 1),
          "a scan that stopped reporting no longer holds the others")
    pg.scan_report_head("loudness", (1, 0), now=t + 200)
    pg._scan_turns["loudness"]["progress"] = t + 200 - pg.SCAN_TURN_STUCK_SECONDS - 1
    check(not pg._scan_more_urgent("duration", (2, 0), now=t + 200), "a scan stuck on one file no longer holds the others")
    pg.scan_report_head("loudness", None, now=t + 201)
    check(not pg._scan_more_urgent("duration", (3, 9), now=t + 201), "a scan with nothing waiting holds nobody")
    check(not pg._scan_more_urgent("duration", (2, 0), now=t + 201) and not pg._scan_more_urgent("x", None, t), "equal or unknown urgency never waits")
    pg._scan_turns.clear()
    pg.set_game_active(True)
    try:
        check(pg.scan_threads() == pg.GAME_SCAN_THREADS, "while a game runs the scans share %d scan thread" % pg.GAME_SCAN_THREADS)
        check(not pg.game_needs_all(), "a smooth game does not stop the scans")
        g0 = 5000.0
        for i in range(60):
            pg.note_game_tick(i % 3 == 0, now=g0 + i * 0.016)
        check(pg.game_needs_all(), "a game that keeps having to catch up stops the background scans")
        for i in range(60):
            pg.note_game_tick(False, now=g0 + 10 + i * 0.016)
        check(pg.game_needs_all(), "they stay stopped until the game has been steady for a while")
        for i in range(800):
            pg.note_game_tick(False, now=g0 + 12 + i * 0.016)
        check(not pg.game_needs_all(), "a steady game lets the scans go on again at the game pace")
    finally:
        pg.set_game_active(False)
    check(not pg.game_needs_all() and pg.scan_threads() >= 1, "leaving the game returns to normal")
    gate_src = read(_script("performance_governor.py"))
    check("and (lane not in FFMPEG_SCAN_LANES or ffmpeg_scans_running() < ffmpeg_scans_at_once(level))" in gate_src and "not playback_needs_the_pc()" in gate_src,
          "background scan work may not start past the overall cap (the PC's peak, narrowed with the level) or during a tune; priority work never waits")
    slot = gate_src[gate_src.index("def scan_thread_slot"):]
    slot = slot[:slot.index("def scan_gpu_decode_allowed")]
    check("_slot_active[0] < scan_threads() and ticket == min(_slot_waiting)" in slot and "scan_note_progress(kind)" in slot,
          "a file takes a place only while one is free and it is the most urgent waiting file, and a finished file is recorded")
    for wiring in ('with _scan_thread_slot("duration", _cls, _tier_idx) as _slot_ok:', 'with _scan_thread_slot("picture_box", _cls, _tier_idx) as _slot_ok:',
                   'with _scan_thread_slot("loudness", _head_cls, _chunk[0][1]) as _slot_ok:', 'with _scan_thread_slot("music", _scan_cls) as _slot_ok:',
                   'with _scan_thread_slot("commercial_check", SCAN_CLASS_COMMERCIAL) as _slot_ok:', 'with _scan_thread_slot("pending", SCAN_CLASS_DEEP) as _slot_ok:'):
        check(wiring in MAIN_SRC, "every scanner takes its turn: %s" % wiring)
    check('_scan_report_head("loudness", _pipeline_items[_need_pi][0], _pipeline_items[_need_pi][1])' in MAIN_SRC,
          "loudness reports its next file that still needs loudness, not files already done")
    pause = MAIN_SRC[MAIN_SRC.index("def _background_scan_should_pause"):MAIN_SRC.index("def _background_scan_pace_seconds")]
    check('performance_governor.scan_throttle_mode() == "stopped"' in pause and "or _is_game_actively_playing()" in MAIN_SRC[MAIN_SRC.index("def _python_heavy_should_pause"):MAIN_SRC.index("def _background_scan_pace_seconds")],
          "scans stop for a game only when the governor says stopped; Python-heavy work still waits for the whole game")
    fut = MAIN_SRC[MAIN_SRC.index("def _hub_future_worker"):]
    check("if _python_heavy_should_pause() or _server_work_should_yield():" in fut[:3000], "the future guide rows wait for the whole game")
    check("performance_governor.set_game_active(_is_game_actively_playing())" in MAIN_SRC
          and "_gov.note_game_tick(self._gft_runs > 1)" in read(_script("game_deck.py")),
          "the governor knows when a game runs and how its frames keep up")
    music = MAIN_SRC[MAIN_SRC.index("def _music_precache_worker"):]
    check("while _background_scan_should_pause():\n                    if _app_shutting_down.wait(_scan_pace(MUSIC_PRECACHE_BETWEEN_TRACKS_SECONDS)):" in music,
          "the music scan waits on a pause instead of skipping songs")


