class TestChannel03BackdropFollowsTheTheme(unittest.TestCase):
    """Owner 2026-11-23: channel 03 with no picture shows the menus' theme background with a border in the border color, not black"""

    def test_the_backdrop_is_the_theme_background_with_a_border(self):
        module = load_deck_module(_script("game_deck.py"), "game_deck_ch03_backdrop")
        import colorsys
        deck = object.__new__(module.ExternalGameDeck)
        deck.ui_color = (10, 200, 30)
        fills, rects = [], []
        screen = types.SimpleNamespace(fill=lambda color, rect=None: fills.append((color, rect)))
        main = types.SimpleNamespace(db=types.SimpleNamespace(config={"theme_bg_hue": 120}))
        with patch.dict(sys.modules, {"__main__": main}), patch.object(module.pygame.draw, "rect", lambda surf, color, rect, width=0: rects.append((color, rect, width))):
            deck._draw_theme_backdrop(screen, (0, 0, 1360, 680))
        r, g, b = colorsys.hsv_to_rgb(120 / 360.0, 0.6, 0.15)
        self.assertEqual(fills, [((int(r * 255), int(g * 255), int(b * 255)), (0, 0, 1360, 680))])
        self.assertEqual(len(rects), 2, "owner 2026-11-23: double borders, the edge one and the inset one")
        self.assertEqual(rects[0], ((10, 200, 30), (0, 0, 1360, 680), gov.CH03_BACKDROP_BORDER_PX),
                         "owner 2026-11-23: the outside border on the screen's edges is back")
        color, (bx, by, bw, bh), width = rects[1]
        edge = gov.CH03_BACKDROP_EDGE_GAP_PX
        self.assertEqual((color, width, bx, by, bw), ((10, 200, 30), gov.CH03_BACKDROP_BORDER_PX, edge, edge, 1360 - 2 * edge),
                         "owner 2026-11-23: the border is set in from the edges so the background colour shows outside it")
        self.assertEqual(680 - (by + bh), edge, "owner 2026-11-24: the same gap at the bottom as on the other three sides")
        self.assertFalse(hasattr(gov, "CH03_BACKDROP_LEGEND_GAP_PX"))
        src = open(_script("game_deck.py"), encoding="utf-8").read()
        legend = src[src.index("    def _draw_legend("):src.index("    # SECTION: Rendering: console carousel")]
        self.assertIn("y_title = y + h - edge - border - (f.get_height() + key_h + gap) - _gov.GAME_LEGEND_BOTTOM_PAD_PX", legend,
                      "the control hints sit inside the inner border")

    def test_the_no_picture_screen_draws_the_backdrop_and_not_black(self):
        src = open(_script("game_deck.py"), encoding="utf-8").read()
        render = src[src.index("    def render("):]
        render = render[:render.index("\n    def ", 10)]
        self.assertIn("self._draw_theme_backdrop(screen, rect)", render)

    def test_a_background_picture_still_replaces_the_colour_and_gets_the_border(self):
        # WARNING: owner 2026-11-23: the background picture still replaces the default, border line and all.
        module = load_deck_module(_script("game_deck.py"), "game_deck_ch03_picture")
        deck = object.__new__(module.ExternalGameDeck)
        deck.ui_color = (200, 10, 10)
        deck.mode = "CAROUSEL"
        deck._ensure_fonts = lambda: None
        picture = module.pygame.Surface((64, 32))
        deck._get_menu_bg_surface = lambda: picture
        calls = []
        deck._draw_theme_backdrop = lambda screen, rect: calls.append("colour")
        deck._draw_screen_border = lambda screen, rect: calls.append("border")
        screen = module.pygame.Surface((340, 170))
        try:
            deck.render(screen, (0, 0, 340, 170))
        except Exception:
            pass
        self.assertEqual(calls[:1], ["border"])
        self.assertNotIn("colour", calls)


def suite_list_leaves_failed_drive():
    module = load_deck_module(_script("game_deck.py"), "game_deck_list_drive")
    module._gd_drive_root_of = lambda path: (str(path)[:2] + "\\") if path and ":" in str(path) else None
    calls = []

    def make(mode="ROMLIST", console="DVD", browse="D:\\Movies", roms=None):
        deck = object.__new__(module.ExternalGameDeck)
        deck.mode = mode
        deck.active_console = console
        deck.current_browse_dir = browse
        deck.roms = list(roms or [])
        deck._drive_launch_failed = {}
        deck._romlist_error_msg = ""
        deck._romlist_error_until = 0
        deck._get_console_rom_dir = lambda c: "C:\\roms\\" + c
        deck._scan_roms = lambda c: calls.append(("scan", c))
        deck._snap_rom_cursor_if_scan_landed = lambda: None
        return deck

    D, C = "D:\\", "C:\\"
    deck = make()
    check(deck.leave_list_of_failed_drive(set()) is False and deck.current_browse_dir == "D:\\Movies", "no failed drive, the list stays where it is")
    check(deck.leave_list_of_failed_drive({C}) is False and deck.current_browse_dir == "D:\\Movies", "a failed drive that is not the one being browsed leaves the list alone")
    check(deck.leave_list_of_failed_drive({D}) is True and deck.current_browse_dir == "" and set(deck.drive_launch_failures()) == {D},
          "browsing a folder on a drive that failed leaves that folder, notes the drive for the banner and rescans")
    check(("scan", "DVD") in calls and "Drive not responding" in deck._romlist_error_msg, "the list is rescanned and says why")
    calls.clear()
    check(deck.leave_list_of_failed_drive({D}) is False and calls == [], "a drive already handled is not handled again every frame")

    for mode in ("GAME", "DVD_PLAYER", "LOADING"):
        running = make(mode=mode)
        check(running.leave_list_of_failed_drive({D}) is False and running.current_browse_dir == "D:\\Movies" and not running.drive_launch_failures(),
              "a running game or DVD is never touched by a drive that fails (%s)" % mode)

    top = make(browse="", roms=[("[DRIVE] C:\\", C), ("[DRIVE] D:\\", D)])
    check(top.leave_list_of_failed_drive({D}) is True and set(top.drive_launch_failures()) == {D},
          "a drive that fails while the list of drives is on screen is noted and the list is rebuilt")

    console = make(console="SNES", browse="D:\\roms\\SNES")
    check(console.leave_list_of_failed_drive({D}) is True and console.current_browse_dir == "C:\\roms\\SNES" and set(console.drive_launch_failures()) == {D},
          "a game list on a failed drive goes back to the console's own folder and notes the drive")

    module._media_listing = types.SimpleNamespace(held_drive_roots=lambda: [])
    mixed = make(roms=[("[.. BACK TO THIS PC]", ""), ("[DRIVE] C:\\", C), ("[DRIVE] D:\\", D), ("[.. BACK TO PREVIOUS FOLDER]", "D:\\")])
    mixed.note_drive_launch_failure(D)
    shown = [n for n, _p in mixed._without_failed_drives(mixed.roms)]
    check(shown == ["[.. BACK TO THIS PC]", "[DRIVE] C:\\", "[.. BACK TO PREVIOUS FOLDER]"], "the failed drive is hidden from the drive picker and the back entries stay")
    files = make(roms=[("Game One", "D:\\roms\\one.sfc"), ("Game Two", "C:\\roms\\two.sfc")])
    files.note_drive_launch_failure(D)
    check(len(files._without_failed_drives(files.roms)) == 2, "a game file on a failed drive stays listed (owner 2026-11-06: the banner says what is wrong, the file stays)")
    mixed.clear_drive_launch_failure(D)
    check(len(mixed._without_failed_drives(mixed.roms)) == 4, "once the drive is cleared it is listed again")

    src = MAIN_SRC
    check("game_deck.leave_list_of_failed_drive(set(_failed_drive_roots()))" in src, "the main loop hands the drives that stayed unresponsive long enough to the list every frame")


