def suite_guide_future_from_hub():
    tmp = tempfile.mkdtemp()
    lib = ml.MediaLibrary(os.path.join(tmp, "library.sqlite3"))
    try:
        hub = ml.ScheduleHub(lib)
        now = datetime.datetime(2026, 10, 25, 10, 0, 0)
        midnight = datetime.datetime(2026, 10, 25).timestamp()
        pair = {"path": "/m/a.mkv", "duration": 1500.0, "is_pair": True, "pair_ep1_path": "/m/a.mkv", "pair_ep1_duration": 700.0,
                "pair_ep2_path": "/m/b.mkv", "pair_ep2_duration": 800.0}
        hub.replace_future_rows("05", [
            {"slot_key": "k@1", "position": 0, "path": "/m/a.mkv", "kind": "episode", "planned_start": midnight + 12 * 3600, "used_length": 1500.0, "guide_entry": pair},
            {"slot_key": "k@1", "position": 1, "path": "/m/ad.mp4", "kind": "commercial", "planned_start": midnight + 12 * 3600 + 1500, "used_length": 30.0, "guide_entry": {"path": "/m/ad.mp4", "duration": 30.0}},
            {"slot_key": "k@1", "position": 2, "path": "/m/n.mkv", "kind": "episode", "planned_start": midnight + 12 * 3600 + 1530, "used_length": 900.0, "guide_entry": None}])
        hub.replace_future_rows("07", [{"slot_key": "k@9", "position": 0, "path": "/m/far.mkv", "kind": "episode", "planned_start": midnight + 6 * 86400 + 9 * 3600, "used_length": 1800.0, "guide_entry": {"path": "/m/far.mkv", "duration": 1800.0}}])
        far = ui._guide_hub_future_cells("07", now, 6 * 86400 + 8 * 3600, 6 * 86400 + 12 * 3600, hub=hub)
        check(len(far) == 1 and far[0][1] == 6 * 86400 + 9 * 3600, "a row on the seventh day ahead is read back at its planned time, so the week comes from the hub")
        cells = ui._guide_hub_future_cells("05", now, 10 * 3600, 16 * 3600, hub=hub)
        check(len(cells) == 2, "a row with no readable facts is left to the guide's own future (%d cells)" % len(cells))
        check(cells[0][0].get("is_pair") and cells[0][0]["pair_ep2_path"] == "/m/b.mkv" and cells[0][1] == 12 * 3600 and cells[0][2] == 12 * 3600 + 1500,
              "a projected pair is drawn as the pair with both parts, at its planned time")
        check(cells[1][0]["is_commercial"] is True, "a projected break is a break cell")
        day_two = [(({"path": "/m/old.mkv", "duration": 7200.0}), 11 * 3600, 13 * 3600, "Morning")]
        spliced = ui._guide_splice_aired(day_two, ui._guide_aired_rows_in_view(cells, 10 * 3600, 16 * 3600))
        check(any(c[0].get("path") == "/m/a.mkv" for c in spliced) and any(c[0].get("path") == "/m/old.mkv" for c in spliced),
              "the hub's future lies over the guide's own copy and the copy keeps the part the hub does not cover")
        sig = ui._guide_hub_future_signature("05", now, hub=hub)
        check(sig and sig[0] == 3, "the guide's saved timeline key holds the future rows' signature: %s" % (sig,))
        broken = types.SimpleNamespace(future_rows_between=lambda *a: (_ for _ in ()).throw(RuntimeError("boom")),
                                       future_signature=lambda *a: (_ for _ in ()).throw(RuntimeError("boom")))
        check(ui._guide_hub_future_cells("05", now, 10 * 3600, 16 * 3600, hub=broken) == [], "a failing hub gives no future cells, so the guide draws its own")
        check(ui._guide_hub_future_signature("05", now, hub=broken) is None, "a failing hub gives no signature and the guide still draws")
        src = open(_script("ui.py"), encoding="utf-8").read() if "ROOT" in globals() else None
        if src is None:
            import inspect
            src = inspect.getsource(ui)
        key_at = src.index("_guide_hub_future_signature(ch_str, now_dt))")
        check(key_at < src.index("_tl_hit = _guide_timeline_cache.get(_tl_key)"), "the future rows' signature is part of the guide's timeline cache key")
        future_at = src.index("_guide_hub_future_cells(ch_str, now_dt, viewport_adjusted_start")
        check(future_at < src.index("_guide_hub_aired_cells(ch_str, now_dt, viewport_adjusted_start"), "the hub's past is laid over the future, never the other way round")
    finally:
        lib.close()
        shutil.rmtree(tmp, ignore_errors=True)


class TestHubPlaybackDoor(unittest.TestCase):
    """14.10: playback asks the hub; on a miss the hub asks the scheduler and keeps the answer"""

    def _ns(self, calls, clock):
        import types, time, logging
        hub = __import__("media_library").ScheduleHub.__new__(__import__("media_library").ScheduleHub)
        hub._show_facts, hub._upcoming = {}, {}
        ml = types.SimpleNamespace(shared_schedule_hub=lambda: hub)
        def sched(ch, a=False, b=False, c=False):
            calls.append((ch, a, b, c))
            return {"mode": "Video", "file": "/m/a.mkv", "seek": 100.0, "duration": 1500.0, "block": "Morning", "interior_cut": False}
        ns = {"app_state": {}, "time": time, "log": logging.getLogger("t"), "db": None, "_log_warn_throttled": lambda *a, **k: None,
              "broadcast_clock": types.SimpleNamespace(now=lambda: types.SimpleNamespace(timestamp=lambda: clock[0], toordinal=lambda: 1)),
              "_scheduler_playback_state": sched, "_hub_miss_logged": {}, "threading": threading,
              "_screen_scheduler_answers": {}, "SCREEN_SCHEDULER_ASK_GAP_S": 0.5, "_log_swallowed": lambda *a: None,
              "_scheduler_prepared": {}}
        import sys
        sys.modules.setdefault("media_library", __import__("media_library"))
        for name in ("_hub_playback_guard", "calculate_slotted_playback_state", "_hub_miss_log_once", "_hub_remember_state", "_screen_scheduler_answer"):
            exec(get_function_source(name), ns)
        exec(STATION_DOOR_SRC, ns)
        _door = ns["calculate_slotted_playback_state"]

        def _off_screen(*a, **k):
            out = []
            t = threading.Thread(target=lambda: out.append(_door(*a, **k)))
            t.start()
            t.join()
            return out[0]
        ns["calculate_slotted_playback_state"] = _off_screen
        return ns, hub, ml

    def test_hit_is_clock_math_and_miss_asks_the_scheduler(self):
        import media_library
        calls, clock = [], [1000.0]
        ns, hub, ml = self._ns(calls, clock)
        orig = media_library.shared_schedule_hub
        media_library.shared_schedule_hub = lambda: hub
        try:
            ns["calculate_slotted_playback_state"]("05")
            self.assertEqual(len(calls), 1)
            clock[0] = 1030.0
            second = ns["calculate_slotted_playback_state"]("05")
            self.assertEqual(len(calls), 1, "the hub answered without the scheduler")
            self.assertAlmostEqual(second["seek"], 130.0)
            clock[0] = 1030.0
            ns["calculate_slotted_playback_state"]("05", snap_internal_advance=True)
            self.assertEqual(len(calls), 1, "an advance reads the hub too (owner 2026-11-21: prepared, never looked up at the last minute)")
            ns["calculate_slotted_playback_state"]("05", trust_recent_stop=True)
            self.assertEqual(len(calls), 2, "a recent-stop request reaches the scheduler, which reads the player")
            clock[0] = 1000.0 + 1500.0
            ns["calculate_slotted_playback_state"]("05")
            self.assertEqual(len(calls), 3, "when the show runs out with nothing prepared the hub asks the scheduler again")
        finally:
            media_library.shared_schedule_hub = orig

    def test_static_answers_are_never_kept(self):
        import media_library
        calls, clock = [], [1000.0]
        ns, hub, ml = self._ns(calls, clock)
        ns["_scheduler_playback_state"] = lambda ch, *a: (calls.append(ch), {"mode": "Static", "file": "", "seek": 0, "reason": "not_scanned"})[1]
        orig = media_library.shared_schedule_hub
        media_library.shared_schedule_hub = lambda: hub
        try:
            for _ in range(2):
                t = threading.Thread(target=ns["calculate_slotted_playback_state"], args=("05",))
                t.start(); t.join()
            self.assertEqual(len(calls), 2, "off the screen thread every ask reaches the scheduler: the hub keeps no Static")
            self.assertIsNone(hub.show_facts("05", clock[0], None))
        finally:
            media_library.shared_schedule_hub = orig


class TestHubWriterTick(unittest.TestCase):
    """14.10: the scheduler is the hub's writer on its own beat; readers never have to poke it"""

    def test_writer_worker_shape(self):
        src = get_function_source("_hub_writer_worker")
        self.assertIn("_hub_writer_step(_watched)", src)
        self.assertIn("_python_heavy_should_pause()", src)
        self.assertIn("_app_shutting_down.wait(_HUB_WRITER_WATCHED_SECONDS)", src)
        step = get_function_source("_hub_writer_step")
        self.assertIn("_station_playback_state(channel_key, _epoch)", step)
        self.assertIn("_hub_remember_state(", step)
        self.assertIn('name="HubWriter"', MAIN_SRC)

    def test_writer_step_refreshes_the_hubs_record(self):
        import types, media_library
        hub = media_library.ScheduleHub.__new__(media_library.ScheduleHub)
        hub._show_facts, hub._upcoming = {}, {}
        calls = []
        ns = {"broadcast_clock": types.SimpleNamespace(now=lambda: types.SimpleNamespace(timestamp=lambda: 500.0, toordinal=lambda: 1)),
              "_scheduler_playback_state": lambda ch: (calls.append(ch), {"mode": "Video", "file": "/m/a.mkv", "seek": 10.0, "duration": 1500.0})[1],
              "_hub_playback_guard": lambda ch: ("g",), "_log_warn_throttled": lambda *a, **k: None, "time": __import__("time"), "_hub_writer_checked": {},
              "_scheduler_prepared": {}, "_warm_open_facts": lambda *a: None, "OPEN_FACTS_WARM_ITEMS": 4,
              "_hub_writer_item_ends": {}, "_hub_writer_redo": {"05"}}
        for name in ("_hub_remember_state", "_airing_item_end_epoch", "_hub_writer_step"):
            exec(get_function_source(name), ns)
        exec(STATION_DOOR_SRC, ns)
        ns["_mark_server_rows_progress"] = lambda *a: None
        ns["_hub_channel_key"] = lambda ch: str(ch).zfill(2)
        orig = media_library.shared_schedule_hub
        media_library.shared_schedule_hub = lambda: hub
        try:
            ns["_hub_writer_step"]("05")
        finally:
            media_library.shared_schedule_hub = orig
        self.assertEqual(calls, ["05"])
        self.assertAlmostEqual(hub.show_facts("05", 530.0, ("g",))["seek"], 40.0)
        self.assertEqual(ns["_hub_writer_item_ends"]["05"], 500.0 + 1490.0, "the pass keeps when the item on air ends")
        self.assertEqual(ns["_hub_writer_redo"], set(), "the pass is the one a changed state asked for")


class TestHubWriterSkipsValidChannels(unittest.TestCase):
    """The writer's pass over the other channels skips a channel whose kept record is still right"""

    def test_next_stale_skips_valid_and_recently_checked(self):
        import types, media_library
        hub = media_library.ScheduleHub.__new__(media_library.ScheduleHub)
        hub._show_facts, hub._upcoming = {}, {}
        hub.remember_show_facts("06", {"mode": "Video", "file": "x", "seek": 0.0, "duration": 1500.0}, 100.0, ("g",))
        import time
        ns = {"time": time, "db": types.SimpleNamespace(channels_db={c: {"active": True} for c in ("05", "06", "07", "08")}),
              "broadcast_clock": types.SimpleNamespace(now=lambda: types.SimpleNamespace(timestamp=lambda: 200.0)),
              "_hub_playback_guard": lambda ch: ("g",), "_hub_writer_checked": {"07": time.monotonic()},
              "_HUB_WRITER_STATIC_RECHECK_SECONDS": 60.0, "_hub_writer_item_ends": {}, "_hub_writer_redo": set()}
        exec(get_function_source("_hub_writer_next_stale"), ns)
        orig = media_library.shared_schedule_hub
        media_library.shared_schedule_hub = lambda: hub
        try:
            chans = ["05", "06", "07", "08"]
            self.assertEqual(ns["_hub_writer_next_stale"](chans, 0), "08", "06 has a valid record and 07 was just checked")
            hub.remember_show_facts("08", {"mode": "Video", "file": "x", "seek": 0.0, "duration": 1500.0}, 100.0, ("g",))
            hub.remember_show_facts("05", {"mode": "Video", "file": "x", "seek": 0.0, "duration": 1500.0}, 100.0, ("g",))
            self.assertIsNone(ns["_hub_writer_next_stale"](chans, 0), "every channel is up to date")
        finally:
            media_library.shared_schedule_hub = orig


class TestEveryChannelIsWorkedOutAgainWhenItsItemEnds(unittest.TestCase):
    """Owner 2026-11-24: "the show that is on, needs to be updated in cache as soon as it ends so that i dont load the wrong show. stay on schedule all the time"; a tune to channel 06 opened the show kept from before the server's state came and the scheduler swapped it 15 s later."""

    def _hub(self):
        import media_library
        hub = media_library.ScheduleHub.__new__(media_library.ScheduleHub)
        hub._show_facts, hub._upcoming = {}, {}
        hub.remember_show_facts("06", {"mode": "Video", "file": "/m/old.mp4", "seek": 0.0, "duration": 5000.0}, 100.0, ("g",))
        hub.remember_show_facts("07", {"mode": "Video", "file": "/m/x.mp4", "seek": 0.0, "duration": 5000.0}, 100.0, ("g",))
        return hub

    def _ns(self, hub, **extra):
        import types, time
        ns = {"time": time, "db": types.SimpleNamespace(channels_db={c: {"active": True} for c in ("06", "07")}),
              "broadcast_clock": types.SimpleNamespace(now=lambda: types.SimpleNamespace(timestamp=lambda: 200.0)),
              "_hub_playback_guard": lambda ch: ("g",), "_hub_writer_checked": {"06": time.monotonic(), "07": time.monotonic()},
              "_HUB_WRITER_STATIC_RECHECK_SECONDS": 60.0, "_hub_writer_item_ends": {"06": 5100.0, "07": 5100.0}, "_hub_writer_redo": set(),
              "_screen_scheduler_answers": {"06": {"state": {}}, "07": {"state": {}}}, "app_state": {"current_channel": "07"}}
        ns.update(extra)
        for name in ("_hub_writer_next_stale", "_hub_schedule_inputs_changed"):
            exec(get_function_source(name), ns)
        return ns

    def _with(self, hub, fn):
        import media_library
        orig = media_library.shared_schedule_hub
        media_library.shared_schedule_hub = lambda: hub
        try:
            return fn()
        finally:
            media_library.shared_schedule_hub = orig

    def test_a_channel_whose_item_ended_is_due_at_once_even_inside_the_recheck_gap(self):
        hub = self._hub()
        ns = self._ns(hub)
        self.assertIsNone(self._with(hub, lambda: ns["_hub_writer_next_stale"](["06", "07"], 0)), "both were just checked and their items are on")
        ns["_hub_writer_item_ends"]["06"] = 150.0
        self.assertEqual(self._with(hub, lambda: ns["_hub_writer_next_stale"](["06", "07"], 1)), "06", "its item ended, so it is worked out again now")

    def test_a_changed_state_drops_the_kept_show_off_screen_and_asks_for_a_pass(self):
        hub = self._hub()
        ns = self._ns(hub)
        self._with(hub, lambda: ns["_hub_schedule_inputs_changed"](["06", "07"]))
        self.assertIsNone(hub.show_facts("06", 200.0, ("g",)), "a tune before the pass waits for the scheduler, it never opens the old show")
        self.assertNotIn("06", ns["_screen_scheduler_answers"])
        self.assertIsNotNone(hub.show_facts("07", 200.0, ("g",)), "the channel on screen keeps its show; the writer works it out every beat")
        self.assertEqual(ns["_hub_writer_redo"], {"06", "07"})
        self.assertEqual(self._with(hub, lambda: ns["_hub_writer_next_stale"](["06", "07"], 1)), "06")

    def test_the_servers_state_is_compared_before_and_after_it_is_applied(self):
        body = MAIN_SRC[MAIN_SRC.index("    def _apply_remote_schedule_message(message):"):]
        body = body[:body.index("    def _forget_a_replaced_server(message):")]
        self.assertLess(body.index("_held_before = {"), body.index("db.apply_remote_schedule("))
        self.assertIn("_hub_schedule_inputs_changed([_ch for _ch, _rec in list(db.channels_db.items()) if _channel_record_signature(_rec) != _held_before.get(_ch)])", body)


