class TestTheFirstShowGetsAllThreeScansAhead(unittest.TestCase):
    """Owner 2026-11-20: the first pass of new media gets length, picture box and loudness accelerated; the loudness starts at priority right after the other two, on its own thread, and is not started twice."""

    def _ns(self, gain=None, streamed=False):
        calls = []
        ns = {"os": os, "time": time, "threading": types.SimpleNamespace(Thread=lambda target, **kw: types.SimpleNamespace(start=target)),
              "log": logging.getLogger("t"), "_loudness_priming_lock": threading.Lock(), "_loudness_priming_inflight": set(),
              "_channel_is_server_streamed": lambda ch: streamed, "_read_file_probe_facts": lambda p: {"gain": gain},
              "_loudness_probe_in_cooldown": lambda p: False, "_mark_loudness_priority_active": lambda: calls.append("on"),
              "_mark_loudness_priority_done": lambda: calls.append("off"),
              "_probe_and_apply_loudness_blocking": lambda *a, **k: calls.append((a, k)) or 1.5}
        exec(get_function_source("_first_show_loudness"), ns)
        return ns, calls

    def test_the_scan_runs_at_priority_once(self):
        ns, calls = self._ns()
        ns["_first_show_loudness"]("05", "Full Day", "/m/show.mkv")
        self.assertEqual(calls[0], "on")
        self.assertEqual(calls[1], (("channel", "05", "Full Day", os.path.normpath("/m/show.mkv"), "new channel first show"), {"priority": True}))
        self.assertEqual(calls[2], "off")
        self.assertEqual(ns["_loudness_priming_inflight"], set())
        ns["_loudness_priming_inflight"].add(("05", os.path.normpath("/m/show.mkv")))
        ns["_first_show_loudness"]("05", "Full Day", "/m/show.mkv")
        self.assertEqual(len(calls), 3, "a scan already running for the file is not started again")

    def test_nothing_is_scanned_with_a_gain_or_on_a_streamed_channel(self):
        for ns, calls in (self._ns(gain=1.2), self._ns(streamed=True)):
            ns["_first_show_loudness"]("05", "Full Day", "/m/show.mkv")
            self.assertEqual(calls, [])

    def test_the_first_show_worker_starts_it_after_length_and_picture_box(self):
        worker = MAIN_SRC[MAIN_SRC.index("first show %s scanned ahead of the other scans"):][:600]
        self.assertIn("_first_show_loudness(_ch, _block, _path)", worker)


class TestVlcWritesItsOwnLogAndAThreadReadsIt(unittest.TestCase):
    """Owner 2026-11-20: VLC's opening thread waited for Python's turn on each of about 400 log lines per channel change; VLC writes its own log file for every engine (main and DVD, so every kind of playback), VlcLogReader reads it on its own thread and feeds the same queue as before."""

    def _ns(self, folder):
        lines = queue.Queue()
        ns = {"os": os, "queue": queue, "threading": threading, "time": time, "_vlc_log_queue": lines,
              "VLC_DEBUG_LOG_PATH": os.path.join(folder, "vlc-debug.log"), "_log_output_dir": lambda: folder,
              "_vlc_native_logs": {}, "_vlc_native_logs_lock": threading.Lock(), "_VLC_NATIVE_LOG_MAX_BYTES": 400,
              "broadcast_clock": types.SimpleNamespace(now=lambda: datetime.datetime(2026, 11, 20, 12, 3, 0, 123000)),
              "_log_swallowed": lambda *a: None, "_log_warn_throttled": lambda *a: None}
        for name in ("_vlc_native_log_args", "_vlc_native_log_read"):
            exec(main_function_code(name), ns)
        return ns, lines

    def test_lines_are_read_whole_stamped_and_old_runs_are_skipped(self):
        with tempfile.TemporaryDirectory() as folder:
            os.makedirs(os.path.join(folder, "temp"))
            path = os.path.join(folder, "temp", "vlc-native-main.log")
            with open(path, "wb") as fh:
                fh.write(b"main debug: from the run before\n")
            ns, lines = self._ns(folder)
            args = ns["_vlc_native_log_args"]("main")
            self.assertEqual(args, ["--file-logging", "--logfile=" + path, "--log-verbose=2"])
            state = ns["_vlc_native_logs"][path]
            with open(path, "ab") as fh:
                fh.write(b'main debug: Creating an input for \'show.mp4\'\r\nmain debug: using demux mod')
            ns["_vlc_native_log_read"](path, state)
            got = [lines.get_nowait() for _ in range(lines.qsize())]
            self.assertEqual(got, ["[12:03:00.123] main debug: Creating an input for 'show.mp4'"])
            with open(path, "ab") as fh:
                fh.write(b'ule "mp4"\n' + b"x" * 500 + b"\n")
            ns["_vlc_native_log_read"](path, state)
            got = [lines.get_nowait() for _ in range(lines.qsize())]
            self.assertEqual(got[0], '[12:03:00.123] main debug: using demux module "mp4"')
            self.assertEqual(os.path.getsize(path), 0, "past the size limit the file is emptied")
            self.assertEqual(state["offset"], 0)
            with open(path, "ab") as fh:
                fh.write(b"main warning: buffer too late (5 us): dropped\n")
            ns["_vlc_native_log_read"](path, state)
            self.assertEqual(lines.get_nowait(), "[12:03:00.123] main warning: buffer too late (5 us): dropped")

    def test_every_engine_logs_to_its_own_file_and_no_python_runs_in_vlc(self):
        self.assertNotIn("log_set(", MAIN_SRC)
        self.assertNotIn("vsnprintf", MAIN_SRC)
        self.assertIn('_vlc_base_args_dvd = [a for a in vlc_args if not a.startswith("--avcodec-hw")] + ["--avcodec-hw=none"] + _vlc_native_log_args("dvd")', MAIN_SRC)
        self.assertIn('vlc_args = vlc_args + _vlc_native_log_args("main")', MAIN_SRC)
        self.assertIn("_new_main_args = list(_vlc_base_args_main or [])", MAIN_SRC, "an engine rebuilt for a setting keeps its log")
