        self.assertEqual(first_incident, [True] * gov.SURFACE_LOCK_SWAPS_MAX + [False] * 3, "within one incident the repairs run out as before")
        self.assertEqual(len(finds), 1)
        clock[0] += gov.SURFACE_LOCK_INCIDENT_GAP_SECONDS + 1
