    def test_the_watermark_is_picked_then_the_channels_folder_then_the_one_default(self):
        import sys, tempfile
        sys.path.insert(0, os.path.join(SCRIPTS, "server"))
        import server_sync as ss
        with tempfile.TemporaryDirectory() as root:
            def put(*parts):
                path = os.path.join(root, *parts)
                os.makedirs(os.path.dirname(path), exist_ok=True)
                open(path, "wb").write(b"x")
                return path
            self.assertEqual(ss.watermark_file_for("12", "", root), ("", ""), "nothing anywhere: none")
            default = put("default", "watermark.png")
            self.assertEqual(ss.watermark_file_for("12", "", root), (default, "default"), "one default for every channel")
            b = put("Channel 12", "b.png")
            a = put("Channel 12", "a.png")
            self.assertEqual(ss.watermark_file_for("12", "", root)[1], "folder")
            self.assertEqual(ss.watermark_file_for("13", "", root), (default, "default"), "another channel still has the default")
            named = sorted([a, b], key=lambda x: os.path.basename(x).lower())[0]
            self.assertEqual(ss.watermark_file_for("12", "", root)[0], named, "several in the folder: the first by name")
            mine = put("elsewhere", "mine.png")
            self.assertEqual(ss.watermark_file_for("12", mine, root), (mine, "picked"), "the Add button pick wins over the folder")
            put("Channel 12", "0000-later.png")
            self.assertEqual(ss.watermark_file_for("12", mine, root), (mine, "picked"), "files added to the folder later do not take it back")
            self.assertEqual(ss.watermark_file_for("12", os.path.join(root, "gone.png"), root)[1], "folder", "a pick whose file is gone falls back")
            legacy = put("watermark.png")
            self.assertEqual(ss.watermark_file_for("13", legacy, root), (default, "default"), "the older default path stored in a record is not a pick")
            self.assertEqual(ss.watermark_file_for("13", default, root), (default, "default"))

