        self.assertEqual(ml._bi_frame_text_bands(frame), [])
        # WARNING: owner 2026-11-17: text that comes into the search area from either side and is not centred is a logo overlapping, so it is not a subtitle.
        from_left = TestBurnedInScanLogsItsReason()._frame(ml, [(int(h * 0.88), int(h * 0.93), int(w * 0.01), int(w * 0.55))])
