    check(ns["_audio_track_rows"]([(2, "Track 2 - [English]")], [{"lang": "eng", "desc": "x"}])[0][1] == "Track 2 - [English]",
          "a label that already names its language is shown as VLC gives it")
    src = read(MAIN_SCRIPT)
