class TestThemeColourHasEveryHueAndTheButtonsTurnAway(unittest.TestCase):
    """Owner 2026-11-21: the border/text colour slider has every hue again; the blue menu buttons turn inside the blue to stay a safe distance from it, jumping to the far side when it crosses their resting hue."""

    def test_the_slider_steps_through_every_hue(self):
        config, seen = {"theme_ui_hue": 0}, []
        for _ in range(80):
            mn.slider_adjust(config, "ui_hue", mn.RIGHT)
            seen.append(config["theme_ui_hue"])
        self.assertEqual(seen[:72], list(range(5, 365, 5)))
        self.assertEqual(seen[-1], 360)
        self.assertIn(215, seen)

    def test_the_track_draws_every_hue_and_a_saved_blue_is_kept(self):
        ui_text = read(_script("ui.py"))
        self.assertNotIn("_cached_ui_gradient_surf", ui_text)
        self.assertIn("ui_knob_x = slider_x + int((ui_hue / 360.0) * slider_width)", ui_text)
        self.assertNotIn("theme_ui_hue_clear", read(_script("media.py")))
        self.assertFalse(hasattr(gov, "THEME_UI_HUE_SKIP_LOW"))

    def test_every_colour_of_button_keeps_the_safe_gap_from_every_hue(self):
        import ui
        rests, gap = gov.THEME_BUTTON_FAMILY_REST, gov.THEME_BUTTON_HUE_SAFE_GAP
        self.assertEqual((ui.THEME_BUTTON_FAMILY_REST, ui.THEME_BUTTON_HUE_SAFE_GAP), (rests, gap))
        self.assertEqual(set(rests), set(ui._BUTTON_FAMILIES))
        for family, rest in rests.items():
            for tenth in range(0, 3600, 7):
                hue = tenth / 10.0
                shift = ui.theme_button_hue_shift(hue, rest)
                apart = abs(((hue - (rest + shift) + 180) % 360) - 180)
                self.assertGreaterEqual(apart + 1e-9, gap, (family, hue))
                self.assertLessEqual(abs(shift), gap, (family, hue))
        self.assertEqual(ui.theme_button_hue_shift(140, 218), 0, "far from blue: plain button blue")
        self.assertEqual(gap, 60, "owner 2026-11-23: the highlight stands well apart from the buttons")
        self.assertEqual((gov.SELECTION_BORDER_WIDTH, media.SELECTION_BORDER_WIDTH, ui.SELECTION_BORDER_WIDTH), (5, 5, 5), "owner 2026-11-23: the highlight is drawn thicker")
        self.assertIn("else 5", [l for l in read(_script("media.py")).splitlines() if l.startswith("SELECTION_BORDER_WIDTH =")][0])
        self.assertEqual(ui.theme_button_hue_shift(208, 218), gap - 10, "a highlight just under pushes the buttons up")
        self.assertEqual(ui.theme_button_hue_shift(218, 218), -gap, "the jump at the resting hue")
        self.assertEqual(ui.theme_button_hue_shift(4, 354), -(gap - 10), "red wraps past 360")

    def test_each_rest_is_the_hue_of_its_buttons(self):
        import ui, colorsys
        for family, names in ui._BUTTON_FAMILIES.items():
            for name in names:
                h = colorsys.rgb_to_hsv(*[c / 255.0 for c in ui._BUTTON_BASE[name]])[0] * 360
                self.assertLess(abs(((h - gov.THEME_BUTTON_FAMILY_REST[family]) + 180) % 360 - 180), 12, name)

    def test_the_colours_follow_the_shift_and_come_back(self):
        import ui, colorsys
        base = dict(ui._BUTTON_BASE)
        try:
            for family, names in ui._BUTTON_FAMILIES.items():
                ui.sync_button_colors(100 if family != "green" else 300)
                ui.sync_button_colors(gov.THEME_BUTTON_FAMILY_REST[family] + 5)
                for name in names:
                    h0, s0, v0 = colorsys.rgb_to_hsv(*[c / 255.0 for c in base[name]])
                    h1, s1, v1 = colorsys.rgb_to_hsv(*[c / 255.0 for c in getattr(ui, name)])
                    self.assertAlmostEqual(((h1 - h0) * 360 + 180) % 360 - 180, -(gov.THEME_BUTTON_HUE_SAFE_GAP - 5), delta=2.5, msg=name)
                    self.assertAlmostEqual(v1, v0, delta=0.01)
            ui.sync_button_colors(gov.THEME_BUTTON_FAMILY_REST["blue"] + 5)
            self.assertEqual(ui._system_row_color("send_logs", None), ui.COLOR_MENU_BUTTON_BLUE)
            self.assertNotEqual(ui.COLOR_MENU_BUTTON_BLUE, base["COLOR_MENU_BUTTON_BLUE"])
            self.assertEqual(ui._system_row_color("exit_program", "red"), "red")
            self.assertEqual(ui.COLOR_BUTTON_CLOSE, base["COLOR_BUTTON_CLOSE"], "red is far from blue and stays")
        finally:
            ui.sync_button_colors(290)
        ui.sync_button_colors(290)
        for name in ui._BUTTON_BASE:
            self.assertEqual(getattr(ui, name), base[name], name)

    def test_the_main_loop_sets_them_every_frame(self):
        self.assertIn('ui.sync_button_colors(db.config.get("theme_ui_hue", 140))', MAIN_SRC)

    def test_every_yes_no_popup_is_the_shared_one_with_the_theme_border(self):
        ui_text = read(_script("ui.py"))
        body = ui_text[ui_text.index("def draw_popup_yes_no("):]
        body = body[:body.index("\n\n\n")]
        self.assertNotIn("COLOR_TEXT_WHITE", body.split('"""')[2])
        deck = read(_script("game_deck.py"))
        self.assertEqual(deck.count("_ui.draw_popup_yes_no(screen, cx, btn_y, self."), 3)
        for name in ("COLOR_BUTTON_YES", "COLOR_BUTTON_NO", "COLOR_BUTTON_CLOSE", "COLOR_GAME_SWITCH_ON", "COLOR_GAME_SWITCH_OFF",
                     "COLOR_GAME_OFF_RED", "COLOR_GAME_PLAYER_BOX_ARMED", "COLOR_GAME_VALUE_BOX_ACTIVE"):
            self.assertNotIn("_gov." + name, deck)
        self.assertEqual(deck.count("import ui as _ui"), 1)


class TestClipEndingBeforeItsSlotWaits(unittest.TestCase):
    """Owner 2026-11-09: commercials start on their second, play whole, and nothing is reopened at the end; a clip that ends a little before its slot waits, and the next item opens at its first second."""

    def _guard(self):
        ns = {"os": os, "SCHEDULER_REPEAT_GUARD_SECONDS": 60, "SCHEDULER_REPEAT_GUARD_WINDOW_SECONDS": 900, "SLOT_TAIL_HOLD_MAX_SECONDS": 3.0}
        exec(compile(get_function_source("_apply_repeat_guard"), "<extracted:_apply_repeat_guard>", "exec"), ns)
        return ns["_apply_repeat_guard"]

    def _timeline(self):
        return [{"path": "A", "start_time": 0.0, "duration": 164, "is_commercial": True},
                {"path": "B", "start_time": 164.0, "duration": 32, "is_commercial": True},
                {"path": "C", "start_time": 196.0, "duration": 30, "is_commercial": True}]

    def _armed(self, file_name):
        now = datetime.datetime(2026, 11, 9, 4, 0, 0)
        return now, {"last_ended_commercial": {"file": file_name, "block": "Full Day", "armed_ts": now.timestamp()}}

    def test_the_repeat_guard_lands_on_the_next_items_first_second(self):
        now, log_ = self._armed("a")
        show, position = self._guard()("05", log_, "Full Day", self._timeline(), 226, 163.5, now)
        self.assertEqual((show["path"], position), ("B", 164.0))

    def test_a_short_clip_found_in_its_last_seconds_is_not_reopened(self):
        now, log_ = self._armed("b")
        show, position = self._guard()("05", log_, "Full Day", self._timeline(), 226, 194.66, now)
        self.assertEqual((show["path"], position), ("C", 196.0))

    def test_a_clip_with_more_than_the_tail_left_is_left_alone(self):
        now, log_ = self._armed("b")
        show, position = self._guard()("05", log_, "Full Day", self._timeline(), 226, 190.0, now)
        self.assertEqual((show["path"], position), ("B", 190.0))

    def test_the_numbers_are_in_the_governor(self):
        self.assertEqual((gov.SLOT_TAIL_HOLD_MAX_SECONDS, gov.SLOT_START_GRACE_SECONDS), (3.0, 0.3))
        self.assertFalse(hasattr(gov, "SLOT_OPEN_LEAD_SECONDS"), "owner 2026-11-23: the tail is held to the slot's end, never ended early")

    def test_the_hold_asks_the_schedule_before_the_guard_is_armed_and_ends_on_the_clock(self):
        text = read(os.path.join(ROOT, "retro_tv_emulator.py"))
        peek = text.index("_peek = calculate_slotted_playback_state(ch, snap_internal_advance=True)")
        self.assertIn("0 < _peek_left <= SLOT_TAIL_HOLD_MAX_SECONDS", text[peek:peek + 900])
        self.assertLess(peek, text.index("_guard_key = \"last_ended_commercial\" if _anchor.get(\"mode\")"))
        hold = text.index("_tail_hold = app_state.get(\"_slot_tail_hold\")")
        self.assertIn("broadcast_clock.now().timestamp() < _tail_hold.get(\"until\", 0)", text[hold:hold + 600])
        self.assertIn("_tail_hold_just_ended = True", text[hold:hold + 900])
        self.assertIn("and not _tail_hold_active", text[hold:hold + 1200])
        self.assertLess(hold, text.index("change_channel(ch, is_surfing=False, internal_advance=True, snap_internal_advance=is_video_finished)"))

    def test_an_item_found_just_inside_its_slot_starts_at_its_first_second(self):
        text = read(os.path.join(ROOT, "retro_tv_emulator.py"))
        start = text.index("if 0 < _into_slot <= _SLOT_START_GRACE_S:")
        self.assertIn("t_state[\"seek\"] = float(t_state.get(\"seek\") or 0) - _into_slot", text[start:start + 200])
        self.assertIn("if internal_advance and t_state.get(\"mode\") in (\"Video\", \"Commercial\")", text[start - 400:start])


class TestEveryGovernorNameIsDefined(unittest.TestCase):
    """Owner 2026-11-08: a script that reads a performance_governor.py number that no longer exists crashed the app at start, so every name any script reads from it must exist there."""

    def test_no_script_reads_a_governor_name_that_is_missing(self):
        import re as _re
        names = set(_re.findall(r"^([A-Za-z_]\w*)\s*=|^def (\w+)|^class (\w+)", open(_script("performance_governor.py"), encoding="utf-8").read(), _re.M))
        defined = {n for group in names for n in group if n}
        missing = []
        for folder in ("", "assets", "GPU", "server", "updater", "pipeline", "profile", "media"):
            path = os.path.join(ROOT, folder)
            for name in (sorted(os.listdir(path)) if os.path.isdir(path) else []):
                if not name.endswith(".py") or name == "performance_governor.py":
                    continue
                text = open(os.path.join(path, name), encoding="utf-8").read()
                for node in ast.walk(ast.parse(text)):
                    if (isinstance(node, ast.Attribute) and isinstance(node.value, ast.Name)
                            and node.value.id in ("performance_governor", "_governor", "_perf_governor")
                            and node.attr not in defined):
                        missing.append("%s: %s" % (name, node.attr))
        self.assertEqual(missing, [])


