class TestAllSettingsTurnsOnSticksAndSyncsProfiles(unittest.TestCase):
    """Owner 2026-11-07: with All Settings on, changing the L-STICK AS D-PAD switch changes it on every console (turning All Settings on changes nothing by itself), and a profile pick goes to every console"""

    def test_all_settings_applies_a_stick_change_to_every_console(self):
        import json
        import tempfile
        import game_deck as gd
        with tempfile.TemporaryDirectory() as tmp:
            path = os.path.join(tmp, "emulator_config.json")
            with open(path, "w", encoding="utf-8") as handle:
                json.dump({"SNES_mapping": {"stick_as_dpad": False}, "SNES_mapping_p2": {"stick_as_dpad": False}}, handle)
            deck = gd.ExternalGameDeck.__new__(gd.ExternalGameDeck)
            deck._gameplay_ctrl_mapping_cache = {"SNES": {1: object()}}
            deck.ctrl_mapping = {"stick_as_dpad": False}
            deck._active_mapping_console = "SNES"
            original = gd.resolve_emulator_config_path
            gd.resolve_emulator_config_path = lambda: path
            try:
                deck.set_stick_as_dpad_everywhere(True)
            finally:
                gd.resolve_emulator_config_path = original
            with open(path, "r", encoding="utf-8") as handle:
                saved = json.load(handle)
        for console in gd.CONSOLE_ORDER:
            if console in ("DVD", "N64"):
                self.assertNotIn(gd.ExternalGameDeck._mapping_key(console, 1), saved if console == "DVD" else {}, console)
                continue
            for player in range(1, gd.CONSOLE_MAX_PLAYERS.get(console, 4) + 1):
                self.assertTrue(saved[gd.ExternalGameDeck._mapping_key(console, player)]["stick_as_dpad"], (console, player))
        self.assertNotIn("N64_mapping", saved, "N64 has no such switch")
        self.assertTrue(saved["GBA_mapping"]["stick_as_dpad"])
        self.assertTrue(deck.ctrl_mapping["stick_as_dpad"])
        self.assertEqual(deck._gameplay_ctrl_mapping_cache, {})
        self.assertIn("game_deck.set_stick_as_dpad_everywhere(", MAIN_SRC)
        self.assertNotIn("turn_on_stick_as_dpad_everywhere", MAIN_SRC)
        _toggle = get_function_source("_toggle_all_profiles")
        self.assertNotIn("stick_as_dpad", _toggle, "switching All Settings on changes no stick switch by itself")

    def test_a_profile_pick_goes_to_every_console_while_all_settings_is_on(self):
        self.assertIn("_targets = [c for c in CONSOLE_ORDER if c != \"MENU\"] if db.config.get(\"all_profiles_sync\", False) else [con]", MAIN_SRC)
        self.assertIn("game_deck.sync_profile_from_db(_target, db.config)", MAIN_SRC)

















class TestScreenThreadFirstLookAtALocalPath(unittest.TestCase):
    """Owner log 2026-11-10 18:07: a drive that answered slowly froze the picture 24 s, the screen thread probing new paths one after another."""

    def setUp(self):
        import media
        self.media = media
        self.paths = ["/slow/drive/a%d.mkv" % i for i in range(6)]
        self.saved_roots = dict(media._screen_thread_slow_roots)
        media._screen_thread_slow_roots.clear()
        for p in self.paths:
            media._path_exists_cache.pop(p, None)
            media._path_refresh_queue.pop(p, None)

    def tearDown(self):
        m = self.media
        m._screen_thread_slow_roots.clear()
        m._screen_thread_slow_roots.update(self.saved_roots)
        for p in self.paths:
            m._path_exists_cache.pop(p, None)
            m._path_refresh_queue.pop(p, None)

    def test_a_drive_that_answers_gives_the_true_answer(self):
        m = self.media
        with patch.object(m.os.path, "exists", lambda p: p.endswith("a0.mkv")):
            self.assertEqual(m._path_status(self.paths[0]), m.PATH_PRESENT)
            self.assertEqual(m._path_status(self.paths[1]), m.PATH_MISSING)

    def test_a_drive_that_does_not_answer_costs_one_short_wait_not_one_per_path(self):
        m = self.media
        release = threading.Event()
        started = time.monotonic()
        with patch.object(m.os.path, "exists", lambda p: release.wait(30) or True):
            answers = [m._path_status(p) for p in self.paths]
            took = time.monotonic() - started
            release.set()
        self.assertEqual(answers, [m.PATH_UNKNOWN] * len(self.paths))
        self.assertLess(took, 1.0)
        self.assertTrue(all(m._cached_path_exists(p) for p in self.paths))
        for p in self.paths[1:]:
            self.assertIn(p, m._path_refresh_queue)

    def test_the_answer_that_comes_late_is_kept(self):
        m = self.media
        release = threading.Event()
        with patch.object(m.os.path, "exists", lambda p: (release.wait(30), False)[1]):
            self.assertEqual(m._path_status(self.paths[0]), m.PATH_UNKNOWN)
            release.set()
            deadline = time.monotonic() + 5
            while (m._path_exists_cache.get(self.paths[0]) or (None,))[0] != m.PATH_MISSING and time.monotonic() < deadline:
                time.sleep(0.02)
        self.assertEqual(m._path_exists_cache[self.paths[0]][0], m.PATH_MISSING)

    def test_the_numbers_match_the_governor(self):
        import performance_governor as pg
        self.assertEqual(self.media._SCREEN_THREAD_FIRST_LOOK_MS, pg.SCREEN_THREAD_FIRST_LOOK_MS)
        self.assertEqual(self.media._SCREEN_THREAD_SLOW_DRIVE_HOLD_MS, pg.SCREEN_THREAD_SLOW_DRIVE_HOLD_MS)


class TestWindowedLaunchTakesFocusBack(unittest.TestCase):
    """Owner 2026-11-12: launched windowed, the buttons did nothing until the window was clicked; the focus watchdog only ran in fullscreen."""

    def setUp(self):
        with open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8") as f:
            self.src = f.read()

    def test_the_watchdog_runs_in_windowed_mode_for_the_launch_window_only(self):
        i = self.src.index('app_state["_windowed_launch_focus_until_ms"] = now_ticks')
        block = self.src[i:i + 1400]
        self.assertIn('app_state.get("is_fullscreen", False)', block)
        self.assertIn('now_ticks < app_state["_windowed_launch_focus_until_ms"]', block)
