class TestServerServiceRunsOnlyOnce(unittest.TestCase):
    """The detached server service is started once, never once a second (a failed liveness check once started about 150 copies and ran Windows out of memory)."""

    def setUp(self):
        sys.path.insert(0, os.path.join(SCRIPTS, "server"))
        import server_service
        self.ss = server_service
        self.tmp = tempfile.mkdtemp()
        self.ss._last_launch_time = 0.0

    def tearDown(self):
        shutil.rmtree(self.tmp, ignore_errors=True)

    def test_liveness_check_sees_this_process_and_not_a_dead_one(self):
        self.assertTrue(self.ss._pid_alive(os.getpid()))
        self.assertFalse(self.ss._pid_alive(0))
        self.assertFalse(self.ss._pid_alive("x"))
        self.assertFalse(self.ss._pid_alive(99999999))

    def test_windows_liveness_does_not_use_signal_zero(self):
        src = inspect.getsource(self.ss._pid_alive)
        self.assertIn("OpenProcess", src)
        self.assertIn("WaitForSingleObject", src)

    def test_a_second_launch_inside_the_cooldown_starts_nothing(self):
        script = os.path.join(os.path.dirname(self.ss.__file__), "server_service.py")
        with mock.patch.object(self.ss, "_pid_alive", return_value=False), \
             mock.patch.object(self.ss, "set_autostart", return_value=True), \
             mock.patch.object(self.ss, "_service_command", return_value=[sys.executable, script]), \
             mock.patch.object(self.ss.subprocess, "Popen") as popen:
            self.assertTrue(self.ss.ensure_running(self.tmp))
            self.assertTrue(self.ss.ensure_running(self.tmp))
            self.assertTrue(self.ss.ensure_running(self.tmp))
        self.assertEqual(popen.call_count, 1)

    def test_a_running_service_is_not_started_again(self):
        with open(self.ss._pid_path(self.tmp), "w") as fh:
            fh.write(str(os.getpid()))
        with mock.patch.object(self.ss, "set_autostart", return_value=True), \
             mock.patch.object(self.ss.subprocess, "Popen") as popen:
            self.assertTrue(self.ss.ensure_running(self.tmp))
        popen.assert_not_called()

    def test_the_service_claims_a_single_instance_before_it_runs(self):
        src = inspect.getsource(self.ss.run_service)
        self.assertIn("_claim_single_instance", src)
        self.assertLess(src.index("_claim_single_instance"), src.index("_write_pid"))

    def test_cooldown_number_matches_the_governor(self):
        import performance_governor as pg
        self.assertEqual(self.ss.SERVICE_RELAUNCH_COOLDOWN_S, pg.SERVER_SERVICE_RELAUNCH_COOLDOWN_S)


