class TestSaveRetriesWhenFileIsBusy(unittest.TestCase):
    """A save onto a file another program is reading is tried again for a moment instead of being lost."""

    def test_replace_retries_then_succeeds(self):
        import media
        calls = {"n": 0}
        real = os.replace
        tmp = tempfile.mkdtemp()
        src, dst = os.path.join(tmp, "a.tmp"), os.path.join(tmp, "a.json")
        def flaky(a, b):
            if a != src:
                return real(a, b)
            calls["n"] += 1
            if calls["n"] < 3:
                raise PermissionError("busy")
            return real(a, b)
        try:
            open(src, "w").write("x")
            with mock.patch.object(media.os, "replace", flaky), mock.patch.object(media.time, "sleep"):
                media._replace_with_retry(src, dst)
            self.assertEqual(calls["n"], 3)
            self.assertTrue(os.path.exists(dst))
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_replace_gives_up_after_the_last_try(self):
        import media
        with mock.patch.object(media.os, "replace", side_effect=PermissionError("busy")) as rep, mock.patch.object(media.time, "sleep"):
            with self.assertRaises(PermissionError):
                media._replace_with_retry("a", "b")
        self.assertEqual(rep.call_count, media.CONFIG_REPLACE_RETRIES)

    def test_media_fallbacks_match_the_governor(self):
        import media
        import performance_governor as pg
        self.assertEqual(media.CONFIG_REPLACE_RETRIES, pg.CONFIG_REPLACE_RETRIES)
        self.assertEqual(media.CONFIG_REPLACE_RETRY_DELAY_S, pg.CONFIG_REPLACE_RETRY_DELAY_S)


class TestServerMenuFlow(unittest.TestCase):
    """The Server Menu: arrow keys, highlight versus switch, per-server folders, popups and the draw."""

    def _main(self):
        return open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()

    def _move(self, sel, direction):
        return mn.server_menu_move({}, sel, direction)

    def test_arrow_keys_follow_the_picture(self):
        self.assertEqual(self._move(0, mn.DOWN), mn.SERVER_MENU_BOX_BASE)
        self.assertEqual(self._move(mn.SERVER_MENU_BOX_BASE + 2, mn.RIGHT), mn.SERVER_MENU_MANAGE)
        self.assertEqual(self._move(mn.SERVER_MENU_BOX_BASE + 5, mn.RIGHT), mn.SERVER_MENU_RENAME)
        self.assertEqual(self._move(mn.SERVER_MENU_MANAGE, mn.DOWN), mn.SERVER_MENU_RENAME)
        self.assertEqual(self._move(mn.SERVER_MENU_RENAME, mn.DOWN), mn.SERVER_MENU_RESET)
        self.assertEqual(self._move(mn.SERVER_MENU_RESET, mn.DOWN), 1)
        self.assertEqual(self._move(1, mn.DOWN), mn.SERVER_MENU_USER_BASE)
        self.assertEqual(self._move(mn.SERVER_MENU_USER_BASE + 2, mn.RIGHT), mn.SERVER_MENU_SCAN)
        self.assertEqual(self._move(mn.SERVER_MENU_USER_BASE + 5, mn.RIGHT), mn.SERVER_MENU_PICK)
        self.assertEqual(self._move(mn.SERVER_MENU_SCAN, mn.DOWN), mn.SERVER_MENU_PICK)
        self.assertEqual(self._move(mn.SERVER_MENU_PICK, mn.DOWN), mn.SERVER_MENU_CLEAR)
        self.assertEqual(self._move(mn.SERVER_MENU_CLEAR, mn.RIGHT), mn.SERVER_MENU_CLOSE)
        self.assertEqual(self._move(mn.SERVER_MENU_CLOSE, mn.UP), mn.SERVER_MENU_PICK)
        self.assertEqual(self._move(0, mn.UP), 0)

    def test_every_cell_is_reachable_and_nothing_bounces_the_highlight(self):
        cells = [0, 1, 2, 3, 4, 5, 6, 7, 8] + list(range(10, 16)) + list(range(20, 26))
        seen, todo = {0}, [0]
        while todo:
            at = todo.pop()
            for direction in (mn.UP, mn.DOWN, mn.LEFT, mn.RIGHT):
                to = self._move(at, direction)
                self.assertIn(to, cells, (at, direction, to))
                if to not in seen:
                    seen.add(to)
                    todo.append(to)
        self.assertEqual(sorted(seen), sorted(cells))
        for sel in cells:
            self.assertEqual(mn.server_menu_index(mn.server_menu_cell(sel)), sel)

    def test_the_move_does_not_depend_on_the_role_or_the_scan(self):
        import inspect
        self.assertEqual(list(inspect.signature(mn.server_menu_move).parameters), ["app_state", "selection", "direction"])

    def test_enter_on_a_server_box_only_moves_the_dot_and_manage_server_switches(self):
        src = self._main()
        begin = src.index("elif _srv_manage_visible and menu_nav.SERVER_MENU_BOX_BASE <= srv_sel")
        branch = src[begin:src.index("elif _srv_manage_visible and srv_sel == menu_nav.SERVER_MENU_RENAME", begin)]
