class TestChannelButtonsShowAStarterBar(unittest.TestCase):
    """Until the first scan count is published every active channel button shows the shortest bar, so nothing looks like it is not loading."""

    class _Db:
        SERVER_SLOT_IDS = tuple("server%d" % i for i in range(1, 7))
        server_listener = None

        def __init__(self):
            self.config = {"game_channel_enabled": True, "menu_opacity": 85}
            self.channels_db = {"%02d" % n: {"active": n in (5, 6), "name": "x"} for n in range(5, 45)}

        def __getattr__(self, name):
            return None

    def _render(self, ready, progress=None):
        ui._settings_menu_frame_cache.update(key=None, stamp=None)
        surf = pygame.Surface((1152, 864))
        state = {"active_menu_tab": "Channels", "menu_layer": "CHANNEL_LIST", "menu_selection_index": 3, "channels_tab_page": 0,
                 "_channel_scan_progress_ready": ready}
        if progress is not None:
            state["_channel_scan_progress"] = progress
        ui.render_settings_overlay_menu(surf, ui._DEFAULT_THEME, state, self._Db())
        return surf

    @staticmethod
    def _different(a, b):
        return sum(1 for x in range(0, 1152, 2) for y in range(0, 864, 2) if a.get_at((x, y)) != b.get_at((x, y)))

    def test_the_starter_bar_shows_before_the_first_count_and_goes_after_it(self):
        waiting = self._render(False)
        counted_nothing_to_scan = self._render(True, {})
        self.assertGreater(self._different(waiting, counted_nothing_to_scan), 0, "active channels show a bar while waiting")
        self.assertEqual(self._different(counted_nothing_to_scan, self._render(True, {"05": (3, 3)})), 0, "a finished channel and an empty one show no bar")
        self.assertGreater(self._different(self._render(True, {"05": (0, 10)}), counted_nothing_to_scan), 0, "a real count still draws its bar")

    def test_the_count_marks_ready_and_a_new_channel_file_starts_waiting_again(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        publish = src[src.index("def _publish_channel_scan_progress(snap):"):src.index("def _scan_snapshot_worker():")]
        self.assertIn('app_state["_channel_scan_progress_ready"] = True', publish)
        restart = src[src.index("def _restart_playback_after_source_change(reason, restore_channel=False, target_channel=None):"):src.index("def _execute_manage_server():")]
        self.assertIn('app_state["_channel_scan_progress_ready"] = False', restart)
        self.assertIn('app_state["_channel_scan_progress"] = {}', restart)


