class TestServerServiceSurvivesTheAppClosing(unittest.TestCase):
    """The app kills every child in its Windows job when it exits; the service must break away from that job."""

    def setUp(self):
        import server_service
        self.ss = server_service
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, ignore_errors=True)

    def _launch(self, fail_first):
        calls = []
        def fake_popen(cmd, **kw):
            calls.append(kw.get("creationflags"))
            if fail_first and len(calls) == 1:
                raise OSError("access denied")
            return object()
        ss = self.ss
        with mock.patch.object(ss.os, "name", "nt"), \
             mock.patch.object(ss, "_read_pid", return_value=None), \
             mock.patch.object(ss, "set_autostart", return_value=True), \
             mock.patch.object(ss, "_last_launch_time", -1e9), \
             mock.patch.object(ss.subprocess, "Popen", fake_popen), \
             mock.patch.object(ss.os.path, "isfile", return_value=True), \
             mock.patch.object(ss.sys, "frozen", True, create=True):
            ok = ss.ensure_running(self.tmp)
        return ok, calls

    def test_the_launch_breaks_away_from_the_apps_kill_on_close_job(self):
        ok, calls = self._launch(False)
        self.assertTrue(ok)
        self.assertEqual(len(calls), 1)
        self.assertTrue(calls[0] & 0x01000000, "CREATE_BREAKAWAY_FROM_JOB missing")

    def test_if_breakaway_is_refused_the_launch_is_retried_without_it(self):
        ok, calls = self._launch(True)
        self.assertTrue(ok)
        self.assertEqual(len(calls), 2)
        self.assertFalse(calls[1] & 0x01000000)


class TestServerLinkStaysUpAndFilesLiveInLogs(unittest.TestCase):
    def test_the_keepalive_numbers_match_the_governor_and_leave_room(self):
        import performance_governor as pg
        import server_sync
        self.assertEqual(server_sync.SERVER_KEEPALIVE_S, pg.SERVER_KEEPALIVE_S)
        self.assertEqual(server_sync.CLIENT_READ_TIMEOUT_S, pg.CLIENT_READ_TIMEOUT_S)
        self.assertGreaterEqual(pg.CLIENT_READ_TIMEOUT_S, 2 * pg.SERVER_KEEPALIVE_S)

    def test_an_unchanged_schedule_still_reaches_a_user_before_its_read_times_out(self):
        import server_sync
        with tempfile.TemporaryDirectory() as tmp:
            slot = os.path.join(tmp, "retro.config.json")
            with open(slot, "w", encoding="utf-8") as fh:
                json.dump({"channels": {"05": {"schedules": {}}}}, fh)
            import socket
            with socket.socket() as probe:
                probe.bind(("127.0.0.1", 0)); port = probe.getsockname()[1]
            with mock.patch.object(server_sync, "SERVER_KEEPALIVE_S", 0.3), \
                 mock.patch.object(server_sync, "CLIENT_READ_TIMEOUT_S", 3.0):
                b = server_sync.ScheduleBroadcaster(lambda: {"a": slot}, host="127.0.0.1", port=port, poll_interval=0.05)
                got, states = [], []
                b.start()
                c = server_sync.ScheduleClient("127.0.0.1", port=port, slot_id="a",
                                               on_schedule=got.append, on_status=states.append, timeout=1.0)
                c.start()
                try:
                    time.sleep(4.0)
                finally:
                    c.stop(); b.stop()
        self.assertEqual(len(got), 1, "the schedule is applied once, not on every reconnect")
        self.assertNotIn("offline", states)

    def test_every_server_module_writes_to_the_service_log(self):
        """Owner logs 2026-11-24: the caption scan left no line in server_service.log because only server_service's own logger had the file."""
        import subprocess
        with tempfile.TemporaryDirectory() as tmp:
            code = ("import sys, logging; sys.path[:0] = %r; import server_service as ss; ss._configure_logging(%r); "
                    "logging.getLogger('server_captions').info('[CAPTION SCAN] hello'); ss.log.info('[SERVER SERVICE] hi'); "
                    "logging.shutdown()") % ([os.path.join(SCRIPTS, d) for d in ("server", "updater", "assets", "GPU", "pipeline", "profile", "media")] + [os.path.join(ROOT, "tests")], tmp)
            subprocess.run([sys.executable, "-c", code], check=True, timeout=60, cwd=tmp)
            text = open(os.path.join(tmp, "logs", "server_service.log"), encoding="utf-8").read()
        self.assertIn("server_captions: [CAPTION SCAN] hello", text)
        self.assertEqual(text.count("[SERVER SERVICE] hi"), 1)

    def test_the_pid_file_and_the_log_live_in_the_logs_folder_and_old_ones_are_moved(self):
        import server_service as ss
        with tempfile.TemporaryDirectory() as tmp:
            old_pid = os.path.join(tmp, ss.SERVICE_PID_FILENAME)
            old_log = os.path.join(tmp, "server_service.log")
            for p in (old_pid, old_log):
                with open(p, "w") as fh:
                    fh.write("1")
            self.assertEqual(os.path.dirname(ss._pid_path(tmp)), os.path.join(tmp, "logs"))
            ss._tidy_legacy_files(tmp)
            self.assertFalse(os.path.exists(old_pid))
            self.assertFalse(os.path.exists(old_log))
            self.assertTrue(os.path.isfile(os.path.join(tmp, "logs", "server_service.log")))


