class TestMislabeledPackageDoesNotLoopTheUpdate(unittest.TestCase):
    """The V1.5.4 zip carried an exe built as 1.5.3: after installing, it was offered 1.5.4 again at every start."""

    def setUp(self):
        import auto_updater
        self.au = auto_updater
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, ignore_errors=True)
        self.au._stamp_ahead_warned.clear()
        patcher = mock.patch.object(self.au, "_build_info", types.SimpleNamespace(BUILD_VERSION="1.5.3", BUILD_TYPE="Alpha"))
        patcher.start()
        self.addCleanup(patcher.stop)
        env = mock.patch.dict(os.environ, {}, clear=False)
        env.start()
        self.addCleanup(env.stop)
        os.environ.pop("RETRO_TV_VERSION", None)

    def _stamp(self, payload):
        with open(os.path.join(self.tmp, "version.json"), "w", encoding="utf-8") as fh:
            json.dump(payload, fh)

    def test_a_newer_version_recorded_by_the_helper_wins_over_the_number_in_the_exe(self):
        self._stamp({"version": "1.5.4", "build": "Alpha"})
        self.assertEqual(self.au.current_version(self.tmp), "1.5.4")
        self.assertFalse(self.au.version_is_newer("1.5.4", self.au.current_version(self.tmp)))

    def test_the_check_does_not_rewrite_that_stamp_back_to_the_old_number(self):
        self._stamp({"version": "1.5.4", "build": "Alpha"})
        self.au._heal_version_stamp(self.tmp)
        with open(os.path.join(self.tmp, "version.json"), encoding="utf-8") as fh:
            self.assertEqual(json.load(fh)["version"], "1.5.4")

    def test_a_stamp_the_app_wrote_from_its_own_exe_is_never_trusted_over_the_exe(self):
        self._stamp({"version": "1.5.4", "build": "Alpha", "from_exe": True})
        self.assertEqual(self.au.current_version(self.tmp), "1.5.3")

    def test_an_equal_or_older_stamp_changes_nothing_and_the_heal_marks_its_stamp(self):
        self._stamp({"version": "1.5.2"})
        self.assertEqual(self.au.current_version(self.tmp), "1.5.3")
        self.au._heal_version_stamp(self.tmp)
        with open(os.path.join(self.tmp, "version.json"), encoding="utf-8") as fh:
            stamp = json.load(fh)
        self.assertEqual((stamp["version"], stamp.get("from_exe")), ("1.5.3", True))

    def test_the_mistake_is_logged_once_with_the_fix(self):
        self._stamp({"version": "1.5.4"})
        with self.assertLogs(self.au.log, level="WARNING") as captured:
            self.au.current_version(self.tmp)
            self.au.current_version(self.tmp)
        lines = [l for l in captured.output if "wrong number" in l]
        self.assertEqual(len(lines), 1)
        self.assertIn("write_build_info.py 1.5.4", lines[0])








