class TestHolidaysWorkOnAServerProfile(unittest.TestCase):
    """Owner 2026-11-12: holidays interrupt on the server's channels when the server set up a holiday folder, and on a channel this User added to the profile when this User added holiday media; the Watermark Add button is never greyed and its pick is kept for a streamed channel."""

    def _db(self, tmp, server_channels):
        rdb, restore = _settings_writer_db(tmp, 0.05)
        rdb.create_server_slot("Den", "server1")
        with open(rdb.get_server_slot_path("server1"), "w") as f:
            json.dump({"channels": server_channels}, f)
        self.assertTrue(rdb.open_local_profile_as_user("server1"))
        return rdb, restore

    def _tracks(self, info, key="christmas"):
        import media
        tracks, pending = media.holiday_day_tracks(info, key, lambda p: True)
        return list(tracks) + list(pending)

    def test_the_servers_holiday_folder_is_on_its_channel_and_the_users_own_holiday_media_is_on_the_users_channel_and_survives_a_save_and_reopen(self):
        tmp = tempfile.mkdtemp()
        try:
            rdb, restore = self._db(tmp, {
                "05": {"active": True, "schedules": {"Full Day": [{"path": "C:\\a.mp4"}]}, "holiday_schedules": {"christmas": [{"path": "C:\\xmas.mp4"}]},
                       "holiday_playback_log": {"christmas": {"block_key": "k"}}},
                "06": {"active": True, "schedules": {"Full Day": [{"path": "C:\\b.mp4"}]}}})
            self.assertTrue(rdb.channels_db["05"]["server_locked"])
            self.assertTrue(self._tracks(rdb.channels_db["05"]), "the server's holiday folder interrupts on the server's channel")
            self.assertEqual(rdb.channels_db["05"]["holiday_playback_log"], {"christmas": {"block_key": "k"}})
            self.assertFalse(self._tracks(rdb.channels_db["06"]), "no holiday folder on the server, none shown")
            rdb.channels_db["20"]["active"] = True
            rdb.channels_db["20"]["schedules"] = {"Full Day": [{"path": "C:\\mine.mp4"}]}
            rdb.channels_db["20"]["holiday_schedules"] = {"christmas": [{"path": "C:\\mine_xmas.mp4"}]}
            rdb.save_channels(force=True)
            self.assertTrue(self._tracks(rdb.channels_db["20"]))
            rdb.apply_remote_schedule(json.load(open(rdb.get_server_slot_path("server1")))["channels"], None, None, local=True)
            self.assertTrue(self._tracks(rdb.channels_db["20"]), "still there after the server's schedule is applied again")
            self.assertFalse(rdb.channels_db["20"].get("server_locked", False))
            rdb.save_channels(force=True)
            with open(rdb.channels_path) as f:
                mine = json.load(f)["channels"]
            self.assertEqual(mine["20"]["holiday_schedules"]["christmas"][0]["path"], "C:\\mine_xmas.mp4")
            self.assertEqual(mine.get("05", {}).get("holiday_schedules", {}).get("christmas", []), [], "the server's holiday media is not copied into this User's copy")
            self.assertTrue(rdb.open_local_profile_as_user("server1"))
            self.assertTrue(self._tracks(rdb.channels_db["20"]), "back after leaving and opening the profile again")
            self.assertTrue(self._tracks(rdb.channels_db["05"]))
            restore()
        finally:
            shutil.rmtree(tmp, ignore_errors=True)

    def test_a_streamed_channel_shows_the_servers_watermark_and_never_this_pcs_pick(self):
        import threading, base64, tempfile, media
        png = base64.b64encode(b"\x89PNG\r\n\x1a\nfake").decode("ascii")
        tmp = tempfile.mkdtemp()
        real_dir = media.resolve_splash_images_dir
        media.resolve_splash_images_dir = lambda: tmp
        try:
            db = object.__new__(media.RetroDatabase)
            db._remote_schedule_lock = threading.RLock()
            db._remote_schedule_active = False
            db._remote_local_channels_snapshot = None
            db._remote_locked_channels = set()
            db.remote_playback = {}
            db.config = {"server_watermark_overrides": {"05": False}, "server_watermark_paths": {"05": "C:\\logo.png"}}
            db.channels_db = db._build_channels_db({})
            sched = {"Full Day": [{"path": "C:\\a.mp4"}]}
            db.apply_remote_schedule({"05": {"active": True, "schedules": sched, "watermark_enabled": True,
                                             "watermark_image": {"name": "bug.png", "sha": "abc123", "b64": png}}}, server_host="srv")
            rec = db.channels_db["05"]
            self.assertTrue(rec["watermark_enabled"], "the server's switch, not this PC's old pick")
            self.assertTrue(os.path.isfile(rec["watermark_path"]))
            self.assertIn("abc123", rec["watermark_path"])
            with open(rec["watermark_path"], "rb") as fh:
                self.assertEqual(fh.read(), b"\x89PNG\r\n\x1a\nfake")
            db.apply_remote_schedule({"05": {"active": True, "schedules": sched, "watermark_enabled": False}}, server_host="srv")
            self.assertFalse(db.channels_db["05"]["watermark_enabled"], "the server turned it off")
            db.apply_remote_schedule({"05": {"active": True, "schedules": sched, "watermark_enabled": True}}, server_host="srv")
            self.assertFalse(db.channels_db["05"]["watermark_enabled"], "on with no image sent shows nothing")
        finally:
            media.resolve_splash_images_dir = real_dir
            shutil.rmtree(tmp, ignore_errors=True)

    def _stream_one(self, tmp, image, own_default):
        import threading, media
        real_dir = media.resolve_splash_images_dir
        media.resolve_splash_images_dir = lambda: tmp
        try:
            if own_default is not None:
                os.makedirs(os.path.join(tmp, "WATERMARK", "default"), exist_ok=True)
                with open(os.path.join(tmp, "WATERMARK", "default", "watermark.png"), "wb") as fh:
                    fh.write(own_default)
            db = object.__new__(media.RetroDatabase)
            db._remote_schedule_lock = threading.RLock()
            db._remote_schedule_active = False
            db._remote_local_channels_snapshot = None
            db._remote_locked_channels = set()
            db.remote_playback = {}
            db.config = {}
            db.channels_db = db._build_channels_db({})
            incoming = {"active": True, "schedules": {"Full Day": [{"path": "C:\\a.mp4"}]}, "watermark_enabled": True}
            if image is not None:
                incoming["watermark_image"] = image
            db.apply_remote_schedule({"05": incoming}, server_host="srv")
            return db.channels_db["05"], os.path.join(tmp, "WATERMARK", "default", "watermark.png")
        finally:
            media.resolve_splash_images_dir = real_dir

    def test_the_default_watermark_rules(self):
        import base64, tempfile
        default_img = {"name": "watermark.png", "sha": "def0", "b64": base64.b64encode(b"SERVERS-DEFAULT").decode("ascii"), "is_default": True}
        for case in range(4):
            tmp = tempfile.mkdtemp()
            try:
                if case == 0:
                    rec, default = self._stream_one(tmp, default_img, b"MINE")
                    self.assertTrue(rec["watermark_enabled"])
                    self.assertEqual(rec["watermark_path"], default, "the server picked none: this PC's own default is used")
                    with open(default, "rb") as fh:
                        self.assertEqual(fh.read(), b"MINE", "and is not replaced")
                elif case == 1:
                    rec, default = self._stream_one(tmp, default_img, None)
                    self.assertTrue(rec["watermark_enabled"])
                    self.assertEqual(rec["watermark_path"], default)
                    with open(default, "rb") as fh:
                        self.assertEqual(fh.read(), b"SERVERS-DEFAULT", "this PC had none: the server's default is saved as this PC's default")
                elif case == 2:
                    rec, default = self._stream_one(tmp, None, b"MINE")
                    self.assertTrue(rec["watermark_enabled"])
                    self.assertEqual(rec["watermark_path"], default, "the server has none (default missing there): this PC's default")
                else:
                    rec, default = self._stream_one(tmp, None, None)
                    self.assertFalse(rec["watermark_enabled"], "nothing picked and no default anywhere: off")
                    self.assertFalse(os.path.exists(default))
            finally:
                shutil.rmtree(tmp, ignore_errors=True)

    def test_the_server_sends_the_small_image_with_a_channel_whose_watermark_is_on(self):
        import sys, tempfile
        sys.path.insert(0, os.path.join(SCRIPTS, "server"))
        import server_sync
        tmp = tempfile.mkdtemp()
        try:
            path = os.path.join(tmp, "bug.png")
            with open(path, "wb") as fh:
                fh.write(b"tiny-image")
            out = server_sync.sanitize_channels({"07": {"active": True, "watermark_enabled": True, "watermark_path": path},
                                                 "08": {"active": True, "watermark_enabled": False, "watermark_path": path}})
            self.assertEqual(out["07"]["watermark_image"]["name"], "bug.png")
            self.assertTrue(out["07"]["watermark_enabled"])
            self.assertNotIn("watermark_image", out["08"], "off sends no image")
            self.assertNotIn("watermark_path", out["07"], "the server's own path never leaves it")
            self.assertFalse(out["07"]["watermark_image"]["is_default"], "an image outside the WATERMARK folder is the creator's pick")
            big = os.path.join(tmp, "big.png")
            with open(big, "wb") as fh:
                fh.write(b"x" * (server_sync.WATERMARK_SERVER_MAX_BYTES + 1))
            out = server_sync.sanitize_channels({"09": {"active": True, "watermark_enabled": True, "watermark_path": big}})
            self.assertNotIn("watermark_image", out["09"], "an image over the cap is left out")
            root = os.path.join(tmp, "WATERMARK")
            os.makedirs(os.path.join(root, "default"))
            with open(os.path.join(root, "default", "watermark.png"), "wb") as fh:
                fh.write(b"default")
            server_sync.WATERMARK_ROOT = root
            try:
                out = server_sync.sanitize_channels({"10": {"active": True, "watermark_enabled": True, "watermark_path": ""}})
                self.assertTrue(out["10"]["watermark_image"]["is_default"], "no pick and nothing in the folder: the one default, found on the server by the same rule")
                os.makedirs(os.path.join(root, "Channel 10"))
                with open(os.path.join(root, "Channel 10", "own.png"), "wb") as fh:
                    fh.write(b"own")
                out = server_sync.sanitize_channels({"10": {"active": True, "watermark_enabled": True, "watermark_path": ""}})
                self.assertEqual(out["10"]["watermark_image"]["name"], "own.png")
                self.assertFalse(out["10"]["watermark_image"]["is_default"])
            finally:
                server_sync.WATERMARK_ROOT = ""
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


class TestAServerChannelOnWithNoMediaShowsOffOnTheProfile(unittest.TestCase):
    """Owner 2026-11-12: a channel the server turned on but gave no media is Static and is not streamed; it shows as off on the User's profile."""

    def _db(self, own):
        import threading
        import media
        db = object.__new__(media.RetroDatabase)
        db._remote_schedule_lock = threading.RLock()
        db._remote_schedule_active = False
        db._remote_local_channels_snapshot = None
        db._remote_locked_channels = set()
        db.remote_playback = {}
        db.config = {}
        db.channels_db = db._build_channels_db(own)
        return db

    def test_on_with_no_media_is_off_and_free_while_on_with_media_is_the_servers(self):
        db = self._db({})
        db.apply_remote_schedule({"05": {"active": True}, "06": {"active": True}, "07": {"active": True, "schedules": {"Full Day": [{"path": "C:\\a.mp4"}]}}})
        for ch in ("05", "06"):
            self.assertFalse(db.channels_db[ch]["active"], ch)
            self.assertFalse(db.channels_db[ch].get("server_locked", False), ch)
        self.assertTrue(db.channels_db["07"]["active"])
        self.assertTrue(db.channels_db["07"]["server_locked"])

    def test_a_server_channel_with_one_block_scheduled_stays_the_servers_and_its_gaps_stay_static(self):
        db = self._db({"09": {"active": True, "block_mode": "full_day", "schedules": {"12-4am": [{"path": "C:\\mine.mp4"}]}}})
        db.apply_remote_schedule({"09": {"active": True, "block_mode": "six_block", "schedules": {"4-8am": [{"path": "C:\\a.mp4"}]}}})
        rec = db.channels_db["09"]
        self.assertTrue(rec["server_locked"])
        self.assertTrue(rec["active"])
        self.assertEqual(rec["block_mode"], "six_block")
        self.assertEqual(rec["schedules"]["4-8am"][0]["path"], "C:\\a.mp4")
        self.assertEqual(rec["schedules"]["12-4am"], [], "the unscheduled block is the server's gap (Static), not this User's media")

    def test_this_users_own_media_on_that_channel_keeps_it_on(self):
        db = self._db({"05": {"active": True, "schedules": {"Full Day": [{"path": "C:\\mine.mp4"}]}}})
        db.apply_remote_schedule({"05": {"active": True}})
        self.assertTrue(db.channels_db["05"]["active"])
        self.assertFalse(db.channels_db["05"].get("server_locked", False))


class TestTheServerStartsWithTheProgramAndTheTrayClosesWhenItIsTurnedOff(unittest.TestCase):
    """Owner 2026-11-12: with the Server toggle on the server must start when it is not in the tray, and with it off the tray must close."""

    def _controller(self):
        i = MAIN_SRC.index("    def _schedule_broadcaster_controller():")
        return MAIN_SRC[i:MAIN_SRC.index("    if UPDATER_AND_SERVER_FEATURES_ENABLED:\n        threading.Thread(target=_schedule_broadcaster_controller")]

    def test_the_controller_waits_for_the_settings_and_starts_the_server_on_the_first_pass(self):
        c = self._controller()
        self.assertLess(c.index('getattr(db, "ready_flag", False)'), c.index("_server_service_should_run()"))
        self.assertIn("_reconcile_server_service(force=first_pass)", c)
        self.assertIn("server_service.set_autostart(db.base_dir, True)", c)
        self.assertNotIn("set_autostart(db.base_dir, False)", c, "the start-at-login entry is not removed again every second")
        self.assertIn("elif was_wanted:\n                _stop_server_service_now()", c)

    def test_turning_the_toggle_off_flushes_the_settings_and_ends_the_tray_process_and_on_starts_it(self):
        calls = []
        class _Db:
            base_dir = "x"
            def flush_settings(self_inner): calls.append("flush")
        class _Svc:
            @staticmethod
            def set_autostart(b, e): calls.append(("autostart", e))
            @staticmethod
            def stop_service(b): calls.append("stop")
        class _Thread:
            def __init__(self_inner, target=None, daemon=None, name=None): self_inner.t = target
            def start(self_inner): self_inner.t()
        body = re.search(r"^def _stop_server_service_now\(.*?(?=^\S)", MAIN_SRC, re.S | re.M).group(0)
        ns = {"db": _Db(), "server_service": _Svc, "threading": types.SimpleNamespace(Thread=_Thread), "_log_swallowed": lambda *a, **k: None}
        exec(compile(body, "stop", "exec"), ns)
        ns["_stop_server_service_now"]()
        self.assertEqual(calls, ["flush", ("autostart", False), "stop"])
        toggle = MAIN_SRC[MAIN_SRC.index('db.config["server_mode_enabled"] = not db.config.get("server_mode_enabled", False)'):]
        toggle = toggle[:toggle.index('elif _as_row_id == "server_menu_open"')]
        self.assertIn("_stop_server_service_now()", toggle)
        self.assertIn("_reconcile_server_service(force=True)", toggle)


class TestEachServerHasItsOwnCopyAndNothingIsLeftBehind(unittest.TestCase):
    """Owner 2026-11-12: opening a server hides this PC's own channels and loads that server's copy; nothing carries over either way, and on the app's first boot (no settings file) every saved data file, the server and profile folders included, is cleared."""

    def _db(self, tmp):
        return _settings_writer_db(tmp, 0.4)

    def _write(self, path, channels):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w") as f:
            json.dump({"channels": channels}, f)

    def test_a_normal_start_and_a_pick_never_delete_a_copy_the_user_has_added_channels_to(self):
        tmp = tempfile.mkdtemp()
        rdb, restore = self._db(tmp)
        try:
            self.assertTrue(rdb.enter_user_profile("Steven"))
            rdb.channels_db["20"]["active"] = True
            rdb.save_channels(force=True)
            rdb.leave_server_slot()
            self.assertTrue(rdb.enter_user_profile("Steven"))
            self.assertTrue(rdb.channels_db["20"]["active"])
        finally:
            restore()
            shutil.rmtree(tmp, ignore_errors=True)
        src = open(_script("media.py"), encoding="utf-8").read()
        self.assertNotIn("clean_leftover_server_data", src)

    def test_a_fresh_copy_holds_none_of_this_pcs_own_channels(self):
        tmp = tempfile.mkdtemp()
        rdb, restore = self._db(tmp)
        try:
            rdb.channels_db["09"]["active"] = True
            self.assertTrue(rdb.enter_user_profile("Steven"))
            self.assertFalse(rdb.channels_db["09"]["active"])
            self.assertTrue(rdb.channels_db["05"]["active"])
        finally:
            restore()
            shutil.rmtree(tmp, ignore_errors=True)

    def test_only_a_channel_with_media_is_the_servers_and_every_other_channel_stays_free(self):
        import threading
        import media
        db = object.__new__(media.RetroDatabase)
        db._remote_schedule_lock = threading.RLock()
        db._remote_schedule_active = False
        db._remote_local_channels_snapshot = None
        db._remote_locked_channels = set()
        db.remote_playback = {}
        db.channels_db = db._build_channels_db({"20": {"active": True, "schedules": {"Full Day": [{"path": "C:\\mine.mp4"}]}}})
        db.apply_remote_schedule({"05": {"active": True, "schedules": {"Full Day": [{"path": "C:\\theirs.mp4"}]}}, "06": {"active": True}, "07": {"active": False}})
        self.assertTrue(db.channels_db["05"]["server_locked"])
        self.assertEqual(db._remote_locked_channels, {"05"})
        for free in ("06", "07", "08", "44"):
            self.assertFalse(db.channels_db[free].get("server_locked", False), free)
        self.assertTrue(db.channels_db["20"]["active"], "this PC's own addition stays on")
        self.assertFalse(db.channels_db["20"].get("server_locked", False))

    def test_a_reset_and_a_first_boot_delete_the_server_data_folders(self):
        tmp = tempfile.mkdtemp()
        try:
            logs, main = os.path.join(tmp, "logs"), os.path.join(tmp, "main")
            os.makedirs(logs)
            os.makedirs(main)
            for rel in (os.path.join("_internal", "server", ".json", "user", "A"), os.path.join("server", ".json", "server", "B")):
                os.makedirs(os.path.join(tmp, rel))
                open(os.path.join(tmp, rel, "retro.config.json"), "w").write("{}")
            ns = {}
            src = MAIN_SRC
            exec(compile("import os\n" + src[src.index("FRESH_START_MARKER_NAME = "):src.index("def _fresh_start_marker_path")].replace("_FRESH_START_WAIT_FOR_OLD_APP_S", "0"), "c", "exec"), ns)
            body = src[src.index("def _wait_for_old_app_to_close"):src.index("# SECTION: Process lifetime")]
            ns.update(log=logging.getLogger("t"), time=time, _FRESH_START_WAIT_FOR_OLD_APP_S=0.0)
            exec(compile(body.rsplit("# ====", 1)[0], "b", "exec"), ns)
            removed, failed = ns["_wipe_saved_data_for_fresh_start"](tmp, logs, main, config_missing=True)
            self.assertEqual(failed, [])
            self.assertFalse(os.path.exists(os.path.join(tmp, "_internal", "server", ".json")))
            self.assertFalse(os.path.exists(os.path.join(tmp, "server", ".json")))
        finally:
            shutil.rmtree(tmp, ignore_errors=True)


class TestAPickedServerOpensOnTheRightChannelWithABlackScreen(unittest.TestCase):
    """Owner 2026-11-12: a pick opens on 05 the first time and on the last channel watched on that server after that, shows black (never Static) while it loads, and leaving goes back to the channel left from."""

    def setUp(self):
        self.src = MAIN_SRC

    def _fn(self, name, **extra):
        match = re.search(r"^def %s\(.*?(?=^\S)" % name, self.src, re.S | re.M)
        ns = {"app_state": {}, "db": types.SimpleNamespace(config={}, save_settings=lambda: None), "log": logging.getLogger("t_pick"),
              "calls": [], "pygame": types.SimpleNamespace(time=types.SimpleNamespace(get_ticks=lambda: 1000))}
        ns.update(extra)
        exec(compile(match.group(0), name, "exec"), ns)
        return ns

    def test_a_pick_the_viewer_made_opens_on_the_remembered_channel_and_one_the_app_made_stays_put(self):
        ns = self._fn("_remember_channel_on_server")
        exec(compile(re.search(r"^def _channel_to_open_on_server\(.*?(?=^\S)", self.src, re.S | re.M).group(0), "x", "exec"), ns)
        ns["app_state"].update(user_selected_server_name="Den", active_remote_server={"name": "Den"}, current_channel="12")
        self.assertEqual(ns["_channel_to_open_on_server"]("Den"), "05")
        ns["db"].config["server_last_channels"] = {"den": "14"}
        self.assertEqual(ns["_channel_to_open_on_server"]("den"), "14")
        ns["app_state"]["_server_pick_is_automatic"] = True
        ns["app_state"]["current_channel"] = "30"
        self.assertEqual(ns["_channel_to_open_on_server"]("den"), "30")

    def test_the_first_schedule_tunes_once_to_the_channel_it_opens_on(self):
        ns = self._fn("_server_first_tune_tick")
        exec(compile(re.search(r"^def _channel_to_open_on_server\(.*?(?=^\S)", self.src, re.S | re.M).group(0), "x", "exec"), ns)
        ns["_restart_playback_after_source_change"] = lambda reason, restore_channel=False, target_channel=None: ns["calls"].append(target_channel)
        ns["db"].config["server_last_channels"] = {"den": "14"}
        ns["app_state"].update(_server_first_tune="Den", active_remote_server={"name": "Den"}, _remote_schedule_received=False, current_channel="21")
        ns["_server_first_tune_tick"]()
        self.assertEqual(ns["calls"], [])
        ns["app_state"]["_remote_schedule_received"] = True
        ns["_server_first_tune_tick"]()
        ns["_server_first_tune_tick"]()
        self.assertEqual(ns["calls"], ["14"])

    def test_the_wish_falls_back_to_05_then_to_the_closest_channel(self):
        src = self.src[self.src.index("def _restart_playback_after_source_change"):self.src.index("def _execute_manage_server():")]
        self.assertIn("if target_channel:", src)
        self.assertIn('elif "05" in _allowed_pick:', src)
        self.assertIn("_nearest_allowed_channel(_want, _allowed_pick)", src)
        self.assertIn("if _saved and not target_channel:", src)

    def test_a_pick_is_black_not_static_while_it_loads(self):
        ns = self._fn("_awaiting_first_server_schedule")
        ns["_SERVER_FIRST_SCHEDULE_WAIT_MS"] = 10000
        ns["app_state"]["_server_pick_blank_until_ms"] = 4000
        self.assertTrue(ns["_awaiting_first_server_schedule"]())
        ns["app_state"]["_server_pick_blank_until_ms"] = 900
        self.assertFalse(ns["_awaiting_first_server_schedule"]())
        use = self.src[self.src.index("def _use_server_entry(entry):"):self.src.index("def _remote_slot_missing_from_discovery")]
        self.assertIn('app_state["_server_pick_blank_until_ms"] = pygame.time.get_ticks() + int(1000 * SERVER_PICK_BLANK_SECONDS)', use)

    def test_the_pick_remembers_the_channel_it_leaves_and_opens_the_server_on_its_own(self):
        use = self.src[self.src.index("def _use_server_entry(entry):"):self.src.index("def _remote_slot_missing_from_discovery")]
        self.assertLess(use.index("_remember_channel_on_server()"), use.index("_disconnect_remote_server"))
        self.assertIn('target_channel=_channel_to_open_on_server(entry["name"])', use)
        self.assertIn('app_state["_server_first_tune"] = entry["name"]', use)
        self.assertIn("if not _connect_remote_server(entry):", use)
        for name in ("_execute_clear_user_choice", "_fall_back_from_remote_server"):
            self.assertIn("_remember_channel_on_server()", get_function_source(name))
        self.assertIn("_server_first_tune_tick()", self.src)

    def test_no_copy_means_no_connection_and_the_own_channels_come_back(self):
        conn = self.src[self.src.index("def _connect_remote_server(_picked, cached=None):"):self.src.index("def _restart_playback_after_source_change")]
        self.assertIn("return False", conn.split("_sync_status_state", 1)[0])
        self.assertNotIn("streaming on the main channel file", conn)

    def test_the_sync_check_line_is_written_only_for_a_streamed_channel_and_changes_nothing(self):
        import datetime as _dt
        lines = []
        clock = types.SimpleNamespace(now=lambda: _dt.datetime(2026, 11, 12, 20, 0, 30))
        ns = self._fn("_server_sync_check_tick", SERVER_SYNC_CHECK_SECONDS=60.0, datetime=_dt, broadcast_clock=clock, os=os,
                      log=types.SimpleNamespace(info=lambda *a: lines.append(a[0] % a[1:]), warning=lambda *a: lines.append("WARN " + a[0])))
        ns["calculate_slotted_playback_state"] = lambda ch: {"mode": "Video", "file": os.path.join("v", "Show.mkv"), "seek": 90.0}
        ns["db"].channels_db = {"09": {"server_locked": True, "playback_log": {"intro_seed": 7}}, "10": {}}
        ns["app_state"].update(active_remote_server={"name": "Den"}, user_selected_server_name="Den", current_channel="09", remote_schedule_revision=3)
        ns["_server_sync_check_tick"](100000)
        self.assertEqual(len(lines), 1)
        self.assertIn("started=19:59:00", lines[0])
        self.assertIn("file=Show.mkv", lines[0])
        ns["_server_sync_check_tick"](120000)
        self.assertEqual(len(lines), 1, "once a minute")
        ns["app_state"]["current_channel"] = "10"
        ns["_server_sync_check_tick"](200000)
        self.assertEqual(len(lines), 1, "a channel the server does not own writes nothing")
        self.assertIn("_server_sync_check_tick(pygame.time.get_ticks())", self.src)

    def test_the_number_matches_the_governor(self):
        import performance_governor as pg
        self.assertEqual(pg.SERVER_SYNC_CHECK_SECONDS, 60.0)
        self.assertEqual(pg.SERVER_PICK_BLANK_SECONDS, 3.0)
        self.assertIn("else 3.0", self.src[self.src.index("SERVER_PICK_BLANK_SECONDS ="):][:200])


class TestStreamedChannelsAreOnForAUser(unittest.TestCase):
    """A User PC plays every channel the server streams, not only channel 05."""

    def _db(self):
        import threading
        import media
        db = object.__new__(media.RetroDatabase)
        db._remote_schedule_lock = threading.RLock()
        db._remote_schedule_active = False
        db._remote_local_channels_snapshot = None
        db._remote_locked_channels = set()
        db.remote_playback = {}
        db.channels_db = db._build_channels_db({})
        return db

    def _wire(self, **extra):
        import server_sync
        server = {k: dict({"active": True, "schedules": {"Full Day": [{"path": "C:\\v\\" + k + ".mp4"}]}}, **extra.get(k, {}))
                  for k in ("05", "06", "07", "08")}
        return server_sync.sanitize_channels(server)

    def test_every_streamed_channel_is_on_even_though_this_pcs_own_switch_is_off(self):
        db = self._db()
        self.assertFalse(db.channels_db["06"]["active"])
        db.apply_remote_schedule(self._wire())
        for ch in ("05", "06", "07", "08"):
            self.assertTrue(db.channels_db[ch]["active"], ch)
            self.assertTrue(db.channels_db[ch]["server_locked"], ch)
        self.assertFalse(db.channels_db["09"]["active"])
        db.disconnect_remote_schedule()
        self.assertFalse(db.channels_db["06"]["active"], "disconnecting gives this PC's own switches back")

    def test_a_channel_the_server_has_off_stays_off_and_a_music_channel_stays_a_music_channel(self):
        db = self._db()
        db.apply_remote_schedule(self._wire(**{"06": {"active": False}, "08": {"is_visualizer": True, "visualizer_style": "Random"}}))
        self.assertFalse(db.channels_db["06"]["active"])
        self.assertTrue(db.channels_db["08"]["is_visualizer"])

    def test_an_older_server_that_sends_no_switch_still_gets_its_channels_on(self):
        db = self._db()
        db.apply_remote_schedule({"06": {"schedules": {"Full Day": [{"path": "C:\\v\\a.mp4"}]}}})
        self.assertTrue(db.channels_db["06"]["active"])

    def test_only_schedules_and_the_few_playback_settings_cross_the_wire(self):
        import server_sync
        wire = server_sync.sanitize_channels({"06": {"active": True, "name": "MY NAME", "commercials_enabled": True,
                                                       "schedules": {}, "playback_log": {"x": 1}, "watermark": "w.png"}})
        self.assertEqual(sorted(wire["06"]), ["active", "commercials_enabled", "playback_log", "schedules"])
        self.assertEqual(wire["06"]["playback_log"], {"x": 1})


class TestTwoPcsOnAServerBuildTheSameBlocks(unittest.TestCase):
    """Owner 2026-11-12: the logs of the server PC and a User PC on one server (2026-11-12 04:30) showed the same movie on air at different points, 83 s into a 30-minute slot on one and 1650 s into the whole film on the other; the server's cycle held 91794 s with commercials, the User PC's block 77083 s with none."""

    def _db(self):
        return TestStreamedChannelsAreOnForAUser._db(self)

    def test_the_settings_that_decide_a_blocks_length_cross_the_wire_and_are_applied(self):
        import server_sync
        wire = server_sync.sanitize_channels({"05": {"active": True, "schedules": {"Full Day": [{"path": "C:\\v\\a.mp4"}], "Commercials": [{"path": "C:\\c\\1.mp4"}]},
                                                      "commercials_enabled": True, "commercial_placement": "interrupt_half_hour",
                                                      "intros_enabled": True, "outros_enabled": True, "marathon_anchor_epoch": 123.5, "name": "MINE"}})
        self.assertEqual(wire["05"]["commercials_enabled"], True)
        self.assertEqual(wire["05"]["marathon_anchor_epoch"], 123.5)
        self.assertNotIn("name", wire["05"])
        db = self._db()
        self.assertFalse(db.channels_db["05"]["commercials_enabled"])
        db.apply_remote_schedule(wire)
        rec = db.channels_db["05"]
        self.assertTrue(rec["commercials_enabled"])
        self.assertEqual(rec["commercial_placement"], "interrupt_half_hour")
        self.assertTrue(rec["intros_enabled"] and rec["outros_enabled"])
        self.assertEqual(rec["marathon_anchor_epoch"], 123.5)
        db.disconnect_remote_schedule()
        self.assertFalse(db.channels_db["05"]["commercials_enabled"], "leaving gives this PC's own setting back")

    def test_an_older_server_that_sends_none_of_them_changes_nothing(self):
        db = self._db()
        db.channels_db["05"]["commercials_enabled"] = True
        db.apply_remote_schedule({"05": {"active": True, "schedules": {"Full Day": [{"path": "C:\\v\\a.mp4"}]}}})
        self.assertTrue(db.channels_db["05"]["commercials_enabled"])

    def test_a_streamed_copy_is_never_folded_into_this_pcs_own_channels(self):
        db = self._db()
        db.apply_remote_schedule({"09": {"active": True, "schedules": {"Full Day": [{"path": "C:\\v\\a.mp4"}]}}})
        db._remote_locked_channels = set()
        with db._remote_schedule_lock:
            db._fold_live_unlocked_into_snapshot_locked()
        own = db._remote_local_channels_snapshot["09"]
        self.assertFalse(own["active"])
        self.assertEqual(own["schedules"]["Full Day"], [])

    def test_the_copies_of_earlier_builds_are_deleted_once_and_never_again(self):
        tmp = tempfile.mkdtemp()
        rdb, restore = _settings_writer_db(tmp, 0.4)
        try:
            root = os.path.join(tmp, "main", "data", ".json")
            old = os.path.join(root, "user", "Steven", "retro.config.json")
            os.makedirs(os.path.dirname(old))
            open(old, "w").write('{"channels": {"09": {"active": true}}}')
            keep = os.path.join(root, "server", "Den", "retro.config.json")
            os.makedirs(os.path.dirname(keep))
            open(keep, "w").write('{"channels": {}}')
            self.assertTrue(rdb.clear_user_copies_once())
            self.assertFalse(os.path.exists(os.path.dirname(old)))
            self.assertTrue(os.path.isfile(keep), "a server's own folder is never touched")
            self.assertEqual(rdb.config["user_copies_cleared"], 1)
            self.assertTrue(rdb.enter_user_profile("Steven"))
            rdb.channels_db["20"]["active"] = True
            rdb.save_channels(force=True)
            rdb.leave_server_slot()
            self.assertFalse(rdb.clear_user_copies_once())
            self.assertTrue(os.path.isfile(old), "what a User adds after this build is kept")
        finally:
            restore()
            shutil.rmtree(tmp, ignore_errors=True)


class TestEveryPcOnAServerAirsTheSameThing(unittest.TestCase):
    """Owner 2026-11-10: two computers on one server played different things; the server now sends where each channel's rotation stands and a User follows it."""

    def _db(self):
        return TestStreamedChannelsAreOnForAUser._db(self)

    def _wire(self, log):
        import server_sync
        return server_sync.sanitize_channels({"06": {"active": True, "schedules": {"Full Day": [{"path": "C:\\v\\a.mp4"}]},
                                                      "playback_log": log}})

    def test_the_servers_rotation_state_crosses_the_wire_without_working_flags(self):
        wire = self._wire({"intro_seed": 77, "show_pos": {"A": 2}, "_sched_rebuild_requested": True, "nest": {"_x": 1, "y": 2}})
        self.assertEqual(wire["06"]["playback_log"], {"intro_seed": 77, "show_pos": {"A": 2}, "nest": {"y": 2}})

    def test_a_user_takes_the_servers_start_number_and_positions_not_its_own(self):
        db = self._db()
        db.channels_db["06"]["playback_log"] = {"intro_seed": 5, "show_pos": {"A": 9}}
        db.apply_remote_schedule(self._wire({"intro_seed": 77, "show_pos": {"A": 2}}))
        self.assertEqual(db.channels_db["06"]["playback_log"], {"intro_seed": 77, "show_pos": {"A": 2}})

    def test_two_users_of_a_server_that_has_no_start_number_yet_get_the_same_one(self):
        first, second = self._db(), self._db()
        first.channels_db["06"]["playback_log"] = {"intro_seed": 5}
        second.channels_db["06"]["playback_log"] = {"intro_seed": 6}
        for d in (first, second):
            d.apply_remote_schedule(self._wire({}), server_host="srv")
        self.assertEqual(first.channels_db["06"]["playback_log"]["intro_seed"], second.channels_db["06"]["playback_log"]["intro_seed"])

    def test_the_servers_state_is_not_kept_after_leaving_the_server(self):
        db = self._db()
        db.channels_db["06"]["playback_log"] = {"intro_seed": 5}
        db.apply_remote_schedule(self._wire({"intro_seed": 77}))
        db.disconnect_remote_schedule()
        self.assertEqual(db.channels_db["06"].get("playback_log", {}).get("intro_seed"), 5)

    def test_a_lineup_saved_by_file_path_is_moved_to_the_share_with_its_keys(self):
        import server_remote_files
        fm = server_remote_files.RemoteFileMap.__new__(server_remote_files.RemoteFileMap)
        fm._unc_by_server_path = {server_remote_files._win("C:\\v\\a.mp4"): "\\\\srv\\s\\a.mp4"}
        out, left = fm.rewrite({"playback_log": {"sched_cached_durations": {"C:\\v\\a.mp4": 60}, "sched_cached_tracks": ["C:\\v\\a.mp4"]}})
        self.assertEqual(out["playback_log"]["sched_cached_durations"], {"\\\\srv\\s\\a.mp4": 60})
        self.assertEqual(out["playback_log"]["sched_cached_tracks"], ["\\\\srv\\s\\a.mp4"])
        self.assertEqual(left, 0)


