class TestServerFilesAreDecidedByTheServer(unittest.TestCase):
    """Owner 2026-11-14: CRT logs showed long channel loads: the User PC rescanned picture boxes and decoded video for burned-in captions over the share while VLC was opening the same drive."""

    def test_the_burned_in_verdict_travels_with_the_file_facts(self):
        import server_files
        self.assertIn("captions_source", server_files.FACT_COLUMNS)
        self.assertIn("captions_reason", server_files.FACT_COLUMNS)

    def test_a_newer_burned_in_verdict_from_the_server_replaces_an_older_one_as_a_pair(self):
        import server_remote_files
        lib = MagicMock()
        lib.get_entry.return_value = {"captions_source": "clean", "captions_reason": "burned_in_v3"}
        entry = {"key": "k", "size": 5, "mtime": 1.0,
                 "f": {"captions_source": "baked", "captions_reason": "burned_in_v4"}}
        server_remote_files.RemoteFileMap._save_facts(lib, "\\\\h\\s\\a.mkv", entry)
        saved = lib.upsert_fields.call_args.kwargs
        self.assertEqual((saved["captions_source"], saved["captions_reason"]), ("baked", "burned_in_v4"))

    def test_an_equal_or_older_verdict_from_the_server_changes_nothing_held_here(self):
        import server_remote_files
        lib = MagicMock()
        lib.get_entry.return_value = {"captions_source": "clean", "captions_reason": "burned_in_v4"}
        entry = {"key": "k", "size": 5, "mtime": 1.0,
                 "f": {"captions_source": "baked", "captions_reason": "burned_in_v4"}}
        server_remote_files.RemoteFileMap._save_facts(lib, "\\\\h\\s\\a.mkv", entry)
        self.assertNotIn("captions_source", lib.upsert_fields.call_args.kwargs if lib.upsert_fields.called else {})

    def test_the_server_scan_reads_the_burned_in_verdict_of_a_video_that_lacks_it(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            clip = os.path.join(tmp, "a.mkv")
            open(clip, "w").close()
            probe = MagicMock()
            probe.get_cached.return_value = {"header_probed_at": 1.0, "duration": 100.0}
            probe.get_burned_in_verdict.return_value = None
            probe.detect_burned_in_if_needed.return_value = False
            sc = server_scanner.FactsScanner(lambda: {}, lambda: False, lambda: probe)
            with patch("media_library.PICTURE_BOX_DETECTOR_VERSION", 0, create=True):
                self.assertIn("burned", sc._needs(probe, clip))
                self.assertTrue(sc._scan_file(probe, clip))
            probe.detect_burned_in_if_needed.assert_called_once_with(clip)

    def test_a_user_pc_never_decodes_a_server_file_for_burned_in_captions(self):
        import media, media_library
        probe = MagicMock()
        probe.get_burned_in_verdict.return_value = None
        with patch.object(media_library, "shared_probe_library", return_value=probe), \
                patch("server_remote_files.server_owns", return_value=True):
            self.assertIsNone(media._burned_in_verdict("\\\\h\\s\\a.mkv"))
        probe.detect_burned_in_if_needed.assert_not_called()

    def test_a_user_pc_does_not_rescan_a_server_files_older_picture_box(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        locked = src[src.index("def _picture_box_scan_one_locked"):]
        locked = locked[:locked.index("diag = {}")]
