class TestGuideWindowMovesOncePerPress(unittest.TestCase):
    """Owner 2026-11-16: one press dragged the guide twice and the highlight left the screen in between, because the search for the next spot moved the real window to each candidate"""

    def _run(self, presses, direction, start_hour=23, columns=5, one_past_the_edge=False):
        import datetime as _dt
        import ui
        now = _dt.datetime(2026, 11, 15, start_hour, 5)
        live = now.hour * 2 + (1 if now.minute >= 30 else 0)
        import random
        rnd = random.Random(1)
        shows, t = [], -3 * 86400
        while t < 9 * 86400:
            d = rnd.choice([1800, 1800, 3600, 3600, 5400, 7200])
            shows.append((t, t + d))
            t += d
        sec = now.hour * 3600 + now.minute * 60
        cur = next(x for x in shows if x[0] <= sec < x[1])

        class _State(dict):
            writes = []

            def __setitem__(self, key, value):
                if key == "selected_guide_time_idx":
                    self.writes.append(value)
                dict.__setitem__(self, key, value)
        state = _State({"guide_col_pos": 0, "selected_guide_time_idx": 0, "guide_current_row_stops": [],
                        "guide_selected_stop_key": ("show", cur[0]), "guide_selected_abs_time": cur[0]})
        state.writes = []

        def refresh(shift=None):
            _shift = state["selected_guide_time_idx"] if shift is None else shift
            idx = ui.clamp_guide_time_idx(live + _shift, columns)
            vs, ve = idx * 1800, idx * 1800 + columns * 1800
            stops = []
            for a, b in shows:
                if b <= vs or a >= ve:
                    continue
                sa, sb = max(a, vs), min(b, ve)
                cut = "left" if a < vs else ("right" if b > ve else None)
                stops.append({"col": int((sa - vs) // 1800), "abs": a, "key": ("show", a),
                              "vis": (sb - sa) / 1800.0 if cut else 99.0, "cut": cut})
            if one_past_the_edge:
                after = next((x for x in shows if x[0] >= ve), None)
                if after is not None:
                    stops.append({"col": columns, "abs": after[0], "key": ("show", after[0]), "vis": 99.0, "cut": None})
            state["guide_current_row_stops"] = stops
        refresh()
        ns = {"_log_warn_throttled": lambda *a, **k: None, "app_state": state, "db": object(), "performance_governor": None,
              "get_guide_num_cols": lambda d: columns, "_guide_dirty_event": threading.Event(),
              "_GUIDE_MIN_VISIBLE_COLUMNS": 0.4,
              "broadcast_clock": types.SimpleNamespace(now=lambda: now),
              "clamp_guide_time_idx": ui.clamp_guide_time_idx, "_refresh_guide_row_stops_offscreen": refresh}
        exec(get_function_source("_guide_jump_col"), ns)
        per_press = []
        for _ in range(presses):
            state.writes = []
            ns["_guide_jump_col"](direction)
            per_press.append(list(state.writes))
        return state, per_press, live

    def test_the_real_window_changes_at_most_once_per_press_going_left(self):
        _state, per_press, _live = self._run(60, -1)
        self.assertTrue(all(len(w) <= 1 for w in per_press), per_press)

    def test_the_real_window_changes_at_most_once_per_press_going_right(self):
        _state, per_press, _live = self._run(60, 1)
        self.assertTrue(all(len(w) <= 1 for w in per_press), per_press)

    def test_left_goes_back_to_todays_midnight_and_no_further(self):
        """Owner 2026-11-23: the only past the guide shows is today's, back to midnight; at 11 pm the window stops at today's midnight."""
        import ui
        self.assertEqual(gov.GUIDE_PAST_HALF_HOURS, 0)
        state, _per, live = self._run(80, -1)
        self.assertEqual(ui.clamp_guide_time_idx(live + state["selected_guide_time_idx"], 5), 0)
        self.assertGreaterEqual(state["guide_selected_abs_time"], -1800)
        self.assertLessEqual(state["guide_selected_abs_time"], 1800)

    def test_right_always_lands_on_a_spot_that_is_on_screen(self):
        import ui
        state, _per, live = self._run(1, 1)
        idx = ui.clamp_guide_time_idx(live + state["selected_guide_time_idx"], 5)
        col = (state["guide_selected_abs_time"] - idx * 1800) / 1800.0
        self.assertTrue(0 <= col < 5)

    def test_right_scrolls_when_the_row_holds_a_spot_past_the_edge(self):
        """Owner test 2026-11-23: past 06:30 the highlight went off the right edge, was put back, went off again, and the guide never scrolled."""
        import ui
        for presses in range(1, 15):
            state, _per, live = self._run(presses, 1, start_hour=4, one_past_the_edge=True)
            idx = ui.clamp_guide_time_idx(live + state["selected_guide_time_idx"], 5)
            col = (state["guide_selected_abs_time"] - idx * 1800) / 1800.0
            self.assertTrue(-1 < col < 5, "press %d left the highlight at column %.2f" % (presses, col))
        self.assertGreater(state["selected_guide_time_idx"], 0, "the window moved right")

    def test_a_probe_reads_its_own_shift_and_never_the_real_one(self):
        import ui
        state = {"selected_guide_time_idx": 3, "_guide_stops_only_probe": True, "_guide_probe_shift": -7}
        self.assertEqual(ui.guide_time_shift(state), -7)
        state["_guide_stops_only_probe"] = False
        self.assertEqual(ui.guide_time_shift(state), 3)


class TestGuideRowsAndSpotsAreNeverLost(unittest.TestCase):
    """Owner 2026-11-16: the guide opened on a channel it does not draw, right stopped working and took the highlight off the screen"""

    def test_one_list_of_rows_serves_drawing_up_down_restore_and_start(self):
        import inspect, ui
        self.assertEqual(menu_nav.guide_rows({"05": {"active": False}, "06": {}, "07": {"active": True}, "08": {"active": False}})[:2], ["06", "07"])
        self.assertIn("menu_nav.guide_rows(db.channels_db)", inspect.getsource(ui))
        self.assertIn("menu_nav.guide_rows(db.channels_db)", get_function_source("_guide_step_row"))
        self.assertIn("menu_nav.guide_rows(db.channels_db)", get_function_source("change_channel"))

    def test_the_start_row_is_always_a_drawn_row(self):
        rows = ["06", "07", "13"]
        self.assertEqual(menu_nav.guide_start_row(rows, "13", "05"), "13", "the channel being watched first")
        self.assertEqual(menu_nav.guide_start_row(rows, "05", "07"), "07", "then the one last highlighted")
        self.assertEqual(menu_nav.guide_start_row(rows, "05", "04"), "06", "else the first row; a channel that is not a row never holds the highlight")
        self.assertIsNone(menu_nav.guide_start_row([], "05"))

    def _jump(self, direction, presses, highlight_abs=None, window_keyed=True, columns=4):
        import datetime as _dt
        import ui
        now = _dt.datetime(2026, 11, 15, 22, 5)
        live = now.hour * 2 + 0
        shows, t = [], -3 * 86400
        import random
        rnd = random.Random(7)
        while t < 9 * 86400:
            if rnd.random() < 0.25:
                t += rnd.choice([1800, 3600, 2651])
            d = rnd.choice([1800, 3600, 5400, 7200, 3011])
            shows.append((t, t + d))
            t += d
        sec = now.hour * 3600 + now.minute * 60
        cur = next(x for x in shows if x[0] <= sec < x[1])
        start = cur[0] if highlight_abs is None else highlight_abs
        state = {"guide_col_pos": 0, "selected_guide_time_idx": 0, "guide_current_row_stops": [],
                 "guide_selected_stop_key": ("show", start), "guide_selected_abs_time": start}

        def refresh(shift=None):
            _shift = state["selected_guide_time_idx"] if shift is None else shift
            idx = ui.clamp_guide_time_idx(live + _shift, columns)
            vs, ve = idx * 1800, idx * 1800 + columns * 1800
            stops = []
            for a, b in shows:
                if b <= vs or a >= ve:
                    continue
                sa, sb = max(a, vs), min(b, ve)
                cut = "left" if a < vs else ("right" if b > ve else None)
                key = ("show", a, vs) if window_keyed else ("show", a)
                stops.append({"col": int((sa - vs) // 1800), "abs": a, "key": key, "vis": (sb - sa) / 1800.0 if cut else 99.0, "cut": cut})
            state["guide_current_row_stops"] = stops
        refresh()
        ns = {"_log_warn_throttled": lambda *a, **k: None, "app_state": state, "db": object(), "performance_governor": None,
              "get_guide_num_cols": lambda d: columns, "_guide_dirty_event": threading.Event(), "_GUIDE_MIN_VISIBLE_COLUMNS": 0.4,
              "broadcast_clock": types.SimpleNamespace(now=lambda: now), "clamp_guide_time_idx": ui.clamp_guide_time_idx,
              "_refresh_guide_row_stops_offscreen": refresh}
        exec(get_function_source("_guide_jump_col"), ns)
        trail = []
        for _ in range(presses):
            ns["_guide_jump_col"](direction)
            refresh()
            idx = ui.clamp_guide_time_idx(live + state["selected_guide_time_idx"], columns)
            trail.append((state["guide_selected_abs_time"], idx * 1800, idx * 1800 + columns * 1800))
        return state, trail

    def test_right_finds_every_next_spot_even_when_a_spot_changes_its_key_with_the_window(self):
        state, trail = self._jump(1, 40)
        abses = [a for a, _vs, _ve in trail]
        self.assertEqual(abses, sorted(set(abses)), "every press moves one spot right, none repeats or goes back")
        self.assertTrue(all(vs - 1 <= a < ve for a, vs, ve in trail), "the highlight is inside the window after every press")

    def test_paging_right_keeps_the_highlight_on_the_right_side(self):
        # WARNING: owner 2026-11-23: at the right side the highlight stays there and the page moves on with each press, never back to the left.
        state, trail = self._jump(1, 40)
        scrolled = [(a, vs, ve) for (a, vs, ve), (_pa, pvs, _pve) in zip(trail[1:], trail[:-1]) if vs != pvs]
        self.assertTrue(len(scrolled) >= 10, "the page moved on %d times" % len(scrolled))
        for a, vs, ve in scrolled:
            self.assertGreaterEqual(a, ve - 2 * 1800, "after the page moves on, the highlight at %s is in the last columns of %s to %s, not back on the left" % (a, vs, ve))

    def test_left_finds_every_previous_spot_even_when_a_spot_changes_its_key_with_the_window(self):
        state, trail = self._jump(-1, 20)
        abses = [a for a, _vs, _ve in trail]
        moved = [a for i, a in enumerate(abses) if i == 0 or a != abses[i - 1]]
        self.assertEqual(moved, sorted(set(moved), reverse=True), "every press moves one spot left, none repeats or goes forward")
        self.assertTrue(all(a == moved[-1] for a in abses[abses.index(moved[-1]):]), "once at today's first show the highlight stays there")
        self.assertLessEqual(moved[-1], 1800, "going left reaches the first show of today")
        self.assertTrue(all(vs - 1 <= a < ve or a < vs for a, vs, ve in trail))

    def test_a_highlight_outside_the_window_is_put_back_inside_it(self):
        import ui
        state, trail = self._jump(1, 1, highlight_abs=124281)
        a, vs, ve = trail[0]
        self.assertTrue(vs - 1 <= a < ve, "the highlight at %s is inside the window %s to %s" % (a, vs, ve))

    def test_a_channel_tuned_from_the_guide_never_shows_the_guide_left_on_screen(self):
        """The guide marks itself as the last thing drawn, the channel starts from the cover, and its first picture clears the mark."""
