class TestTuneThreadNeverWaitsOnAShare(unittest.TestCase):
    """Owner 2026-11-16: a channel change sat 5 s in os.stat on a share that had stopped answering, then fell to Static with the banner"""

    def test_the_channel_open_thread_gets_the_same_bounded_share_check_as_the_screen_thread(self):
        """On content-activate a stat of a share path that does not answer gives up in a fraction of a second and marks the share down."""
        import media_library as ml
        import time as _t
        real_stat = ml.os.stat
        release = threading.Event()

        def slow_stat(path, *a, **k):
            release.wait(5.0)
            return real_stat(__file__)
        ml.os.stat = slow_stat
        ml._stat_cache.clear()
        result = {}

        def _tune():
            t0 = _t.monotonic()
            try:
                ml.stat_for_screen_thread("\\\\unreachable-server\\Movies\\a.mp4")
            except OSError as e:
                result["err"] = e
            result["took"] = _t.monotonic() - t0
        try:
            th = threading.Thread(target=_tune, name="content-activate")
            th.start()
            th.join(4.0)
        finally:
            release.set()
            ml.os.stat = real_stat
            ml._share_down_until.clear()
        self.assertIn("err", result, "the check gave up with an error instead of waiting")
        self.assertLess(result["took"], 2.0)

    def test_a_thread_with_another_name_is_not_bounded(self):
        """Only the screen thread and the channel-open thread are held to the short wait."""
        import media_library as ml
        out = {}

        def _other():
            out["critical"] = ml._is_screen_critical_thread()
        th = threading.Thread(target=_other, name="SomethingElse")
        th.start()
        th.join()
        self.assertFalse(out["critical"])

    def test_the_identity_key_is_never_hashed_on_the_channel_open_thread(self):
        """resolve queues the file for the background keyer on both critical threads."""
        import inspect
        import media_library as ml
        src = inspect.getsource(ml.PathKeyResolver.resolve)
        self.assertIn("_is_screen_critical_thread()", src)


