class TestLiveAudioStream(unittest.TestCase):
    """Owner 2026-11-15: live captions cut each window from one running ffmpeg instead of starting ffmpeg for every window."""

    def _file(self):
        import subprocess
        import tempfile
        d = tempfile.mkdtemp()
        f = os.path.join(d, "t.mkv")
        subprocess.run(["ffmpeg", "-y", "-loglevel", "error", "-f", "lavfi", "-i", "sine=frequency=440:duration=40",
                        "-f", "lavfi", "-i", "color=c=black:s=64x48:d=40", "-shortest", f], check=True)
        return d, f

    def test_windows_come_from_one_stream_with_the_right_length_and_the_end_is_short(self):
        import wave
        import media
        d, f = self._file()
        media._resolve_ffmpeg_path = lambda: "ffmpeg"
        s = media._LiveAudioStream(f, 5.0, None, 4.0).start()
        try:
            out = os.path.join(d, "a.wav")
            self.assertEqual(s.window(5.0, 5.0, out), "ok")
            self.assertAlmostEqual(wave.open(out).getnframes() / 16000.0, 5.0, delta=0.05)
            self.assertTrue(s.covers(10.0))
            self.assertFalse(s.covers(500.0), "far ahead needs a fresh seek")
            self.assertEqual(s.window(30.0, 30.0, out), "ok")
            self.assertAlmostEqual(wave.open(out).getnframes() / 16000.0, 10.0, delta=0.2, msg="the file ends at 40 s")
        finally:
            s.close()

    def test_the_loudness_scan_can_find_speech_in_the_captions_the_program_made(self):
        """Owner 2026-11-15: with no subtitle file or stream, the captions faster-whisper already made for the file give the speech places before the center channel is used."""
        src = open(_script("media.py"), encoding="utf-8").read()
        body = src[src.index("def _resolve_dialogue_basis"):src.index("def _lufs_sample_windows")]
        self.assertLess(body.index("_embedded_text_subtitle_stream(header)"), body.index("_asr_paths(file_path)[0]"))
        self.assertLess(body.index("_asr_paths(file_path)[0]"), body.index("_header_has_center_channel"))

    def test_the_stream_does_not_use_the_wave_module_the_packaged_program_lacks(self):
        """The V1.9.8 test build failed every caption session with No module named 'wave'; the wav header is written by hand."""
        src = open(_script("media.py"), encoding="utf-8").read()
        part = src[src.index("class _LiveAudioStream:"):src.index("def _asr_cleanup_orphan_wavs")]
        self.assertNotIn("import wave", part)

    def test_a_window_before_what_was_dropped_is_not_covered_and_the_session_uses_the_stream_and_closes_it(self):
        import media
        d, f = self._file()
        media._resolve_ffmpeg_path = lambda: "ffmpeg"
        s = media._LiveAudioStream(f, 0.0, None, 4.0).start()
        try:
            out = os.path.join(d, "a.wav")
            s.window(0.0, 5.0, out)
            s.window(10.0, 5.0, out)
            self.assertFalse(s.covers(2.0), "audio before the last window's start is dropped")
        finally:
            s.close()
        self.assertFalse(s.covers(10.0), "a closed stream covers nothing")
        src = open(_script("media.py"), encoding="utf-8").read()
        run = src[src.index("    def _run_locked(self):"):src.index("# SECTION: Media errors")]
        self.assertIn("self._extract_window(pos, audio_end - pos, wav_path)", run)
        self.assertNotIn("_asr_extract_chunk(self.file_path, pos, audio_end - pos", run)


class TestSpeechDetectionForLoudness(unittest.TestCase):
    """Owner 2026-11-16: a file with no subtitle gets its speech places from the caption model's voice detector inside the same decode as the loudness window, and never by loading the model."""

    def _src(self):
        return open(_script("media.py"), encoding="utf-8").read()

    def test_with_no_usable_model_nothing_is_detected(self):
        """No model, no samples or a model that cannot be loaded give None so the window falls back to the whole mix."""
        import media
        saved = media._speech_listener
        try:
            media._speech_listener = lambda: None
            self.assertIsNone(media._detect_spans_in_pcm(b"\x00\x00" * 100))
            self.assertIsNone(media._detect_spans_in_pcm(b""))
        finally:
            media._speech_listener = saved

    def test_spans_come_back_in_seconds_from_the_start_of_the_window(self):
        """The detector answers in samples at 16 kHz; the window code needs seconds from the window start."""
        import media

        class _Model:
            dead = False

            def speech_spans(self, audio, threshold, min_silence_ms, min_speech_ms):
                self.n = len(audio)
                return [{"start": 16000 * 5, "end": 16000 * 25}]

        saved = media._speech_listener
        model = _Model()
        media._speech_listener = lambda: model
        try:
            spans = media._detect_spans_in_pcm(b"\x00\x00" * 16000 * 60)
        finally:
            media._speech_listener = saved
        self.assertEqual(spans, [(5.0, 25.0)])
        self.assertEqual(model.n, 16000 * 60)

    def test_the_window_decode_feeds_the_detector_through_a_third_output(self):
        """One ffmpeg run per window: loudness branch, plus a 16 kHz mono sample output only for the detect method."""
        src = self._src()
        body = src[src.index("def _lufs_window_ffmpeg_inner"):src.index("def _combine_lufs_readings")]
        self.assertIn('_want_vad = _method == "detect"', body)
        self.assertIn("aresample=16000,aformat=sample_fmts=s16:channel_layouts=mono[vad]", body)
        self.assertIn('"-f", "s16le", "pipe:1"', body)
        self.assertIn("_detect_spans_in_pcm(result.stdout)", body)

    def test_the_source_order_is_subtitles_then_made_captions_then_detection_then_center_channel(self):
        """Detection is chosen as a basis only; the pass of its own is gone."""
        src = self._src()
        body = src[src.index("def _resolve_dialogue_basis"):src.index("def _lufs_sample_windows")]
        self.assertLess(body.index("_embedded_text_subtitle_stream(header)"), body.index("_asr_paths(file_path)[0]"))
        self.assertLess(body.index("_asr_paths(file_path)[0]"), body.index('"method": "detect"'))
        self.assertLess(body.index('"method": "detect"'), body.index("_header_has_center_channel"))
        self.assertNotIn("_get_whisper_model(", src[src.index("def _detect_spans_in_pcm"):src.index("def _resolve_dialogue_basis")], "the scan goes through _speech_listener only")
        self.assertNotIn("def _speech_detect_spans", src)

    def test_the_listener_loads_for_the_scan_without_touching_live_captions(self):
        """A scan's memory refusal must not switch Live Captions off, and a refusal is not retried for a minute (no log spam)."""
        import media
        calls = []
        saved = (media._get_whisper_model, media._whisper_model, media._speech_listener_retry_at)
        media._whisper_model = None
        media._speech_listener_retry_at = 0.0
        media._get_whisper_model = lambda for_scan=False: calls.append(for_scan)
        try:
            self.assertIsNone(media._speech_listener())
            self.assertIsNone(media._speech_listener())
        finally:
            media._get_whisper_model, media._whisper_model, media._speech_listener_retry_at = saved
        self.assertEqual(calls, [True], "one try, the second call waits out the retry time")
        src = self._src()
        self.assertIn("_caption_memory_allows_load(notify=not for_scan)", src)
        self.assertIn("handler = _caption_memory_refusal_handler if notify else None", src)

    def test_the_idle_watch_keeps_the_model_while_scans_keep_using_it(self):
        """The model sleeps WHISPER_IDLE_UNLOAD_SECONDS after the last scan use, not while a batch of scans is running."""
        src = self._src()
        body = src[src.index("def _whisper_idle_watch_start"):src.index("def release_whisper_model")]
        self.assertIn("(time.monotonic() - _speech_listener_last_used) < limit_s", body)

    def test_a_detect_window_with_too_little_speech_gives_no_spoken_reading_and_the_scan_falls_back(self):
        """Windows under the minimum speech seconds record nothing; the existing window code then keeps the whole-mix reading."""
        src = self._src()
        body = src[src.index("def _lufs_window_ffmpeg_inner"):src.index("def _combine_lufs_readings")]
        self.assertIn("speech_seconds >= DIALOGUE_MIN_WINDOW_SECONDS", body)


class TestRepeatedWarningsWriteOnce(unittest.TestCase):
    """Owner 2026-11-15: one missing file wrote the same warning 3,700 times"""

    def test_the_same_warning_for_the_same_file_is_written_once_and_another_file_still_writes(self):
        media._media_warning_last.clear()
        lines = []
        real = media.log.warning
        media.log.warning = lambda fmt, *a: lines.append(fmt % a if a else fmt)
        try:
            for _ in range(5):
                media._media_warning("k", "[DRIVE HEALTH] real read of %s fails", "\\\\srv\\a.mkv")
            media._media_warning("k", "[DRIVE HEALTH] real read of %s fails", "\\\\srv\\b.mkv")
        finally:
            media.log.warning = real
            media._media_warning_last.clear()
        self.assertEqual(len(lines), 2)
        self.assertEqual(gov.MEDIA_WARNING_REPEAT_SECONDS, 600.0)

    def test_a_missing_file_on_a_folder_that_answers_is_reported_gone_not_dead(self):
        with tempfile.TemporaryDirectory() as tmp:
            root = os.path.join(tmp, "share")
            os.makedirs(root)
            missing = os.path.join(root, "gone.mkv")
            media._file_probe_state[root] = {"last_result": False, "checked_at": 0, "checking_since": 1, "path": missing}
            media._media_warning_last.clear()
            real = media.log.warning
            lines = []
            media.log.warning = lambda fmt, *a: lines.append(fmt % a if a else fmt)
            try:
                for _ in range(4):
                    media._file_probe_state[root]["checking_since"] = 1
                    media._file_probe_worker(root, missing)
            finally:
                media.log.warning = real
                media._media_warning_last.clear()
                media._file_probe_state.pop(root, None)
        self.assertEqual(len(lines), 1)
        self.assertIn("is gone from it", lines[0])

    def test_a_folder_that_does_not_answer_is_still_a_failed_probe(self):
        root = os.path.join(tempfile.gettempdir(), "no_such_share_xyz")
        path = os.path.join(root, "a.mkv")
        media._file_probe_state[root] = {"last_result": None, "checked_at": 0, "checking_since": 1, "path": path}
        media._media_warning_last.clear()
        real = media.log.warning
        media.log.warning = lambda *a: None
        try:
            media._file_probe_worker(root, path)
            result = media._file_probe_state[root]["last_result"]
        finally:
            media.log.warning = real
            media._media_warning_last.clear()
            media._file_probe_state.pop(root, None)
        self.assertIs(result, False)

    def test_a_thread_stuck_again_and_again_is_reported_in_full_once(self):
        from tests import health_monitor as hm
        mon = hm._Monitor.__new__(hm._Monitor)
        mon.stuck_reports = 0
        mon._stuck_last = {}
        mon.last_dump = time.monotonic()
        lines = []
        with mock.patch.object(hm.log, "warning", lambda fmt, *a: lines.append(fmt % a if a else fmt)):
            for _ in range(6):
                mon.report_stuck("ShareRelayConn", sys._getframe(), 12.0, "thread")
        self.assertEqual(len(lines), 1)
        self.assertEqual(mon._stuck_last["ShareRelayConn"][1], 5)

    def test_the_relay_index_warning_for_one_file_is_written_once(self):
        import share_relay
        share_relay._index_warned.clear()
        lines = []
        with mock.patch.object(share_relay.log, "warning", lambda fmt, *a: lines.append(fmt % a if a else fmt)):
            class _Gone:
                fill_lock = threading.Lock()
                def acquire(self):
                    raise OSError("gone")
                def release(self, handle, ok=False):
                    pass
            with mock.patch.object(share_relay, "_cache_file", lambda p: "x.cache"):
                for _ in range(5):
                    share_relay.ensure_index("\\\\srv\\a.mkv", source=_Gone())
        share_relay._index_warned.clear()
        self.assertEqual(len(lines), 1)

    def test_the_frame_gap_line_is_capped_and_counts_the_slow_frames(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("FRAME_GAP_LOG_GAP_MS", src)
        self.assertIn("slow frames since the last line", src)
        self.assertEqual(gov.FRAME_GAP_LOG_GAP_MS, 10000)

    def test_a_late_caption_line_says_whether_the_cue_reached_the_store_before_or_after_its_start(self):
        cls = None
        for value in vars(media).values():
            if isinstance(value, type) and hasattr(value, "_stamp_new_cues"):
                cls = value
        self.assertIsNotNone(cls)
        obj = cls.__new__(cls)
        obj.lock = threading.RLock()
        obj._cue_stamp = {}
        obj.cues = [[100.0, 102.0, "early"], [110.0, 111.0, "late"]]
        obj._playback_sec = lambda: 105.0
        obj._stamp_new_cues()
        self.assertEqual(obj.cue_store_lead_ms(100000.0), -5000, "stamped at 105 s, so 5 s after its start")
        obj._playback_sec = lambda: 90.0
        obj.cues.append([120.0, 121.0, "ahead"])
        obj._stamp_new_cues()
        self.assertEqual(obj.cue_store_lead_ms(120000.0), 30000)
        self.assertIsNone(obj.cue_store_lead_ms(5000.0))

