    def test_live_captions_pause_and_try_again_after_failed_windows_before_giving_up(self):
        self.assertEqual((gov.LIVE_CAPTION_FAILURE_PAUSE_SECONDS, gov.LIVE_CAPTION_FAILURE_RETRIES), (60.0, 3))
        session = media.LiveCaptionSession.__new__(media.LiveCaptionSession) if hasattr(media, "LiveCaptionSession") else None
        cls = type(session) if session is not None else None
        if cls is None:
            for value in vars(media).values():
                if isinstance(value, type) and hasattr(value, "_pause_after_failures"):
                    cls = value
                    break
        self.assertIsNotNone(cls, "the live caption session class has the pause helper")
        obj = cls.__new__(cls)
        obj._stopped = lambda: False
        lines = []
        with mock.patch.object(media, "_LIVE_CAPTION_FAILURE_PAUSE_SECONDS", 0.05), \
                mock.patch.object(media.log, "warning", lambda fmt, *a: lines.append(fmt % a)):
            self.assertTrue(obj._pause_after_failures("a.avi", 0, "ffmpeg could not read the audio"))
            self.assertTrue(obj._pause_after_failures("a.avi", 2, "ffmpeg could not read the audio"))
            self.assertFalse(obj._pause_after_failures("a.avi", 3, "ffmpeg could not read the audio"))
        self.assertEqual(len(lines), 2, "one warning for each pause, none when it gives up")
        obj._stopped = lambda: True
        with mock.patch.object(media, "_LIVE_CAPTION_FAILURE_PAUSE_SECONDS", 5.0), mock.patch.object(media.log, "warning", lambda *a: None):
            self.assertFalse(obj._pause_after_failures("a.avi", 0, "x"), "a stopped session does not wait")

    def test_the_local_scan_compare_writes_one_line_per_file_for_a_few_files_and_changes_nothing(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("LOCAL_SCAN_COMPARE_MAX_FILES = performance_governor")
        end = src.index("def _log_loudness_result(")
        logged, scans = [], []

        def fake_scan(path, shortfall_out=None, db=None):
            scans.append((path, db))
            shortfall_out.update({"measured_lufs": -30.0, "basis": "dialogue", "windows": [1, 2], "true_peak": -3.0})
            return 2.0
        ns = {"threading": threading, "os": os, "math": math, "performance_governor": gov, "_wait_for_stream_buffer": lambda *a, **k: True,
              "log": types.SimpleNamespace(info=lambda fmt, *a: logged.append(fmt % a if a else fmt)),
              "_log_swallowed": lambda *a: logged.append("SWALLOWED %s" % (a,)), "db": object(), "_gain_context": lambda: "user:srv:slot",
              "server_remote_files": types.SimpleNamespace(server_owns=lambda p: True),
              "_app_shutting_down": types.SimpleNamespace(wait=lambda t: False),
              "_get_library_gain": lambda p: 1.0,
              "media": types.SimpleNamespace(get_media_loudness_gain=fake_scan, TARGET_LUFS=-24.0, LOUDNESS_GAIN_OFFSET_DB=7.0)}
        exec(src[start:end], ns)
        ns["LOCAL_SCAN_COMPARE_MAX_FILES"] = 2
        for name in ("a.mkv", "b.mkv", "c.mkv"):
            ns["_start_local_scan_compare"](name)
            end_wait = time.time() + 3
            while ns["_local_scan_compare"]["running"] and time.time() < end_wait:
                time.sleep(0.01)
        self.assertEqual(len(logged), 2, "only the first two files are measured again")
        self.assertIn("[LOUDNESS COMPARE]", logged[0])
        self.assertIn("difference (here minus Server) +6.0 dB", logged[0])
        self.assertTrue(all(d is None for _p, d in scans), "nothing is stored: the scan gets no database")
        ns["_gain_context"] = lambda: "regular"
        ns["_local_scan_compare"]["files"].clear()
        ns["_start_local_scan_compare"]("d.mkv")
        self.assertEqual(len(logged), 2, "regular mode never compares")

