    def test_the_screen_does_not_wait_for_a_guide_build_the_background_thread_is_running(self):
        import ui
        lock = ui._guide_build_lock
        started, release, result = threading.Event(), threading.Event(), {}
        def holder():
            with lock:
                started.set()
                release.wait(5)
        t = threading.Thread(target=holder, name="GuidePreloader"); t.start()
        started.wait(2)
        try:
            self.assertTrue(lock.held_by_another_thread())
            saved = dict(ui._guide_frame_cache)
            ui._guide_frame_cache["canvas"] = None
            begun = time.monotonic()
            ui.render_tv_guide_async(mock.MagicMock(get_size=lambda: (640, 480)), {}, None, None)
            result["took"] = time.monotonic() - begun
            ui._guide_frame_cache.update(saved)
        finally:
            release.set(); t.join()
        self.assertLess(result["took"], 0.5)

    def test_the_guide_build_thread_does_not_probe_a_path_it_holds_no_status_for(self):
        path = "\\\\srv\\share\\never_seen_xyz.mkv"
        media._path_exists_cache.pop(path, None)
        media.allow_stale_path_status(True)
        try:
            with mock.patch.object(media, "_check_path_status_now", side_effect=AssertionError("probed")):
                got = media._path_status(path)
        finally:
            media.allow_stale_path_status(False)
            media._path_refresh_queue.pop(path, None)
        self.assertEqual(got, media.PATH_UNKNOWN)




