class TestKeepAwakeReadsAreNotAnsweredFromMemory(unittest.TestCase):
    def test_deep_read_rotates_files_and_reads_inside_the_file(self):
        import random as _random
        reads = []

        class _Spy:
            def __init__(self, f): self._f = f
            def __enter__(self): self._f.__enter__(); return self
            def __exit__(self, *a): return self._f.__exit__(*a)
            def seek(self, n): reads.append(("seek", self.path, n)); return self._f.seek(n)
            def read(self, n): return self._f.read(n)
            def fileno(self): return self._f.fileno()

        with tempfile.TemporaryDirectory() as tmp:
            files = []
            for name in ("a.mp4", "b.mp4"):
                path = os.path.join(tmp, name)
                with open(path, "wb") as handle:
                    handle.write(b"x" * 400000)
                files.append(path)
            counter = [0]
            ns = {"os": os, "time": time, "random": _random, "_keep_awake_round": counter, "_log_swallowed": lambda *a: None,
                  "_drive_profile_store": lambda: None, "log": logging.getLogger("t"),
                  "drive_profile": __import__("drive_profile")}
            exec(compile(get_function_source("_wake_drive_with_read"), "<extracted>", "exec"), ns)
            real_open = open
            opened = []

            def _spy_open(path, mode="r", *a, **k):
                opened.append(path)
                return real_open(path, mode, *a, **k)
            ns["open"] = _spy_open
            self.assertTrue(ns["_wake_drive_with_read"]("/", files, time.monotonic() + 5, deep=True))
            counter[0] += 1
            self.assertTrue(ns["_wake_drive_with_read"]("/", files, time.monotonic() + 5, deep=True))
            self.assertEqual(opened, [files[0], files[1]])
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("_wake_drive_with_read(_root, _paths, deadline, deep=True)", src)
        self.assertEqual(gov.DRIVE_KEEP_AWAKE_INTERVAL_SECONDS, 120.0)


