class TestCaptionScanIsPacedByItsLead(unittest.TestCase):
    def test_the_numbers_live_in_the_governor_and_media_matches(self):
        self.assertEqual((gov.LIVE_CAPTION_MIN_LEAD_SEC, gov.LIVE_CAPTION_EASE_LEAD_SEC, gov.LIVE_CAPTION_HIGH_LEAD_SEC), (20.0, 60.0, 120.0))
        self.assertEqual((gov.LIVE_CAPTION_EASE_START_SPEED, gov.LIVE_CAPTION_SLOW_SPEED), (1.3, 0.6))
        self.assertEqual(gov.LIVE_CAPTION_PREFETCH_CHUNK_SEC, 30.0)
        self.assertEqual(gov.LIVE_CAPTION_PREFETCH_CAP_SEC, 120.0)
        self.assertEqual(gov.CAPTION_CATCHUP_AHEAD_SEC, 45.0)
        self.assertEqual(media._LIVE_CAPTION_MIN_LEAD_SEC, gov.LIVE_CAPTION_MIN_LEAD_SEC)
        self.assertEqual(media._LIVE_CAPTION_EASE_LEAD_SEC, gov.LIVE_CAPTION_EASE_LEAD_SEC)
        self.assertEqual(media._LIVE_CAPTION_HIGH_LEAD_SEC, gov.LIVE_CAPTION_HIGH_LEAD_SEC)
        self.assertEqual(media._LIVE_CAPTION_EASE_START_SPEED, gov.LIVE_CAPTION_EASE_START_SPEED)
        self.assertEqual(media._LIVE_CAPTION_SLOW_SPEED, gov.LIVE_CAPTION_SLOW_SPEED)

    def test_zones_by_lead(self):
        self.assertEqual(media._live_caption_zone(None), "boost")
        self.assertEqual(media._live_caption_zone(-5.0), "boost")
        self.assertEqual(media._live_caption_zone(19.9), "boost")
        self.assertEqual(media._live_caption_zone(20.0), "full")
        self.assertEqual(media._live_caption_zone(59.9), "full")
        self.assertEqual(media._live_caption_zone(60.0), "ease")
        self.assertEqual(media._live_caption_zone(119.9), "ease")
        self.assertEqual(media._live_caption_zone(120.0), "slow")
        self.assertEqual(media._live_caption_zone(400.0), "slow")

    def test_speed_is_unlimited_until_the_ease_lead_then_eases_down_and_stays_slow(self):
        self.assertIsNone(media._live_caption_pace_speed(None))
        self.assertIsNone(media._live_caption_pace_speed(0.0))
        self.assertIsNone(media._live_caption_pace_speed(59.9))
        self.assertAlmostEqual(media._live_caption_pace_speed(60.0), 1.3)
        self.assertAlmostEqual(media._live_caption_pace_speed(90.0), 0.95)
        self.assertAlmostEqual(media._live_caption_pace_speed(120.0), 0.6)
        self.assertAlmostEqual(media._live_caption_pace_speed(300.0), 0.6)
        speeds = [media._live_caption_pace_speed(x) for x in range(60, 121, 5)]
        self.assertEqual(speeds, sorted(speeds, reverse=True))

    def test_wait_after_a_chunk_never_negative_and_zero_below_the_ease_lead(self):
        self.assertEqual(media._live_caption_pace_wait(10.0, 30.0, 5.0), 0.0)
        self.assertEqual(media._live_caption_pace_wait(59.0, 30.0, 5.0), 0.0)
        self.assertAlmostEqual(media._live_caption_pace_wait(120.0, 30.0, 10.0), 40.0)
        self.assertEqual(media._live_caption_pace_wait(120.0, 30.0, 80.0), 0.0)
        self.assertAlmostEqual(media._live_caption_pace_wait(60.0, 30.0, 10.0), 30.0 / 1.3 - 10.0)

    def test_a_slow_scan_still_loses_its_lead_slower_than_the_picture_plays(self):
        lead = 150.0
        for _ in range(6):
            wall = max(10.0, 30.0 / media._live_caption_pace_speed(lead))
            lead += 30.0 - wall
        self.assertGreater(lead, 150.0 - 6 * 20.0)
        self.assertLess(lead, 150.0)

    def test_the_session_waits_with_the_pace_and_starts_each_chunk_small_after_a_skip(self):
        src = open(_script("media.py"), encoding="utf-8").read()
