class TestLeavingAServerNeverReturnsToAChannelThatIsOff(unittest.TestCase):
    def _run(self, saved, active_channels):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        body = "def _restart_playback_after_source_change" + src.split("def _restart_playback_after_source_change", 1)[1].split("\ndef _execute_manage_server", 1)[0]
        tuned = []
        allowed = list(active_channels)
        state = {"current_channel": "09"}
        if saved is not None:
            state["channel_before_server"] = saved

        def _nearest(off, allowed_keys):
            cands = [c for c in allowed_keys if c != str(off).zfill(2)]
            return min(cands, key=lambda c: (abs(int(c) - int(off)), -int(c))) if cands else None

        ns = {"_clear_last_video_frame": lambda: None, "SERVER_PICK_BLANK_MAX_SECONDS": 10.0, "pygame": pygame, "app_state": state, "log": __import__("logging").getLogger("t_leave"), "vlc_engine": None,
              "db": types.SimpleNamespace(channels_db={k: {"active": True} for k in active_channels}),
              "_guide_dirty_event": threading.Event(),
              "_allowed_channel_keys": lambda: allowed, "_nearest_allowed_channel": _nearest,
              "change_channel": lambda ch, **kw: tuned.append(ch)}
        exec(body, ns)
        ns["_restart_playback_after_source_change"]("test", restore_channel=True)
        return tuned

    def test_a_remembered_channel_that_is_on_is_used(self):
        self.assertEqual(self._run("14", ["05", "14"]), ["14"])

    def test_a_remembered_channel_that_is_off_goes_to_the_closest_one_that_is_on(self):
        self.assertEqual(self._run("09", ["05"]), ["05"])
        self.assertEqual(self._run("09", ["05", "12"]), ["12"])


