            open(os.path.join(d, "temp", "app_log.txt"), "w").write("".join("line %d %s\n" % (i, "x" * 60) for i in range(40000)))
            open(os.path.join(d, "old.zip"), "w").write("not a log")
            out = os.path.join(d, "temp", "send_logs.zip")
            size = ns["_build_send_logs_zip"](out, "Channel 07 froze", d, 400000, 1000000, 60000)
