class TestPickedLocalProfileStartsThroughTheOneStartLoader(unittest.TestCase):
    """Owner 2026-11-11: editing a server starts on the regular file; a picked server profile on this computer starts on the profile, through the same loader, with no second start path in the script."""

    def _start(self, **cfg):
        tmp = tempfile.mkdtemp()
        rdb, restore = _settings_writer_db(tmp, 0.05)
        try:
            rdb.create_server_slot("Den", "server1")
            slot_path = rdb.get_server_slot_path("server1")
            with open(slot_path, "w") as f:
                json.dump({"channels": {"09": {"active": True, "name": "ProfileNine", "schedules": {"Full Day": [{"path": "C:\\\\nine.mp4"}]}}}}, f)
            config = dict(rdb.config)
            config.update({"server_mode_enabled": True, "server_role": "user", "active_server_slot": "server1",
                           "last_server_pick": {"name": "Den", "slot_id": "server1", "local": True}})
            config.update(cfg)
            with open(rdb.config_path, "w") as f:
                json.dump({"config": config, "channels": {"05": {"active": True, "name": "MainFive"}}}, f)
        finally:
            restore()
        old = sys.argv[0]
        sys.argv[0] = os.path.join(tmp, "Retro TV Emulator.exe")
        try:
            fresh = media.RetroDatabase()
        finally:
            sys.argv[0] = old
        deadline = time.monotonic() + 10.0
        while not fresh.ready_flag and time.monotonic() < deadline:
            time.sleep(0.02)
        return fresh

    def test_a_picked_profile_starts_on_the_profile_and_editing_a_server_starts_on_the_servers_file(self):
        picked = self._start()
        self.assertNotEqual(picked.channels_path, picked.config_path)
        self.assertEqual(picked.channels_path, picked.get_user_profile_path("Den"), "the User's own copy is what is open, never the server's file")
        self.assertIsNone(picked.config.get("active_server_slot"))
        self.assertIn("09", picked.channels_db)
        editing = self._start(server_role="server")
        # WARNING: owner 2026-11-15: a server left under construction is ended at the next start, so the start is the regular file.
        self.assertEqual(editing.channels_path, editing.config_path)
        self.assertIsNone(editing.config.get("active_server_slot"))

    def test_a_users_picked_profile_is_locked_like_a_streamed_server_and_never_written_back_with_the_lock_or_this_pcs_picks(self):
        picked = self._start(server_visualizer_overrides={"09": "Waves"}, server_watermark_overrides={"09": True})
        self.assertIsNot(picked.channels_db["09"].get("watermark_enabled"), True, "this PC's old watermark pick is not applied")
        record = picked.channels_db["09"]
        self.assertTrue(record["server_locked"])
        self.assertEqual(record["visualizer_style"], "Waves")
        picked.save_channels(force=True)
        with open(picked.channels_path) as f:
            on_disk = json.load(f)["channels"]["09"]
        self.assertNotIn("server_locked", on_disk)
        self.assertNotEqual(on_disk.get("visualizer_style"), "Waves")
        self.assertNotEqual(on_disk.get("watermark_enabled"), True)
        editing = self._start(server_role="server", active_server_slot="server1")
        self.assertFalse(any(r.get("server_locked") for r in editing.channels_db.values() if isinstance(r, dict)))

    def test_helper_picks_only_a_users_local_profile_that_still_exists(self):
        src = open(_script("media.py"), encoding="utf-8").read()
        body = "def saved_local_profile_slot" + src.split("def saved_local_profile_slot", 1)[1].split("\n    def ", 1)[0]
        body = textwrap.dedent("    " + body)
        for cfg, exists, want in (
                ({"last_server_pick": {"name": "Den", "slot_id": "server1", "local": True}, "server_role": "user", "server_mode_enabled": True}, True, "server1"),
                ({"last_server_pick": {"name": "Den", "slot_id": "server1", "local": True}, "server_role": "server", "server_mode_enabled": True}, True, None),
                ({"last_server_pick": {"name": "Den", "slot_id": "server1", "local": True}, "server_role": "user", "server_mode_enabled": False}, True, None),
                ({"last_server_pick": {"name": "Den", "slot_id": "server1", "local": False}, "server_role": "user", "server_mode_enabled": True}, True, None),
                ({"last_server_pick": None, "server_role": "user", "server_mode_enabled": True}, True, None),
                ({"last_server_pick": {"name": "Den", "slot_id": "server1", "local": True}, "server_role": "user", "server_mode_enabled": True}, False, None)):
            fake = types.SimpleNamespace(config=cfg, list_server_slots=lambda: [("server1", "Den")],
                                         get_server_slot_path=lambda s: "p", )
            ns = {"os": types.SimpleNamespace(path=types.SimpleNamespace(exists=lambda p: exists))}
            exec(body, ns)
            self.assertEqual(ns["saved_local_profile_slot"](fake), want, cfg)

    def test_the_one_loader_reads_the_choice_and_the_script_has_no_second_start(self):
        media_src = open(_script("media.py"), encoding="utf-8").read()
        self.assertEqual(media_src.count("self.saved_local_profile_slot()"), 1)
        self.assertIn("if _starting:\n                    self.channels_db = self._build_channels_db(_start_raw_channels)", media_src)
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertNotIn("_start_on_saved_local_pick", src)
        self.assertLess(src.index("_adopt_profile_the_start_opened()\n"), src.index("change_channel(_last_ch, is_boot=True)"))


