        ns, saves = self._ns(config)
        ns["_set_scanned_servers"]([{"name": "Den", "slot_id": "server1", "host": "", "local": True},
                                    {"name": "Steven", "slot_id": "server1", "host": "10.0.0.5", "port": 47532, "extra": 1}])
