class TestVlcPlayerCallsAreMadeOneAtATime(unittest.TestCase):
    """Owner 2026-11-11 (V1.6.9): the crash logs of 2026-11-06, 08, 10 and 11 end inside libvlc player calls with several threads inside libvlc at once, so every call into one player is serialized, with bounded waits so it can never hang."""

    SRC = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()

    def _wrapper(self, getter_wait=0.25, main_wait=0.5, call_wait=5.0, health=None):
        body = "class _SerializedVlcPlayer" + self.SRC.split("class _SerializedVlcPlayer", 1)[1].split("\n\n\n_VLCEngineWrapperClass = None", 1)[0]
        warnings = []
        ns = {"threading": threading, "time": time, "health_monitor": health, "_VLC_GETTER_WAIT_S": getter_wait,
              "_VLC_MAIN_CALL_WAIT_S": main_wait, "_VLC_CALL_WAIT_S": call_wait,
              "_log_warn_throttled": lambda key, msg, *a, **k: warnings.append(key),
              "_time_critical_thread": lambda: threading.current_thread() is threading.main_thread()}
        exec(body, ns)
        return ns["_SerializedVlcPlayer"], warnings

    class _Real:
        def __init__(self, pause=0.0):
            self.inside = 0
            self.max_inside = 0
            self.pause = pause
            self.guard = threading.Lock()
            self.time_value = 5

        def _enter(self, pause=None):
            with self.guard:
                self.inside += 1
                self.max_inside = max(self.max_inside, self.inside)
            time.sleep(self.pause if pause is None else pause)
            with self.guard:
                self.inside -= 1

        def stop(self):
            self._enter()

        def get_time(self):
            self._enter()
            return self.time_value

        def video_set_crop_geometry(self, g):
            self._enter(0.05)

        def event_manager(self):
            return "events"

    def test_calls_from_many_threads_never_overlap(self):
        cls, _ = self._wrapper(getter_wait=60.0, main_wait=60.0, call_wait=60.0)
        real = self._Real(pause=0.002)
        player = cls(real)
        threads = [threading.Thread(target=lambda f=f: [f() for _ in range(15)])
                   for f in (player.stop, player.get_time, lambda: player.video_set_crop_geometry("16:9"))]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        self.assertEqual(real.max_inside, 1)

    def test_without_the_wrapper_the_same_threads_do_overlap(self):
        real = self._Real(pause=0.002)
        threads = [threading.Thread(target=lambda f=f: [f() for _ in range(15)]) for f in (real.stop, real.get_time)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        self.assertGreater(real.max_inside, 1)

    def test_a_read_gives_the_last_answer_when_a_slow_call_holds_the_lock(self):
        cls, warnings = self._wrapper(getter_wait=0.05)
        real = self._Real(pause=0.0)
        player = cls(real)
        self.assertEqual(player.get_time(), 5)
        real.time_value = 99
        real.pause = 0.6
        slow = threading.Thread(target=player.stop)
        slow.start()
        time.sleep(0.1)
        began = time.perf_counter()
        self.assertEqual(player.get_time(), 5)
        self.assertLess(time.perf_counter() - began, 0.4)
        slow.join()
        real.pause = 0.0
        self.assertEqual(player.get_time(), 99)

    def test_a_changing_call_is_skipped_after_its_bounded_wait_never_made_beside_another_and_never_hangs(self):
        """Owner 2026-11-14 (V1.7.9): a crop-geometry call going into libvlc beside a stuck stop crashed the CRT."""
        cls, warnings = self._wrapper(main_wait=0.05, call_wait=0.05)
        real = self._Real(pause=0.5)
        player = cls(real)
        slow = threading.Thread(target=player.stop)
        slow.start()
        time.sleep(0.1)
        began = time.perf_counter()
        player.video_set_crop_geometry("4:3")
        self.assertLess(time.perf_counter() - began, 0.35)
        self.assertEqual(real.max_inside, 1)
        self.assertIn("vlc_serial_timeout_video_set_crop_geometry", warnings)
        slow.join()

    def test_same_thread_may_call_again_and_attributes_pass_through(self):
        cls, _ = self._wrapper()
        real = self._Real()
        player = cls(real)
        self.assertEqual(player.event_manager(), "events")
        with player._lock:
            self.assertEqual(player.get_time(), 5)

    def test_the_engine_uses_the_wrapper_and_vlcs_own_callbacks_use_the_real_player(self):
        self.assertIn("self.player = _SerializedVlcPlayer(self._raw_player, engine_label)", self.SRC)
        for name in ("get_title", "get_length", "get_state"):
            self.assertIn("self._raw_player.%s()" % name, self.SRC)
        start = self.SRC.index("def _on_title_changed(event):")
        end = self.SRC.index("self._lock_cb = vlc.CallbackDecorators", start)
        self.assertNotIn("self.player.get_", self.SRC[start:end])
        self.assertEqual(self.SRC.count(".media_player_new()"), 1)

    def test_governor_numbers(self):
        self.assertEqual((gov.VLC_GETTER_WAIT_SECONDS, gov.VLC_MAIN_CALL_WAIT_SECONDS, gov.VLC_CALL_WAIT_SECONDS), (0.25, 0.5, 5.0))


