class TestEveryBannerFollowsOneClock(unittest.TestCase):
    """Owner 2026-11-16: status, failure and reason banners all go black wait, then Static, then the banner, and one bar draws them all."""

    def _ns(self):
        class _Clock:
            now = 100.0

            @staticmethod
            def monotonic():
                return _Clock.now
        ns = {"time": _Clock, "_banner_phase_seen": {}}
        exec(main_function_code("_banner_phase"), ns)
        return ns, _Clock

    def test_wait_then_show_then_gone_and_leaving_starts_it_again(self):
        """10 s of black wait, 30 s of banner, then gone while the viewer stays; a gap over 1.5 s restarts it."""
        ns, clock = self._ns()
        phase = ns["_banner_phase"]
        seen = []
        for _ in range(0, 450):
            seen.append(phase("k", 10.0, 30.0))
            clock.now += 0.1
        self.assertEqual(seen[0], "wait")
        self.assertEqual(seen[50], "wait")
        self.assertEqual(seen[150], "show")
        self.assertEqual(seen[430], "gone")
        clock.now += 5.0
        self.assertEqual(phase("k", 10.0, 30.0), "wait", "coming back after leaving starts the wait again")

    def test_a_banner_with_no_show_time_stays_until_the_viewer_leaves(self):
        """Reason banners (scanning) have no show time."""
        ns, clock = self._ns()
        phase = ns["_banner_phase"]
        phase("r", 2.0)
        for _ in range(900):
            clock.now += 0.1
            last = phase("r", 2.0)
        self.assertEqual(last, "show")

    def test_the_guide_preview_waits_before_static_and_banner_and_all_banners_share_one_bar(self):
        """The preview of a failed channel is grey and silent for the first-load wait, the failure message only draws in the show phase, and the status bar is the reason bar."""
        src = MAIN_SRC
        self.assertEqual(src.count("_guide_failure_phase(hl_ch)"), 2)
        self.assertIn('if _hl_failure_phase != "wait" and (_hl_ch_confirmed_failed or _guide_transition_style == "static"):', src)
        self.assertIn('_gp_failure_phase == "show"', src)
        self.assertIn("own_clock=False", src)
        bar = main_function_source("_draw_status_banner_bar")
        self.assertIn("_draw_reason_banner_bar(screen, pygame.Rect(0, 0, *screen.get_size()), label, scale=1.0, good=good)", bar)
        self.assertIn("_banner_phase((", main_function_source("_draw_static_reason_banner"))


class TestOneChannelBannerPerVisit(unittest.TestCase):
    """Owner 2026-11-16: banners kept coming back one after another while the viewer sat on the channel"""

    def _ns(self):
        class _Clock:
            ticks = 1000
        pg = types.SimpleNamespace(time=types.SimpleNamespace(get_ticks=lambda: _Clock.ticks))
        ns = {"pygame": pg, "app_state": {"current_channel": "09", "_fault_static_on": True}, "CHANNEL_FAILURE_MESSAGE_MS": 30000,
              "_channel_banner_done": False, "_failure_banner_window": {}, "_status_banner_current": None,
              "_CHANNEL_BANNER_NAMES": ("server", "drive", "missing_media")}
        for name in ("_failure_banner_is_up", "_failure_banner_may_draw", "_mark_channel_banner_done", "_fault_static_is_on"):
            exec(main_function_code(name), ns)
        return ns, _Clock

    def test_the_failure_message_shows_once_for_its_time_and_stays_gone_for_the_visit(self):
        """30 s on screen; a new failure entry from a retry does not bring it back."""
        ns, clock = self._ns()
        may = ns["_failure_banner_may_draw"]
        self.assertTrue(may("09"))
        clock.ticks += 29000
        self.assertTrue(may("09"))
        clock.ticks += 2000
        self.assertFalse(may("09"))
        clock.ticks += 60000
        self.assertFalse(may("09"), "still gone a minute later in the same visit")

    def test_a_channel_banner_waits_for_the_Static_and_the_Static_clears_with_a_picture(self):
        """No banner over a picture or over the black wait; it may show only once the channel is on Static."""
        ns, _clock = self._ns()
        ns["app_state"]["_fault_static_on"] = False
        self.assertFalse(ns["_failure_banner_may_draw"]("09"))
        ns["app_state"]["_fault_static_on"] = True
        self.assertTrue(ns["_failure_banner_may_draw"]("09"))
        src = MAIN_SRC
        self.assertIn('app_state["_fault_static_on"] = False', src[src.index("def _note_fresh_live_video_frame"):src.index("def _note_fresh_live_video_frame") + 2500])
        for name in ("server", "drive", "missing_media"):
            self.assertIn("_fault_static_is_on()", main_function_source("_status_banner_is_active"))

    def test_a_stalled_channel_stays_on_Static_and_a_stopped_picture_goes_straight_to_static(self):
        """owner 2026-11-25: a picture that stops holds only through the short hitch, then goes straight to Static; there is no grey screen between."""
        src = MAIN_SRC
        self.assertIn('_static_hold = bool(app_state.get("_static_hold_until_frame", False))\n', src)
        self.assertNotIn('"_static_hold_until_frame", False)) and not _has_last_video_frame', src)
        self.assertNotIn("STALL_GREY_AFTER_MS", src)
        self.assertFalse(hasattr(gov, "STALL_GREY_AFTER_MS"))
        self.assertNotIn("grey until the Static is due", src)

    def test_another_channel_banner_that_has_had_its_time_keeps_the_failure_message_away(self):
        """Server offline having shown for its 30 s means no failure message follows it."""
        ns, _clock = self._ns()
        ns["_mark_channel_banner_done"]()
        self.assertFalse(ns["_failure_banner_may_draw"]("09"))

    def test_a_channel_banner_showing_now_keeps_the_failure_message_from_starting(self):
        """Never two at once."""
        ns, _clock = self._ns()
        ns["_status_banner_current"] = "server"
        self.assertFalse(ns["_failure_banner_may_draw"]("09"))

    def test_leaving_the_channel_brings_the_banners_back(self):
        """The rearm clears the done flag and every failure window."""
        src = main_function_source("_rearm_banners_on_channel_change")
        self.assertIn("_channel_banner_done = False", src)
        self.assertIn("_failure_banner_window.clear()", src)

    def test_the_status_banners_of_a_channel_share_the_one_showing(self):
        """Server, drive and missing-media banners are consumed together; notices and caption messages are not."""
        consumed = main_function_source("_status_banner_is_consumed")
        self.assertIn("name in _CHANNEL_BANNER_NAMES and (_channel_banner_done or _failure_banner_is_up())", consumed)
        self.assertIn("_mark_channel_banner_done()", main_function_source("_mark_status_banner_consumed"))


class TestBannersStayGoneUntilTheViewerChangesChannel(unittest.TestCase):
    """A banner shows on the channel its error is on, goes after 30 s, and comes back only on a channel change while the error remains"""

    def _ns(self, locked_channels=()):
        ns = {"_banner_last_channel": None, "_drive_streak_signature": None, "_drive_streak_consumed": False,
              "_server_streak_signature": None, "_server_streak_consumed": False,
              "_channel_banner_done": False, "_failure_banner_window": {},
              "_log_swallowed": lambda *a, **k: None}
        class _Db:
            channels_db = {c: {"server_locked": True} for c in locked_channels}
        ns["db"] = _Db()
        exec(compile(get_function_source("_rearm_banners_on_channel_change"), "<banner>", "exec"), ns)
        return ns

    def test_sitting_on_the_channel_never_brings_the_banner_back(self):
        ns = self._ns()
        ns["_drive_streak_signature"] = frozenset({"D:\\"})
        ns["_rearm_banners_on_channel_change"]({"current_channel": "05"})
        ns["_drive_streak_consumed"] = True
        for _ in range(1000):
            ns["_rearm_banners_on_channel_change"]({"current_channel": "05"})
        self.assertTrue(ns["_drive_streak_consumed"])

    def test_a_channel_change_brings_back_a_drive_banner_whose_error_remains(self):
        ns = self._ns()
        ns["_drive_streak_signature"] = frozenset({"D:\\"})
        ns["_rearm_banners_on_channel_change"]({"current_channel": "05"})
        ns["_drive_streak_consumed"] = True
        ns["_rearm_banners_on_channel_change"]({"current_channel": "06"})
        self.assertFalse(ns["_drive_streak_consumed"])

    def test_a_cleared_error_is_not_brought_back(self):
        ns = self._ns()
        ns["_drive_streak_consumed"] = True
        ns["_rearm_banners_on_channel_change"]({"current_channel": "06"})
        self.assertTrue(ns["_drive_streak_consumed"])

    def test_the_server_banner_returns_only_on_a_server_channel(self):
        ns = self._ns(locked_channels=("05",))
        ns["_server_streak_signature"] = ("Den", "offline", ())
        ns["_rearm_banners_on_channel_change"]({"current_channel": "02"})
        ns["_server_streak_consumed"] = True
        ns["_rearm_banners_on_channel_change"]({"current_channel": "03"})
        self.assertTrue(ns["_server_streak_consumed"])
        ns["_rearm_banners_on_channel_change"]({"current_channel": "05"})
        self.assertFalse(ns["_server_streak_consumed"])

    def test_no_banner_comes_back_on_a_timer(self):
        src = get_function_source("_advance_status_banner_streaks")
        self.assertNotIn("REARM_MS", src)
        self.assertNotIn("_consumed_at is not None", src)
        self.assertIn("_rearm_banners_on_channel_change(_app)", src)


