# ============================================================================
# SECTION: A streaming computer follows the server's clock zone
# ============================================================================


class TestAStreamingComputerFollowsTheServersTimeZone(unittest.TestCase):
    """Days and blocks are cut by the wall clock; a User PC in another zone must read the server's zone so every channel airs what the server airs"""

    def setUp(self):
        import broadcast_clock
        self.bc = broadcast_clock
        self.bc.set_server_utc_offset(None)

    def tearDown(self):
        self.bc.set_server_utc_offset(None)

    def test_the_clock_reads_in_the_servers_zone_and_goes_back(self):
        own = self.bc.now()
        self.bc.set_server_utc_offset(own.utcoffset().total_seconds() - 3600)
        shifted = self.bc.now()
        self.assertEqual(shifted.utcoffset().total_seconds(), own.utcoffset().total_seconds() - 3600)
        self.assertAlmostEqual((own - shifted).total_seconds(), 0, delta=2)
        gap = (own.hour * 3600 + own.minute * 60 + own.second) - (shifted.hour * 3600 + shifted.minute * 60 + shifted.second)
        self.assertIn(gap % 86400, (3599, 3600, 3601))
        self.bc.set_server_utc_offset(None)
        self.assertEqual(self.bc.now().utcoffset(), own.utcoffset())

    def test_a_bad_offset_is_ignored(self):
        self.bc.set_server_utc_offset(3600)
        self.bc.set_server_utc_offset("soon")
        self.bc.set_server_utc_offset(99 * 3600)
        self.assertEqual(self.bc.server_utc_offset(), 3600)

    def test_a_schedule_message_and_a_ping_carry_the_servers_offset(self):
        import server_sync
        msg = server_sync.build_schedule_message("server1", {}, 1)
        self.assertIsInstance(msg["clock"]["utc_offset_s"], int)
        self.assertIn('"utc_offset_s": local_utc_offset_s()', inspect.getsource(server_sync.ScheduleBroadcaster._run))

    def test_the_client_hands_the_offset_from_a_schedule_and_a_ping_to_the_app(self):
        import server_sync
        got = []
        client = server_sync.ScheduleClient("h", slot_id="server1", on_clock=got.append)
        client._take_clock({"type": "schedule", "slot_id": "server1", "clock": {"utc_offset_s": -25200}})
        client._take_clock({"type": "schedule", "slot_id": "server2", "clock": {"utc_offset_s": 3600}})
        client._take_clock({"type": "ping", "utc_offset_s": -25200})
        client._take_clock({"type": "ping"})
        self.assertEqual(got, [-25200, -25200])

    def test_the_app_follows_on_connect_and_lets_go_on_disconnect(self):
        self.assertIn("on_clock=_on_remote_clock", MAIN_SRC)
        self.assertIn("broadcast_clock.set_server_utc_offset(offset_s)", MAIN_SRC)
        self.assertIn("broadcast_clock.set_server_utc_offset(None)", get_function_source("_disconnect_remote_server"))
        self.assertIn('server_clock_offsets', MAIN_SRC)


