class TestTheTvGuideButtonOverridesTheBootChoice(unittest.TestCase):
    """Theme tab: TV GUIDE: REGULAR / BIG TEXT sits under Letterboxing and overrides the boot-time 4:3 or 16:9 choice"""

    class _Db:
        _detected_aspect_ratio = "16:9"
        def __init__(self, config=None):
            self.config = config or {}

    def test_without_a_pick_the_boot_choice_stands(self):
        self.assertFalse(ui._guide_aspect_is_4_3(self._Db()))
        db = self._Db(); db._detected_aspect_ratio = "4:3"
        self.assertTrue(ui._guide_aspect_is_4_3(db))
        self.assertEqual(ui.guide_text_effective(db), "big")

    def test_a_pick_wins_over_what_the_screen_was_detected_as(self):
        self.assertTrue(ui._guide_aspect_is_4_3(self._Db({"tv_guide_text": "big"})))
        db = self._Db({"tv_guide_text": "regular"}); db._detected_aspect_ratio = "4:3"
