class TestAServerMadeAgainUnderAnOldNameIsANewServer(unittest.TestCase):
    """A reset-and-recreate gives the server a new ID; the User PCs drop what they remembered of the old one"""

    def test_the_id_is_kept_beside_the_channel_file_and_goes_with_the_folder(self):
        import server_sync
        with tempfile.TemporaryDirectory() as tmp:
            slot = os.path.join(tmp, "Steven", "retro.config.json")
            os.makedirs(os.path.dirname(slot))
            first = server_sync.server_id_for_slot(slot)
            self.assertEqual(first, server_sync.server_id_for_slot(slot))
            shutil.rmtree(os.path.dirname(slot))
            os.makedirs(os.path.dirname(slot))
            self.assertNotEqual(first, server_sync.server_id_for_slot(slot))

    def test_every_schedule_message_carries_the_id(self):
        import server_sync
        self.assertEqual(server_sync.build_schedule_message("server1", {}, 1, server_id="abc")["server_id"], "abc")
        self.assertIn("server_id_for_slot(path)", inspect.getsource(server_sync.ScheduleBroadcaster._run))

    def test_a_new_id_for_a_known_name_drops_the_old_servers_memory_but_a_first_id_does_not(self):
        src = MAIN_SRC
