class TestShareSignInKeepsTryingUntilTheNetworkIsUp(unittest.TestCase):
    """Owner 2026-11-13: in shell mode the PC never got into the server's shares; the first sign-in came before the network and nothing tried again."""

    def _res(self, code):
        return types.SimpleNamespace(returncode=code, stdout="System error 53", stderr="")

    def test_a_later_round_that_works_runs_the_follow_up_once(self):
        import server_remote_files as rf
        answers = [2, 2, 2, 2, 0]
        calls = []

        def run(cmd):
            calls.append(cmd)
            return self._res(answers.pop(0) if answers else 0)
        late = []
        rf.begin_sign_in("NETLATE")
        ok = rf.sign_in_until_it_works("NETLATE", on_late_success=lambda: late.append(1), run=run, every=1, total=30, sleep=lambda s: None)
        self.assertTrue(ok)
        self.assertEqual(late, [1])
        self.assertTrue(rf.wait_for_sign_in("NETLATE", 0.1))

    def test_a_1219_cancels_the_hidden_connections_by_name(self):
        import server_remote_files as rf
        calls = []

        def run(cmd):
            calls.append(list(cmd))
            return types.SimpleNamespace(returncode=2, stdout="System error 1219 has occurred.", stderr="")
        rf.sign_in_to_server("HIDDENHOST", run=run, attempts=1, pause=0)
        deletes = [c[2] for c in calls if c[:2] == ["net", "use"] and c[-2:] == ["/delete", "/y"]]
        self.assertIn("\\\\HIDDENHOST\\IPC$", deletes)
        self.assertIn("\\\\HIDDENHOST", deletes)

    def test_a_sign_in_that_works_first_time_runs_no_follow_up(self):
        import server_remote_files as rf
        late = []
        self.assertTrue(rf.sign_in_until_it_works("NETOK", on_late_success=lambda: late.append(1), run=lambda c: self._res(0), every=1, total=5, sleep=lambda s: None))
        self.assertEqual(late, [])

    def test_it_gives_up_after_its_time(self):
        import server_remote_files as rf
        n = []
        self.assertFalse(rf.sign_in_until_it_works("NETDEAD", run=lambda c: (n.append(1), self._res(2))[1], every=5, total=20, sleep=lambda s: None))
        self.assertGreater(len(n), 4)

    def test_the_app_applies_the_schedule_again_and_retunes_after_a_late_sign_in(self):
        body = MAIN_SRC[MAIN_SRC.index("def _after_a_late_sign_in():"):][:1500]
        for needle in ("_station_confirmed_dead_drive.clear()", "media.forget_share_state(_server_host)", "_apply_remote_schedule_message(_last_schedule[\"message\"])", "_restart_playback_after_source_change("):
            self.assertIn(needle, body)
        self.assertIn("server_remote_files.sign_in_until_it_works", MAIN_SRC)


