class TestTheScreenThreadNeverWaitsOnADeadShare(unittest.TestCase):
    """Owner 2026-11-13: with the server's shares unreachable the screen thread sat inside a file check, freezing Static, channel changes and the TV guide."""

    def test_a_slow_share_check_gives_up_quickly_and_is_not_asked_again_at_once(self):
        import media_library as ml
        real_stat = os.stat
        calls = []

        def slow(path, *a, **k):
            if str(path).startswith("\\\\"):
                calls.append(path)
                time.sleep(2)
            return real_stat(path, *a, **k)
        old_ident, old_wait = ml._UI_THREAD_IDENT, ml._SHARE_CHECK_WAIT_S
        ml.set_ui_thread(threading.get_ident())
        ml._SHARE_CHECK_WAIT_S = 0.1
        ml._share_down_until.clear()
        try:
            with mock.patch.object(ml.os, "stat", slow):
                started = time.monotonic()
                with self.assertRaises(OSError):
                    ml.stat_for_screen_thread("\\\\DEADHOST\\Share\\a.mkv")
                with self.assertRaises(OSError):
                    ml.stat_for_screen_thread("\\\\DEADHOST\\Share\\b.mkv")
                self.assertLess(time.monotonic() - started, 1.0)
                self.assertEqual(len(calls), 1)
        finally:
            ml.set_ui_thread(old_ident)
            ml._SHARE_CHECK_WAIT_S = old_wait
            ml._share_down_until.clear()

    def test_the_path_key_lookups_use_it(self):
        src = open(_script("media_library.py"), encoding="utf-8").read() if False else None
        import media_library as ml
        text = inspect.getsource(ml.PathKeyResolver)
        self.assertEqual(text.count("stat_for_screen_thread(file_path)"), 2)


