class TestServerChannelsBootFromASavedCopy(unittest.TestCase):
    """Owner 2026-11-13: server mode must start like a regular station: from a saved copy, contacting the server as early as possible."""

    def test_the_saved_copy_round_trips_and_is_rate_limited(self):
        import server_boot_cache as sbc
        with tempfile.TemporaryDirectory() as tmp:
            path = sbc.cache_path_for(tmp, "Den")
            picked = {"name": "Den", "host": "H1", "port": 47532, "slot_id": "server1"}
            sched = {"channels": {"05": {"schedules": {}}}, "revision": 3}
            self.assertTrue(sbc.save(path, picked, sched, [{"p": "D:\\a.mkv", "s": "Fam", "r": "a.mkv", "key": "k", "f": {"duration": 5}}], force=True))
            data = sbc.load(path, "den")
            self.assertTrue(sbc.usable(data))
            self.assertEqual(data["host"], "H1")
            self.assertEqual(data["files"], [{"p": "D:\\a.mkv", "s": "Fam", "r": "a.mkv"}])
            self.assertFalse(sbc.save(path, picked, None, [{"p": "D:\\a.mkv", "s": "Fam", "r": "a.mkv"}]), "a second file-only save at once is skipped")
            self.assertIsNone(sbc.load(path, "other"))

