class TestLoadWaitsAndFirstScheduleFixes(unittest.TestCase):
    """Owner 2026-11-13 (CRT logs): the saved copy never held a schedule, the black wait restarted on a same-channel re-tune, and the first schedule broke a channel already opening."""

    def test_a_save_with_the_schedule_is_not_skipped_by_the_rate_limit(self):
        import server_boot_cache as sbc
        with tempfile.TemporaryDirectory() as tmp:
            path = sbc.cache_path_for(tmp, "Den")
            picked = {"name": "Den", "host": "H1", "port": 47532, "slot_id": "server1"}
            self.assertTrue(sbc.save(path, picked, None, [{"p": "D:\\a.mkv", "s": "Fam", "r": "a.mkv"}]))
            sched = {"channels": {"05": {"schedules": {}}}, "revision": 1}
            self.assertTrue(sbc.save(path, picked, sched, None), "the schedule arrives right after the file facts and must be saved")
            self.assertTrue(sbc.usable(sbc.load(path, "Den")))
            self.assertEqual(len(sbc.load(path, "Den")["files"]), 1)
            self.assertFalse(sbc.save(path, picked, None, [{"p": "D:\\b.mkv", "s": "Fam", "r": "b.mkv"}]), "file-only saves stay limited")

    def test_the_load_wait_does_not_restart_on_a_same_channel_retune(self):
        src = get_function_source("change_channel")
        self.assertIn('str(new_ch).zfill(2) == str(old_ch).zfill(2)', src)
        self.assertIn('and not app_state.get("_had_first_frame_this_tune", False)', src)

    def test_the_first_schedule_does_not_break_a_channel_already_opening(self):
        src = get_function_source("_server_first_tune_tick")
        self.assertIn("no second tune", src)
        self.assertIn("_channel_to_open_on_server(pending)", src)

    def test_the_source_change_stop_does_not_block_the_screen_thread(self):
        src = get_function_source("_restart_playback_after_source_change")
        self.assertIn("vlc_engine.stop(block=False)", src)
        self.assertNotIn("vlc_engine.player.stop()", src)

    def test_the_saved_pick_keeps_the_channel_it_wanted(self):
        self.assertIn('app_state["_server_wanted_channel"] = (_want, _target)', get_function_source("_restart_playback_after_source_change"))
        self.assertIn('_server_wanted_channel', get_function_source("_channel_to_open_on_server"))

    def test_the_loading_waits_are_ten_seconds(self):
        self.assertEqual(gov.STALL_FORCES_STATIC_FIRST_LOAD_MS, 10000)
        self.assertEqual(gov.SERVER_PICK_BLANK_MAX_SECONDS, 10.0)
        self.assertEqual(gov.SERVER_FIRST_SCHEDULE_WAIT_SECONDS, 10.0)
        self.assertEqual(gov.FIRST_FILE_SCANNING_BANNER_DELAY_MS, 10000)

    def test_a_black_layer_covers_the_guide_preview_after_leaving_the_guide(self):
        hold = get_function_source("_channel_cover_hold")
        self.assertIn('app_state.get("_guide_left_on_screen", False)', hold)
        self.assertIn("_failure_static_is_due(_chk)", hold)


