class TestHalfUpdatedInstallStillStarts(unittest.TestCase):
    """Owner 2026-11-14: a locked file made the CRT PC's rollback stop half way (new program, old server_discovery.py) and the app crash-looped at boot."""

    def test_a_locked_file_does_not_stop_the_rest_of_the_rollback(self):
        import update_helper as h
        with tempfile.TemporaryDirectory() as tmp:
            install = os.path.join(tmp, "install")
            backup = os.path.join(tmp, "backup")
            for root, text in ((install, "new"), (backup, "old")):
                for name in ("a.bin", "b.bin"):
                    os.makedirs(os.path.dirname(os.path.join(root, "x", name)), exist_ok=True)
                    with open(os.path.join(root, "x", name), "w", encoding="utf-8") as handle:
                        handle.write(text)
            real = h._copy_with_retry

            def locked_first(source, target, attempts=40, delay=0.25):
                if target.endswith("a.bin"):
                    raise PermissionError("locked")
                return real(source, target, attempts=2, delay=0.01)
            with mock.patch.object(h, "_copy_with_retry", side_effect=locked_first):
                failed = h._restore(install, backup, [os.path.join("x", "a.bin"), os.path.join("x", "b.bin")], [])
            self.assertEqual(failed, [os.path.join("x", "a.bin")])
            with open(os.path.join(install, "x", "b.bin"), encoding="utf-8") as handle:
                self.assertEqual(handle.read(), "old")

    def test_an_unchanged_file_is_left_alone_by_the_rollback(self):
        import update_helper as h
        with tempfile.TemporaryDirectory() as tmp:
            one, two = os.path.join(tmp, "one"), os.path.join(tmp, "two")
            for path in (one, two):
                with open(path, "w", encoding="utf-8") as handle:
                    handle.write("same")
            self.assertTrue(h._same_file(one, two))

    def test_the_server_list_builds_when_server_discovery_is_the_old_file(self):
        body = MAIN_SRC[MAIN_SRC.index("def _local_server_entries():"):][:900]
        self.assertIn('getattr(_sd, "slot_has_media", None)', body)


