class TestGuideBuildDoesNotProbeTheShareFileByFile(unittest.TestCase):
    """CRT log 2026-11-14: guide builds took 18-160 s, held the guide lock for 90 s and made channel changes and the guide freeze, because the build re-probed every file of the server's channels over the share once its 30 s status expired."""

    def test_a_flagged_thread_reads_a_held_status_and_queues_the_recheck(self):
        p = os.path.join(os.sep, "no", "such", "share", "a.mp4")
        calls = []
        orig = media._check_path_status_now
        media._check_path_status_now = lambda path: calls.append(path) or media.PATH_PRESENT
        out = {}
        try:
            media._store_path_status(p, media.PATH_PRESENT, media._now_ms() - media._PATH_FOUND_TTL_MS - 1000)

            def work(flag):
                media.allow_stale_path_status(flag)
                out[flag] = media._path_status(p)
            for flag in (True,):
                t = threading.Thread(target=work, args=(flag,)); t.start(); t.join()
            self.assertEqual(out[True], media.PATH_PRESENT)
            self.assertEqual(calls, [], "no probe of the drive for a status that is only past its time")
            self.assertIn(p, media._path_refresh_queue)
            t = threading.Thread(target=work, args=(False,)); t.start(); t.join()
            self.assertEqual(len(calls), 1, "a thread that did not ask still checks the drive")
        finally:
            media._check_path_status_now = orig
            media._path_refresh_queue.pop(p, None)
            media._path_exists_cache.pop(p, None)

    def test_the_guide_preload_thread_asks_for_it(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        body = src[src.index("def _guide_preload_worker"):][:2500]
        self.assertIn("media.allow_stale_path_status(True)", body)


class TestOneScanPipelineForEveryPlace(unittest.TestCase):
    """Owner 2026-11-14: the program, a server profile and the server service (program closed) scan through one pipeline, in one order, into one library."""

    def _slot(self, tmp, files_by_channel, durations=False):
        import json
        slot = os.path.join(tmp, "slot.json")
        channels = {}
        for ch, names in files_by_channel.items():
            paths = []
            for n in names:
                p = os.path.join(tmp, n)
                open(p, "w").close()
                paths.append(p)
            channels[ch] = {"active": True, "schedules": {"Full Day": [({"path": p, "duration": 600} if durations else {"path": p}) for p in paths]}}
        with open(slot, "w", encoding="utf-8") as fh:
            json.dump({"channels": channels}, fh)
        return {"s": slot}

    def _probe(self, done=()):
        probe = MagicMock()
        probe.get_cached.side_effect = lambda p: ({"header_probed_at": 1, "duration": 60, "picture_box": {"frame": [1, 1]},
                                                  "picture_box_detector_version": 99, "gain": 1.0, "gain_scan_version": 0}
                                                 if os.path.basename(p) in done else {})
        return probe

    def test_the_program_has_no_scan_order_of_its_own(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        for name in ("_gather_probe_priority_queue", "_gather_deep_backlog_queue", "_build_scan_snapshot", "_order_scan_pipeline"):
            body = src[src.index("def %s(" % name):][:700]
            self.assertIn("scan_pipeline.", body, name)
        self.assertNotIn("tiers[0].append", src)
        self.assertNotIn("_ranked_content.append", src)

    def test_the_service_orders_files_like_the_program_not_alphabetically(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            slots = self._slot(tmp, {"05": ["z_0.mkv", "z_1.mkv", "z_2.mkv"], "06": ["a_0.mkv", "a_1.mkv", "a_2.mkv"]})
            probe = self._probe()
            sc = server_scanner.FactsScanner(lambda: slots, lambda: False, lambda: probe)
            order = [os.path.basename(p) for p in [i[0] for i in sc.ordered_items(probe)]]
            self.assertEqual(order[:2], ["z_0.mkv", "a_0.mkv"], "what airs now on each channel first, channels in order")
            self.assertEqual(sorted(order), sorted(["z_0.mkv", "z_1.mkv", "z_2.mkv", "a_0.mkv", "a_1.mkv", "a_2.mkv"]))

    def test_a_file_already_in_the_library_is_not_queued(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            slots = self._slot(tmp, {"05": ["x_0.mkv", "x_1.mkv", "x_2.mkv"]})
            probe = self._probe(done={"x_0.mkv", "x_1.mkv"})
            sc = server_scanner.FactsScanner(lambda: slots, lambda: False, lambda: probe)
            order = [os.path.basename(p) for p in [i[0] for i in sc.ordered_items(probe)]]
            self.assertEqual(order[:1], ["x_2.mkv"])

    def test_a_channel_a_user_watches_is_scanned_before_the_others(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            slots = self._slot(tmp, {"05": ["z_0.mkv", "z_1.mkv"], "06": ["a_0.mkv", "a_1.mkv"]})
            probe = self._probe()
            sc = server_scanner.FactsScanner(lambda: slots, lambda: False, lambda: probe, watched_fn=lambda slot_id: {"06"})
            order = [os.path.basename(p) for p in [i[0] for i in sc.ordered_items(probe)]]
            self.assertEqual(order, ["a_0.mkv", "a_1.mkv", "z_0.mkv", "z_1.mkv"])

    def test_scan_waits_while_the_pc_is_busy_but_not_for_the_airing_file(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            slots = self._slot(tmp, {"05": ["z_0.mkv", "z_1.mkv"]})
            probe = self._probe()
            waits = []
            sc = server_scanner.FactsScanner(lambda: slots, lambda: False, lambda: probe, cpu_percent_fn=lambda: 99.0)
            sc._wait_while_busy = lambda: waits.append(1)
            sc._scan_file = lambda probe, path: True
            sc._stop.wait = lambda t: False
            sc.scan_once()
            self.assertEqual(len(waits), 1, "only the second file waits; the airing one never does")

    def test_busy_wait_ends_when_the_pc_calms_down_or_the_cap_is_reached(self):
        import server_scanner
        readings = iter([95.0, 95.0, 10.0])
        sc = server_scanner.FactsScanner(lambda: [], lambda: False, lambda: None, cpu_percent_fn=lambda: next(readings))
        waited = []
        sc._stop.wait = lambda t: waited.append(t) or False
        sc._wait_while_busy()
        self.assertEqual(len(waited), 2)
        sc2 = server_scanner.FactsScanner(lambda: [], lambda: False, lambda: None, cpu_percent_fn=lambda: 99.0)
        waited2 = []
        sc2._stop.wait = lambda t: waited2.append(t) or False
        sc2._wait_while_busy()
        self.assertLessEqual(sum(waited2), server_scanner.SERVER_SCAN_BUSY_MAX_WAIT_S)

    def test_unwatched_files_rest_longer_while_a_user_streams(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            slots = self._slot(tmp, {"05": ["z_0.mkv"], "06": ["a_0.mkv"]})
            probe = self._probe()
            pauses = []
            sc = server_scanner.FactsScanner(lambda: slots, lambda: False, lambda: probe,
                                             watched_fn=lambda slot_id: {"06"}, streaming_fn=lambda: True)
            sc._scan_file = lambda probe, path: True
            sc._stop.wait = lambda t: pauses.append(t) or False
            sc.scan_once()
            self.assertEqual(pauses[1], pauses[0] * server_scanner.SERVER_SCAN_STREAMING_PAUSE_FACTOR)

    def test_service_hands_the_scanner_load_and_streaming_signals(self):
        src = open(os.path.join(SCRIPTS, "server", "server_service.py"), encoding="utf-8").read()
        self.assertIn("cpu_percent_fn=_scan_cpu_percent", src)
        self.assertIn("streaming_fn=", src)

    def test_the_scan_reads_files_in_that_order(self):
        import server_scanner, tempfile
        with tempfile.TemporaryDirectory() as tmp:
            slots = self._slot(tmp, {"05": ["z_0.mkv", "z_1.mkv"], "06": ["a_0.mkv", "a_1.mkv"]})
            probe = self._probe()
