        self.assertIs(mixer.Sound, real_sound)
        self.assertIs(mixer.Channel, real_channel)
        self.assertEqual(mixer.music.play, "play")
        self.assertFalse(ns["_SILENT_MIXER"]["on"])
        self.assertFalse(ns["_remove_silent_mixer"]())

