class TestReturnToWindowsDesktop(unittest.TestCase):
    """Owner 2026-11-14: leaving the program while it is the Windows shell must bring Windows' own desktop up smoothly: explorer.exe only becomes the desktop when the Shell value names it, so the value is swapped for the start and put back."""

    @classmethod
    def setUpClass(cls):
        cls.src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()

    def _ns(self, taskbar_after, registry_text, popen_ok=True):
        start = self.src.index("def _windows_taskbar_is_up():")
        end = self.src.index("def _read_registry_text(")
        pieces = [self.src[self.src.index("def _windows_taskbar_is_up():"):self.src.index("def _launch_explorer_fallback(hide_window=False):")],
                  self.src[self.src.index("def _launch_explorer_fallback(hide_window=False):"):self.src.index("def _read_registry_text(")]]
        events = []
        state = {"checks": 0}

        def taskbar():
            state["checks"] += 1
            return state["checks"] > taskbar_after

        class Popen:
            def __init__(self, cmd):
                if not popen_ok:
                    raise OSError("no explorer")
                events.append(("popen", cmd[0]))
        ns = {"os": types.SimpleNamespace(name="nt", environ={"SystemRoot": "C:\\Windows"}, path=os.path),
              "time": time, "subprocess": types.SimpleNamespace(Popen=Popen),
              "pygame": types.SimpleNamespace(error=RuntimeError, display=types.SimpleNamespace(quit=lambda: events.append(("display_quit",)))),
              "log": types.SimpleNamespace(info=lambda *a, **k: events.append(("log",) + a), warning=lambda *a, **k: events.append(("warn",) + a)),
              "_log_swallowed": lambda *a, **k: None,
              "_STARTUP_REG_PATH": "Winlogon", "_STARTUP_REG_NAME": "Shell", "_DEFAULT_SHELL": "explorer.exe",
              "_EXPLORER_START_WAIT_SECONDS": 0.3, "_EXPLORER_START_POLL_SECONDS": 0.01,
              "_read_registry_text": lambda path, name: registry_text,
              "_windows_system_exe": lambda name, sub="": "C:\\Windows\\" + name}
        for piece in pieces:
            exec(piece, ns)
        ns["_windows_taskbar_is_up"] = taskbar
        ns["_write_shell_registry"] = lambda value: events.append(("registry", value)) or True
        return ns, events

    def test_the_shell_value_is_swapped_for_the_start_and_put_back(self):
        ours = '"C:\\Retro TV\\Retro TV Emulator.exe" --as-shell'
        ns, events = self._ns(taskbar_after=4, registry_text=ours)
        ns["_launch_explorer_fallback"](hide_window=True)
        kinds = [e[0] for e in events if e[0] != "log"]
        self.assertEqual(kinds, ["registry", "popen", "display_quit", "registry"])
        self.assertEqual([e[1] for e in events if e[0] == "registry"], ["explorer.exe", ours])
        self.assertEqual([e[1] for e in events if e[0] == "popen"], ["C:\\Windows\\explorer.exe"])

    def test_the_setting_is_put_back_even_when_the_taskbar_never_comes(self):
        ours = '"x.exe" --as-shell'
        ns, events = self._ns(taskbar_after=10 ** 9, registry_text=ours)
        t0 = time.monotonic()
        ns["_launch_explorer_fallback"]()
        self.assertLess(time.monotonic() - t0, 3.0, "the wait is limited")
        self.assertEqual([e[1] for e in events if e[0] == "registry"], ["explorer.exe", ours])

    def test_nothing_is_written_when_the_desktop_is_up_or_the_shell_is_not_ours(self):
        ns, events = self._ns(taskbar_after=0, registry_text='"x.exe" --as-shell')
        ns["_launch_explorer_fallback"]()
        self.assertEqual([e for e in events if e[0] in ("registry", "popen")], [])
        ns, events = self._ns(taskbar_after=3, registry_text="explorer.exe")
        ns["_launch_explorer_fallback"]()
        self.assertEqual([e[0] for e in events if e[0] in ("registry", "popen")], ["popen"])

    def test_both_ways_out_hide_the_window_while_the_desktop_loads(self):
        self.assertEqual(self.src.count("_launch_explorer_fallback(hide_window=True)"), 2)
        watchdog = self.src[self.src.index("def _attempt_self_relaunch"):][:6000]
        self.assertIn("_launch_explorer_fallback()", watchdog)


class TestTuneTimeline(unittest.TestCase):
    """Owner 2026-11-14: one log line per channel change names each step and its milliseconds, so the 3 to 8 second waits can be traced to a step."""

    def _ns(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("def _tune_stage(name):")
        end = src.index("def _note_fresh_live_video_frame(ch):")
        lines = []
        ns = {"app_state": {}, "time": time, "threading": threading, "_unresponsive_drive_roots": lambda: [], "_log_swallowed": lambda *a, **k: None,
              "media": types.SimpleNamespace(path_checks_waiting=lambda: 0, drive_checks_in_flight=lambda: 0),
              "log": types.SimpleNamespace(info=lambda *a, **k: lines.append(a[0] % a[1:]))}
        exec(src[start:end], ns)
        return ns, lines, src

    def test_steps_print_once_in_order_with_milliseconds(self):
        ns, lines, _ = self._ns()
        ns["_tune_stage"]("ignored before a change begins")
        ns["_tune_timeline_begin"]()
        ns["_tune_stage"]("play requested")
        time.sleep(0.02)
        ns["_tune_stage"]("opened")
        ns["_tune_stage"]("opened")
        ns["_tune_stage"]("first picture")
        ns["_tune_timeline_report"]("6")
        ns["_tune_timeline_report"]("6")
        self.assertEqual(len(lines), 1)
        self.assertIn("[TUNE TIMELINE] ch06:", lines[0])
        self.assertLess(lines[0].index("play requested"), lines[0].index("opened"))
        self.assertLess(lines[0].index("opened"), lines[0].index("first picture"))
        self.assertIn("share checks busy: 0", lines[0])

    def test_the_steps_are_wired_into_the_channel_change_path(self):
        _, _, src = self._ns()
        for needle in ("        _tune_timeline_begin()\n", '_tune_stage("play requested")', '_tune_stage("opened")', '_tune_stage("first picture")', "        _tune_timeline_report(ch)\n"):
            self.assertEqual(src.count(needle), 1, needle)


class TestWakeLock(unittest.TestCase):
    """Owner 2026-11-15: playing video did not count as the computer being in use, so Windows slept in the middle of a show."""

    def _ns(self, channel="06", shutting=False):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("_ES_CONTINUOUS = 0x80000000")
        end = src.index("def _service_audio_follow():")
        lines = []
        ns = {"os": os, "time": time, "app_state": {"current_channel": channel},
              "_app_shutting_down": types.SimpleNamespace(is_set=lambda: shutting),
              "_WAKE_LOCK_REFRESH_SECONDS": 30.0, "_log_swallowed": lambda *a, **k: None,
              "log": types.SimpleNamespace(info=lambda *a, **k: lines.append(a[0]))}
        exec(src[start:end], ns)
        return ns, lines

    def test_it_holds_refreshes_and_lets_go(self):
        ns, lines = self._ns()
        calls = []
        go = lambda now, **kw: ns["_service_wake_lock"](now=now, call=lambda f: calls.append(f) or True, **kw)
        go(100.0)
        go(110.0)
        go(131.0)
        self.assertEqual(calls, [0x80000003, 0x80000003])
        go(140.0, want=False)
        self.assertEqual(calls[-1], 0x80000000)
        go(150.0, want=False)
        self.assertEqual(len(calls), 3)
        self.assertEqual(len(lines), 2)

    def test_nothing_is_held_with_no_channel_or_while_closing(self):
        for channel, shutting in (("", False), ("06", True)):
            ns, _ = self._ns(channel, shutting)
            calls = []
            ns["_service_wake_lock"](now=1.0, call=lambda f: calls.append(f) or True)
            self.assertEqual(calls, [])

    def test_the_screen_loop_and_exit_call_it(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("    _service_audio_follow()\n    _service_wake_lock()\n", src)
        self.assertIn("    _app_shutting_down.set()\n    _service_wake_lock()\n", src)


class TestSleepDoesNotKillTheProgram(unittest.TestCase):
    """Owner 2026-11-15 (kids PC): the PC slept for 6 minutes, every thread paused, and the heartbeat watchdog relaunched the program on waking and left captions locked."""

    def _tick(self, ticks):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("def _make_heartbeat_watchdog_tick():")
        end = src.index("_vlc_decode_watch = ")
        recovered, lines = [], []
        clock = {"t": 0}
        ns = {"_app_shutting_down": types.SimpleNamespace(is_set=lambda: False),
              "pygame": types.SimpleNamespace(time=types.SimpleNamespace(get_ticks=lambda: clock["t"])),
              "app_state": {"_heartbeat_last_ticks": 0}, "HEARTBEAT_WATCHDOG_TIMEOUT_MS": 45000,
              "_WATCHDOG_SUSPEND_GAP_MS": 30000,
              "log": types.SimpleNamespace(warning=lambda *a, **k: lines.append(a[0] % a[1:])),
              "_force_recover_from_dead_main_loop": lambda ms: recovered.append(ms)}
        exec(src[start:end], ns)
        return ns, clock, recovered, lines

    def test_a_pause_of_the_whole_program_is_not_a_stuck_main_loop(self):
        ns, clock, recovered, lines = self._tick(None)
        tick = ns["_make_heartbeat_watchdog_tick"]()
        for t in (5000, 10000, 15000):
            clock["t"] = t
            ns["app_state"]["_heartbeat_last_ticks"] = t
            tick()
        clock["t"] = 15000 + 384000
        tick()
        self.assertEqual(recovered, [])
        self.assertEqual(ns["app_state"]["_heartbeat_last_ticks"], clock["t"])
        self.assertIn("[SLEEP RESUME]", lines[0])

    def test_a_really_stuck_main_loop_is_still_recovered(self):
        ns, clock, recovered, lines = self._tick(None)
        tick = ns["_make_heartbeat_watchdog_tick"]()
        for t in range(5000, 60001, 5000):
            clock["t"] = t
            tick()
        self.assertTrue(recovered, "the watchdog still acts when only the main loop stops")
        self.assertEqual(lines, [])

    def test_a_watchdog_relaunch_forgives_captions_only_with_enough_memory(self):
        import tempfile
        from assets import performance_governor as pg
        with tempfile.TemporaryDirectory() as folder:
            pg.set_caption_load_marker(folder)
            marker = os.path.join(folder, pg.CAPTION_LOAD_MARKER_NAME)
            with open(marker, "w") as f:
                f.write("resident 11.83")
            with mock.patch.object(pg, "caption_memory_check", return_value=(False, 11.8, 1.0, 1.5)):
                self.assertFalse(pg.caption_forgive_if_memory_ok())
            self.assertTrue(os.path.exists(marker))
            with mock.patch.object(pg, "caption_memory_check", return_value=(True, 11.8, 7.7, 1.5)):
                self.assertTrue(pg.caption_forgive_if_memory_ok())
            self.assertFalse(os.path.exists(marker))
            pg.set_caption_load_marker(None)
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("performance_governor.caption_forgive_if_memory_ok()\n    _attempt_self_relaunch()", src)


