class TestMissingFileDiagnosis(unittest.TestCase):
    """Owner 2026-11-15: a station said the server was offline while its files were fine; the log must say how far down a missing file's path can be reached."""

    def _ns(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("_missing_diag_last = cache_manager.memo(")
        end = src.index("def _tune_stage(name):")
        started = []

        class FakeThread:
            def __init__(self, target=None, args=(), daemon=None, name=None):
                self.target, self.args = target, args

            def start(self):
                started.append(self.args)
        ns = {"os": os, "performance_governor": None, "time": time, "threading": types.SimpleNamespace(Thread=threading.Thread, Event=threading.Event),
              "log": types.SimpleNamespace(warning=lambda *a, **k: None)}
        exec(src[start:end], ns)
        return ns, started, FakeThread

    def _run(self, ns, path):
        lines = []
        ns["_missing_diag_run"](path, "13", lambda fmt, *a: lines.append(fmt % a), wait_s=2.0)
        return lines[0]

    def test_a_missing_file_names_the_first_level_that_failed(self):
        import tempfile
        ns, _, _ = self._ns()
        with tempfile.TemporaryDirectory() as root:
            folder = os.path.join(root, "Adult Series", "Show")
            os.makedirs(folder)
            open(os.path.join(folder, "Show.S01E02.720p-GalaxyTV.mkv"), "w").close()
            line = self._run(ns, os.path.join(folder, "show.s01e02.720p.mkv"))
            self.assertIn("[MISSING FILE DIAG] ch13", line)
            self.assertIn("first level that failed: show.s01e02.720p.mkv", line)
            self.assertIn("Show.S01E02.720p-GalaxyTV.mkv", line)
            line = self._run(ns, os.path.join(root, "Adult Series", "Gone Folder", "x.mkv"))
            self.assertIn("first level that failed: Gone Folder", line)
            self.assertIn("similar names beside it: none", line)
            line = self._run(ns, os.path.join(folder, "Show.S01E02.720p-GalaxyTV.mkv"))
            self.assertIn("none (the whole path exists now)", line)

    def test_the_same_file_is_checked_once_a_minute(self):
        ns, started, fake = self._ns()
        ns["threading"] = types.SimpleNamespace(Thread=fake, Event=threading.Event)
        ns["_diagnose_missing_file"]("\\\\srv\\share\\a.mkv", "13")
        ns["_diagnose_missing_file"]("\\\\srv\\share\\a.mkv", "13")
        ns["_diagnose_missing_file"]("", "13")
        self.assertEqual(len(started), 1)
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("_diagnose_missing_file(filepath, str(app_state.get(\"current_channel\", \"\")))", src)

    def test_the_timeline_has_the_new_steps_and_the_caption_line_has_the_clock(self):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        for stage in ("picture box decided", "open starts", "vlc play called", "ready to seek", "activation starts"):
            self.assertIn('_tune_stage("%s")' % stage, src)
        self.assertIn("pass gap=%d ms, VLC clock unchanged for %d ms", src)


class TestCaptionSyncLogging(unittest.TestCase):
    """Owner 2026-11-15: captions show early and late; each chunk now logs how far its first words start from where the speech starts."""

    def test_the_offsets_show_early_and_late_cues(self):
        src = open(_script("media.py"), encoding="utf-8").read()
        start = src.index("_ASR_SYNC_EARLY_SEC = _perf_governor")
        end = src.index("class _SegList(list):")
        ns = {"_perf_governor": None}
        exec(src[start:end], ns)
        cue = lambda s: types.SimpleNamespace(start=s, end=s + 1.0)
        spans = [{"start": 16000 * 2, "end": 16000 * 6}, {"start": 16000 * 10, "end": 16000 * 14}, {"start": 16000 * 20, "end": 16000 * 24}, {"start": 16000 * 30, "end": 16000 * 31}]
        cues = [cue(1.5), cue(4.0), cue(10.1), cue(22.0)]
        stats = ns["_asr_sync_stats"](cues, spans, 16000)
        self.assertEqual(stats[0], 3)
        self.assertEqual(stats[2], -500)
        self.assertEqual(stats[3], 2000)
        self.assertEqual((stats[4], stats[5]), (1, 1))
        self.assertIsNone(ns["_asr_sync_stats"]([], spans, 16000))
        self.assertIsNone(ns["_asr_sync_stats"](cues, [], 16000))

    def test_it_is_logged_per_chunk_and_the_clock_once_per_file(self):
        media_src = open(_script("media.py"), encoding="utf-8").read()
        self.assertIn("out.sync_stats = _asr_sync_stats(out, raw_spans, sampling_rate)", media_src)
        self.assertIn("[CAPTION SYNC] %s pos=%.1fs", media_src)
        main = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertEqual(main.count("[CAPTION SYNC CLOCK]"), 1)


