        import media
        media._scheduler_transient_logged.clear()
        self.assertTrue(media._scheduler_transient_due("ch08", ["a", "b"]))
        self.assertFalse(media._scheduler_transient_due("ch08", ["b", "a"]))
        self.assertFalse(media._scheduler_transient_due("ch08", ["a"]), "another set of paths on the same channel waits for the gap too")
        self.assertTrue(media._scheduler_transient_due("ch09", ["a"]))
        with mock.patch("time.monotonic", return_value=time.monotonic() + media.SCHEDULER_TRANSIENT_WARN_GAP_SECONDS + 1):
            self.assertTrue(media._scheduler_transient_due("ch08", ["a"]))

