class TestTrayStopCutsStreaming(unittest.TestCase):
    """Owner 2026-11-15: Stop Server in the tray only ended the process while Windows file sharing kept serving the other computers; it must really stop streaming."""

    def setUp(self):
        sys.path.insert(0, os.path.join(SCRIPTS, "server"))
        import server_files
        self.sf = server_files

    def test_the_sharing_script_registers_both_tasks_and_keeps_quotes_intact(self):
        script, _names = self.sf.build_share_script([r"C:\v"], {}, r"C:\r.txt")
        self.assertIn("Register-ScheduledTask -TaskName 'RetroTV Streaming Off'", script)
        self.assertIn("Register-ScheduledTask -TaskName 'RetroTV Streaming On'", script)
        self.assertIn("Disable-LocalUser -Name ''RetroTV''", script)
        self.assertIn("Close-SmbSession -Force", script)
        self.assertIn("Enable-LocalUser -Name ''RetroTV''", script)
        self.assertIn("-RunLevel Highest", script)

    def test_set_streaming_runs_the_matching_task_and_reports_failure(self):
        calls = []

        def fake_run(cmd, **kw):
            calls.append(cmd)
            return types.SimpleNamespace(returncode=0 if "On" in cmd[-1] else 1)
        with mock.patch.object(self.sf.sys, "platform", "win32"), mock.patch("subprocess.run", fake_run):
            self.assertTrue(self.sf.set_streaming(True))
            self.assertFalse(self.sf.set_streaming(False))
        self.assertEqual(calls, [["schtasks", "/run", "/tn", "RetroTV Streaming On"], ["schtasks", "/run", "/tn", "RetroTV Streaming Off"]])

    def test_a_computer_shared_earlier_gets_the_script_once_the_tasks_are_missing(self):
        ran = []
        with tempfile.TemporaryDirectory() as tmp:
            os.makedirs(os.path.join(tmp, "logs"), exist_ok=True)
            def runner(path):
                ran.append(path)
                with open(os.path.join(tmp, "logs", "share_result.txt"), "w") as fh:
                    fh.write("ok")
                return ""
            ok, _n = self.sf.grant_sharing(tmp, [r"C:\v\a.avi"], shares={"v": r"C:\v"}, run_elevated=runner, switch_ready=lambda: False)
            self.assertTrue(ok)
            self.assertEqual(len(ran), 1)
            ok, _n = self.sf.grant_sharing(tmp, [r"C:\v\a.avi"], shares={"v": r"C:\v"}, run_elevated=runner, switch_ready=lambda: True)
            self.assertEqual(len(ran), 1)

    def test_the_service_turns_streaming_off_from_the_tray_and_on_at_start(self):
        src = open(os.path.join(SCRIPTS, "server", "server_service.py"), encoding="utf-8").read()
        self.assertIn("server_files.stop_streaming_verified(log)", src)
        self.assertIn("server_files.set_streaming(True, log)", src)
        self.assertLess(src.index("server_files.set_streaming(True, log)"), src.index("def _stop_from_tray():"))


class TestLostServerIsLookedForAgain(unittest.TestCase):
    """Owner 2026-11-15: after a server is stopped from the tray and started again, the streaming PC must reconnect by itself, checking every couple of seconds."""

    def _ns(self, entry, cfg, state):
        src = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("def _arm_server_reconnect(name):")
        end = src.index("def _awaiting_first_server_schedule():")
        used = []
        logs = []
        ns = {"db": types.SimpleNamespace(config=cfg), "app_state": state, "SERVER_RECONNECT_CHECK_SECONDS": 2.0,
              "_find_saved_server_entry": lambda pick, a, b: entry["value"], "_local_server_entries": lambda: [],
              "get_server_picker_entries": lambda d: [], "_use_server_entry": lambda e: used.append(e),
              "log": types.SimpleNamespace(info=lambda *a, **k: logs.append(a), warning=lambda *a, **k: None),
              "_log_warn_throttled": lambda *a, **k: None}
        exec(src[start:end], ns)
        return ns, used

    def test_it_waits_then_goes_back_when_the_server_is_offered(self):
        pick = {"name": "Family"}
        cfg = {"last_server_pick": pick, "server_role": "user", "server_mode_enabled": True}
        state = {}
        entry = {"value": None}
        ns, used = self._ns(entry, cfg, state)
        ns["_arm_server_reconnect"]("Family")
        ns["_server_reconnect_tick"](10000)
        self.assertEqual(used, [])
        self.assertIn("_server_reconnect", state)
        ns["_server_reconnect_tick"](11000)
        entry["value"] = {"name": "Family"}
        ns["_server_reconnect_tick"](12100)
        self.assertEqual(used, [{"name": "Family"}])
