        state = {}
        ns, used = self._ns({"value": {"name": "Family"}}, cfg, state)
        ns["_arm_server_reconnect"]("Family")
        cfg["last_server_pick"] = {"name": "Other"}
        ns["_server_reconnect_tick"](5000)
        self.assertEqual(used, [])
        self.assertNotIn("_server_reconnect", state)

