class TestMovieChannelsStayRandom(unittest.TestCase):
    """Owner 2026-11-15: movies are always random, never alphabetical, whatever the order option says; a movie channel must not start on the first movie in the alphabet."""

    NAMES = ["101 Dalmatians", "Aladdin", "Bambi", "Cars", "Dumbo", "Encanto", "Frozen", "Hercules", "Moana", "Tangled", "Up", "Zootopia"]

    def _first_movies(self, order_mode, mode):
        import media
        raw = [{"path": "D:/m/%s.avi" % n, "duration": 5400.0} for n in self.NAMES]
        firsts = []
        for seed in range(1, 25):
            lineup, _pos, _order = media.build_show_rotation(
                raw, mode, {}, seed, pair_threshold_seconds=0, episode_order_mode=order_mode,
                block_duration_seconds=8 * 3600, channel_id="08", order_seed=str(seed * 7919))
            firsts.append(os.path.basename(lineup[0]["path"]))
        return firsts

    def test_the_first_movie_is_not_always_the_first_in_the_alphabet(self):
        for order_mode in ("sequential", "random"):
            for mode in ("random_slots", "two_slots"):
                firsts = self._first_movies(order_mode, mode)
                self.assertGreater(len(set(firsts)), 4, (order_mode, mode, firsts))
                self.assertLess(firsts.count("101 Dalmatians.avi"), 8, (order_mode, mode))

    def test_the_order_option_changes_nothing_for_movies(self):
        self.assertEqual(self._first_movies("sequential", "random_slots"), self._first_movies("random", "random_slots"))



