            hub = ml.ScheduleHub(lib)
            hub.place_rows("05", "blkA", [{"position": 0, "path": "D:/a.mkv", "planned_start": 1.0, "used_length": 10.0, "length_source": "measured"}], mode="random_slots")
            hub.mark("05", "blkA", 0, "airing")
            self.assertEqual(hub.mark_airing_static("05", "D:/a.mkv"), 1)
            self.assertEqual(hub.restore_static_to_airing("05", "D:/a.mkv"), 1)
            self.assertEqual(hub.restore_static_to_airing("05", "D:/a.mkv"), 0)
