class TestPrimingFollowsTheViewer(unittest.TestCase):
    """Owner 2026-11-16: priming keeps the viewer primed a few channels ahead in the direction they are stepping, wrapping from the last channel to 05 (01 and 02 do not exist, 03 is the game, 04 the guide), and does it the moment they move."""

    @staticmethod
    def _src():
        return open(_script("retro_tv_emulator.py"), encoding="utf-8").read()

    def _ns(self, keys=None):
        src = self._src()
        start = src.index("def _station_ring():")
        end = src.index("def _prime_note_viewer_at(")
        keys = keys if keys is not None else range(5, 41)

        class _Db:
            channels_db = {"%02d" % i: {"active": True} for i in keys}
        _Db.channels_db["03"] = {"active": True}
        _Db.channels_db["04"] = {"active": True}
        ns = {"db": _Db, "PRIME_RUSH_AHEAD": 3, "PRIME_RUSH_BEHIND": 1}
        exec(src[start:end], ns)
        return ns

    def test_the_ring_is_only_the_real_stations_in_number_order(self):
        ns = self._ns()
        ring = ns["_station_ring"]()
        self.assertEqual(ring[0], "05")
        self.assertEqual(ring[-1], "40")
        self.assertNotIn("03", ring)
        self.assertNotIn("04", ring)

    def test_stepping_up_readies_three_ahead_and_the_one_just_left(self):
        ns = self._ns()
        ring = ns["_station_ring"]()
        self.assertEqual(ns["_prime_window_for"](ring, "10", "11"), ["12", "13", "14", "10"])

    def test_stepping_down_flips_the_window(self):
        ns = self._ns()
        ring = ns["_station_ring"]()
        self.assertEqual(ns["_prime_window_for"](ring, "11", "10"), ["09", "08", "07", "11"])

    def test_going_past_the_last_channel_comes_round_to_05_not_01(self):
        ns = self._ns()
        ring = ns["_station_ring"]()
        self.assertEqual(ns["_prime_window_for"](ring, "38", "39"), ["40", "05", "06", "38"])
        self.assertEqual(ns["_prime_window_for"](ring, "06", "05"), ["40", "39", "38", "06"])

    def test_a_jump_readies_both_sides_and_a_missing_channel_is_skipped(self):
        ns = self._ns(keys=[k for k in range(5, 41) if k != 21])
        ring = ns["_station_ring"]()
        window = ns["_prime_window_for"](ring, "05", "20")
        self.assertNotIn("21", window)
        self.assertIn("22", window)
        self.assertIn("19", window)
        self.assertNotIn("20", window)

    def test_the_viewer_moving_is_noted_by_a_tune_and_by_the_guide_highlight_and_the_worker_rushes_first(self):
        src = self._src()
        change = src[src.index("def change_channel("):][:9000]
        self.assertIn("_prime_note_viewer_at(new_ch, old_ch)", change)
        step = src[src.index("def _guide_step_row("):][:1500]
        self.assertIn("_prime_note_viewer_at(_target[0], _prime_old_hl)", step)
        worker = src[src.index("def _server_channel_warm_worker(stop):"):][:1800]
        self.assertLess(worker.index("_prime_rush_pass()"), worker.index("_prime_channels_pass()"))

    def test_a_rush_never_moves_the_clock_of_the_full_pass(self):
        src = self._src()
        body = src[src.index("def _prime_channels_pass("):src.index("def _station_ring(")]
        self.assertLess(body.index("if only is not None or airing_only:"), body.index("_prime_next_due[0] = max(2.0, _due)"))

    def test_the_guide_preview_opens_through_the_same_load_path_that_reads_the_primed_facts(self):
        """The guide preview box and a real tune both go through play_file_segmented, which takes the primed size and picture box."""
        src = self._src()
        preview = src[src.index("def _start_guide_preview_load("):][:3500]
        self.assertIn("vlc_engine.play_file_segmented(", preview)
        self.assertIn("_primed_picture_box.get(norm_p)", src)

    def test_a_typed_digit_readies_every_channel_the_number_can_still_become(self):
        """Owner 2026-11-16: 0 readies 05 to 09, 1 the teens, 2 the twenties; 5 to 9 also the single-digit channel typed alone; two digits give just that channel."""
        src = self._src()
        ns = self._ns()
        exec(src[src.index("def _prime_digit_candidates("):src.index("def _prime_note_typed_digits(")], ns)
        ring = ns["_station_ring"]()
        cand = ns["_prime_digit_candidates"]
        self.assertEqual(cand(ring, "0"), ["05", "06", "07", "08", "09"])
        self.assertEqual(cand(ring, "1"), ["%02d" % i for i in range(10, 20)])
        self.assertEqual(cand(ring, "2"), ["%02d" % i for i in range(20, 30)])
        self.assertEqual(cand(ring, "5")[0], "05")
        self.assertEqual(cand(ring, "37"), ["37"])
        self.assertEqual(cand(ring, "01"), [])
        self.assertEqual(cand(ring, ""), [])

    def test_a_typed_digit_goes_to_the_front_of_the_queue_and_is_hooked_into_typing(self):
        src = self._src()
        typed = src[src.index("def _surf_digit_typed("):][:1500]
        self.assertIn("_prime_note_typed_digits(app_state[\"digit_buffer\"])", typed)
        body = src[src.index("def _prime_enqueue("):src.index("def _prime_digit_candidates(")]
        self.assertIn("(list(keys) + [k for k in _prime_rush_pending if k not in keys])[:PRIME_RUSH_QUEUE_MAX]", body)


def _synthetic_mp4(sample_size=1048576, samples=10, sync=(1, 6)):
    """An MP4 with its moov box at the end: one video track of `samples` one-second samples of sample_size bytes, two chunks, the sync samples (1-based) as given. Returns (bytes, offset of each chunk)."""
    import struct

    def box(kind, payload):
        return struct.pack(">I4s", 8 + len(payload), kind) + payload
    ftyp = box(b"ftyp", b"isom" + struct.pack(">I", 0))
    mdat_payload = os.urandom(sample_size * samples)
    mdat = box(b"mdat", mdat_payload)
    first_chunk = len(ftyp) + 8
    half = samples // 2
    chunks = [first_chunk, first_chunk + sample_size * half]
    stbl = (box(b"stts", struct.pack(">IIII", 0, 1, samples, 1000))
            + box(b"stss", struct.pack(">II", 0, len(sync)) + b"".join(struct.pack(">I", v) for v in sync))
            + box(b"stsc", struct.pack(">II", 0, 1) + struct.pack(">III", 1, half, 1))
            + box(b"stsz", struct.pack(">III", 0, sample_size, samples))
            + box(b"stco", struct.pack(">II", 0, 2) + b"".join(struct.pack(">I", c) for c in chunks)))
    mdhd = box(b"mdhd", struct.pack(">IIIIIHH", 0, 0, 0, 1000, samples * 1000, 0, 0))
    hdlr = box(b"hdlr", struct.pack(">II", 0, 0) + b"vide" + b"\0" * 13)
    moov = box(b"moov", box(b"trak", box(b"mdia", mdhd + hdlr + box(b"minf", box(b"stbl", stbl)))))
    return ftyp + mdat + moov, chunks


def _synthetic_mkv():
    """A Matroska file with the Cues at the end: two clusters at 0 s and 5 s. Returns (bytes, offsets of the two clusters)."""
    def elem(ident, payload):
        return ident + b"\x01" + len(payload).to_bytes(7, "big") + payload

    def uint(ident, value):
        return elem(ident, value.to_bytes(4, "big"))
    ebml = elem(b"\x1a\x45\xdf\xa3", b"")
    seg_head = b"\x18\x53\x80\x67" + b"\x01\xff\xff\xff\xff\xff\xff\xff"
    info = elem(b"\x15\x49\xa9\x66", uint(b"\x2a\xd7\xb1", 1000000))
    seek_len = len(elem(b"\x11\x4d\x9b\x74", elem(b"\x4d\xbb", elem(b"\x53\xab", b"\x1c\x53\xbb\x6b") + uint(b"\x53\xac", 0))))
    cluster0 = elem(b"\x1f\x43\xb6\x75", os.urandom(5000))
    cluster1 = elem(b"\x1f\x43\xb6\x75", os.urandom(5000))
    pos0 = seek_len + len(info)
    pos1 = pos0 + len(cluster0)
    cues_pos = pos1 + len(cluster1)
    seek = elem(b"\x11\x4d\x9b\x74", elem(b"\x4d\xbb", elem(b"\x53\xab", b"\x1c\x53\xbb\x6b") + uint(b"\x53\xac", cues_pos)))

    def cue(t, pos):
        return elem(b"\xbb", uint(b"\xb3", t) + elem(b"\xb7", uint(b"\xf7", 1) + uint(b"\xf1", pos)))
    cues = elem(b"\x1c\x53\xbb\x6b", cue(0, pos0) + cue(5000, pos1))
    data = ebml + seg_head + seek + info + cluster0 + cluster1 + cues
    seg_start = len(ebml) + len(seg_head)
    return data, [seg_start + pos0, seg_start + pos1]


class TestShareRelayKnowsWhereATimeIs(unittest.TestCase):
    """Owner 2026-11-16: the relay finds the byte position of a time from the index it already keeps (no share read), so a channel's airing position can be kept in memory."""

    def test_an_mp4_with_its_index_at_the_end_gives_the_keyframe_offsets(self):
        import share_relay as r
        data, chunks = _synthetic_mp4()
        view = r._View(data[:400], data[-20000:], len(data))
        table = r._mp4_keyframes(view)
        self.assertEqual(table, [(0.0, chunks[0]), (5.0, chunks[1])])

    def test_an_mkv_gives_its_cluster_offsets_from_cues_that_are_in_the_kept_tail(self):
        import share_relay as r
        data, clusters = _synthetic_mkv()
        view = r._View(data[:400], data[-300:], len(data))
        table = r._mkv_keyframes(view)
        self.assertEqual(table, [(0.0, clusters[0]), (5.0, clusters[1])])

    def test_an_index_that_is_not_in_the_kept_bytes_gives_none_not_a_wrong_answer(self):
        import share_relay as r
        data, _chunks = _synthetic_mp4()
        self.assertIsNone(r._mp4_keyframes(r._View(data[:400], data[-50:], len(data))))
        self.assertIsNone(r._mkv_keyframes(r._View(b"\x00" * 400, b"", 400)))


class TestShareRelayKeepsAChannelsAiringPositionInMemory(unittest.TestCase):
    """Owner 2026-11-16: a snapshot of the airing position is answered from memory, byte for byte the same as the file, and costs the share only what is new."""

    def setUp(self):
        import share_relay
        import tempfile
        self.r = share_relay
        self.tmp = tempfile.mkdtemp()
        self.data, self.chunks = _synthetic_mp4()
        self.src = os.path.join(self.tmp, "show.mp4")
        with open(self.src, "wb") as fh:
            fh.write(self.data)
        self.r.set_cache_dir(os.path.join(self.tmp, "idx"))
        self.r._failed.clear()
        self.r._snapshots.clear()
        self.r._keyframe_tables.clear()
        self._wants = mock.patch.object(self.r, "wants", return_value=True)
        self._wants.start()
        self.addCleanup(self._wants.stop)
        self.addCleanup(_stop_share_relay, self.r)
        self.addCleanup(self.r._snapshots.clear)

    def _get(self, url, rng):
        import urllib.request
        req = urllib.request.Request(url)
        req.add_header("Range", rng)
        with urllib.request.urlopen(req, timeout=20) as f:
            return f.read()

    def test_a_read_inside_the_snapshot_comes_from_memory_and_is_the_same_bytes(self):
        self.r.ensure_index(self.src)
        self.assertEqual(self.r.locate(self.src, 5.5), self.chunks[1])
        got = self.r.snapshot(self.src, 5.0, 9.0)
        self.assertGreater(got, 0)
        self.assertEqual(self.r.snapshot_span(self.src), (5.0, 9.0))
        url = self.r.url_for(self.src)
        with _ShareReadCounter(self.r) as share:
            body = self._get(url, "bytes=%d-%d" % (self.chunks[1] + 100, self.chunks[1] + 200000))
        self.assertEqual(body, self.data[self.chunks[1] + 100:self.chunks[1] + 200001])
        self.assertEqual(share.bytes, 0, "no byte was read from the share")

    def test_a_read_that_runs_out_of_time_keeps_what_it_got_and_the_next_pass_finishes_it(self):
        self.r.ensure_index(self.src)
        real = self.r._read_partial
        def _short(handle, offset, length, deadline=None):
            return real(handle, offset, min(length, 300000), deadline)
        with mock.patch.object(self.r, "_read_partial", _short):
            first = self.r.snapshot(self.src, 5.0, 9.0)
        self.assertGreater(first, 0)
        self.assertIn("PARTIAL", self.r.snapshot_note(self.src))
        span = self.r.snapshot_span(self.src)
        self.assertLess(span[1], 9.0)
        more = self.r.snapshot(self.src, 5.0, 9.0)
        self.assertGreater(more, 0)
        self.assertEqual(self.r.snapshot_span(self.src), (5.0, 9.0))
        self.assertIn("complete", self.r.snapshot_note(self.src))

    def test_asking_again_for_the_same_span_reads_nothing_and_a_later_span_reads_only_the_new_bytes(self):
        self.r.ensure_index(self.src)
        first = self.r.snapshot(self.src, 0.0, 4.0)
        self.assertGreater(first, 0)
        self.assertEqual(self.r.snapshot(self.src, 0.0, 4.0), 0)
        more = self.r.snapshot(self.src, 0.0, 9.0)
        self.assertGreater(more, 0)
        self.assertLess(more, len(self.data) - first + 1, "the part already held was not read again")

    def test_the_total_memory_is_capped_and_a_changed_file_is_never_served_from_an_old_snapshot(self):
        self.r.ensure_index(self.src)
        self.r.snapshot(self.src, 0.0, 9.0)
        with mock.patch.object(self.r, "SNAPSHOT_TOTAL_BYTES", 1024):
            self.r.snapshot(self.src, 5.0, 9.0)
        self.assertLessEqual(len(self.r._snapshots), 1)
        self.r._snapshots[self.r._key(self.src)]["size"] += 1
        self.assertIsNone(self.r._snapshot_covering(self.src, self.chunks[1], len(self.data), 0))

    def test_dropping_snapshots_frees_every_file_not_kept(self):
        self.r.ensure_index(self.src)
        self.r.snapshot(self.src, 5.0, 9.0)
        self.r.drop_snapshots([self.src])
        self.assertIsNotNone(self.r.snapshot_span(self.src))
        self.r.drop_snapshots(())
        self.assertIsNone(self.r.snapshot_span(self.src))


def _synthetic_mp4_index_first(pad=20000, sample_size=4096, samples=10):
    """An MP4 with its moov box first and made big by a free box inside it; returns (bytes, offset of each chunk)."""
    import struct

    def box(kind, payload):
        return struct.pack(">I4s", 8 + len(payload), kind) + payload
    ftyp = box(b"ftyp", b"isom" + struct.pack(">I", 0))
    half = samples // 2

    def moov_for(chunks):
        stbl = (box(b"stts", struct.pack(">IIII", 0, 1, samples, 1000))
                + box(b"stss", struct.pack(">II", 0, 2) + struct.pack(">II", 1, 6))
                + box(b"stsc", struct.pack(">II", 0, 1) + struct.pack(">III", 1, half, 1))
                + box(b"stsz", struct.pack(">III", 0, sample_size, samples))
                + box(b"stco", struct.pack(">II", 0, 2) + b"".join(struct.pack(">I", c) for c in chunks)))
        mdhd = box(b"mdhd", struct.pack(">IIIIIHH", 0, 0, 0, 1000, samples * 1000, 0, 0))
        hdlr = box(b"hdlr", struct.pack(">II", 0, 0) + b"vide" + b"\0" * 13)
        return box(b"moov", box(b"trak", box(b"mdia", mdhd + hdlr + box(b"minf", box(b"stbl", stbl)))) + box(b"free", b"\0" * pad))
    moov_len = len(moov_for([0, 0]))
    first = len(ftyp) + moov_len + 8
    chunks = [first, first + sample_size * half]
    return ftyp + moov_for(chunks) + box(b"mdat", os.urandom(sample_size * samples)), chunks


class TestALongMoviesIndexIsKeptWhole(unittest.TestCase):
    """Owner log 2026-11-24: National Treasure and the other long MP4 movies on channel 06 never had their airing part read ahead ("no index to place 5219s by"): their index was bigger than the kept start of the file, so a tune read it, and the airing part, over the network."""

    def setUp(self):
        import share_relay
        import tempfile
        self.r = share_relay
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, True)
        self.r.set_cache_dir(os.path.join(self.tmp, "idx"))
        self.r._failed.clear()
        self.r._keyframe_tables.clear()
        self.r._index_reach_checked.clear()
        self._wants = mock.patch.object(self.r, "wants", return_value=True)
        self._wants.start()
        self.addCleanup(self._wants.stop)
        self.addCleanup(_stop_share_relay, self.r)

    def _write(self, name, data):
        path = os.path.join(self.tmp, name)
        with open(path, "wb") as fh:
            fh.write(data)
        return path

    def test_an_index_at_the_start_bigger_than_the_kept_start_is_kept_whole(self):
        data, chunks = _synthetic_mp4_index_first()
        path = self._write("long.mp4", data)
        with mock.patch.object(self.r, "HEAD_CACHE_BYTES", 4096), mock.patch.object(self.r, "TAIL_CACHE_BYTES", 2048):
            meta = self.r.ensure_index(path)
        self.assertGreaterEqual(meta[2], chunks[0] - 8, "the kept start reaches the end of the index")
        self.assertEqual(self.r.keyframe_table(path), [(0.0, chunks[0]), (5.0, chunks[1])])

    def test_an_index_at_the_end_bigger_than_the_kept_end_is_kept_whole(self):
        data, chunks = _synthetic_mp4(sample_size=4096)
        path = self._write("tail.mp4", data)
        moov_at = data.rfind(b"moov") - 4
        with mock.patch.object(self.r, "HEAD_CACHE_BYTES", 64), mock.patch.object(self.r, "TAIL_CACHE_BYTES", 32):
            meta = self.r.ensure_index(path)
        self.assertGreaterEqual(meta[3], len(data) - moov_at)
        self.assertEqual(self.r.keyframe_table(path), [(0.0, chunks[0]), (5.0, chunks[1])])

    def test_a_copy_kept_before_with_its_index_cut_off_is_made_again_and_its_old_table_dropped(self):
        data, chunks = _synthetic_mp4_index_first()
        path = self._write("old.mp4", data)
        with mock.patch.object(self.r, "HEAD_CACHE_BYTES", 4096), mock.patch.object(self.r, "TAIL_CACHE_BYTES", 2048), \
                mock.patch.object(self.r, "_mp4_index_reach", return_value=None):
            self.r.ensure_index(path)
        self.assertIsNone(self.r.keyframe_table(path), "the old copy holds only part of the index")
        with mock.patch.object(self.r, "HEAD_CACHE_BYTES", 4096), mock.patch.object(self.r, "TAIL_CACHE_BYTES", 2048):
            self.r.ensure_index(path)
        self.assertEqual(self.r.keyframe_table(path), [(0.0, chunks[0]), (5.0, chunks[1])])

    def test_only_mp4_files_are_measured_and_a_huge_index_is_left_alone(self):
        data, _chunks = _synthetic_mp4_index_first()
        view = self.r._View(data[:4096], b"", len(data))
        self.assertIsNone(self.r._mp4_index_reach(view, len(data), "x.mkv"))
        with mock.patch.object(self.r, "MP4_INDEX_MAX_BYTES", 1000):
            self.assertIsNone(self.r._mp4_index_reach(view, len(data), "x.mp4"))


class TestPrimerKeepsSnapshotsForTheViewersZone(unittest.TestCase):
    """Owner 2026-11-16: while the viewer is changing channels the channels they may reach next keep their airing position in memory; when they stop, the snapshots are freed."""

    def _ns(self, spans=None, now_seek=100.0, ring=None):
        src = open(_script("retro_tv_emulator.py"), encoding="utf-8").read()
        start = src.index("_prime_snapshot_zone = {}")
        end = src.index("def _prime_rush_pass():")
        zone_fn = src[src.index("def _prime_zone_add("):src.index("def _prime_enqueue(")]
        calls = []
        spans = spans if spans is not None else {}

        class _Relay:
            @staticmethod
            def wants(p):
                return p.startswith("\\\\")

            @staticmethod
            def snapshot_span(p):
                return spans.get(p)

            @staticmethod
            def keyframe_table(p):
                return [(0.0, 1)]

            @staticmethod
            def ensure_index(p, max_seconds=0):
                calls.append(("index", p))

            @staticmethod
            def snapshot(p, a, b, max_seconds=0):
                calls.append(("snapshot", p, a, b))
                return 1000

            @staticmethod
            def snapshot_note(p):
                return "complete: stub"

            @staticmethod
            def drop_snapshots(keep):
                calls.append(("drop", tuple(keep)))

        class _Db:
            channels_db = {}
        ns = {"log": logging.getLogger("test_prime_snapshot"), "_prime_context": threading.local(), "PRIME_SNAPSHOT_LOG_EVERY_S": 30.0, "time": time, "os": os, "db": _Db, "share_relay": _Relay, "_share_relay_on": lambda: True,
              "app_state": {"current_channel": "05"}, "_app_shutting_down": threading.Event(),
              "calculate_slotted_playback_state": lambda ch: {"file": "\\\\srv\\%s.mkv" % ch, "seek": now_seek, "duration": 1800},
              "_wait_to_prime": lambda path=None: True, "_wait_for_cache_turn": lambda path=None: True, "_log_swallowed": lambda *a: None, "SERVER_CHANNEL_WARM_MAX_SECONDS": 6.0,
              "PRIME_SNAPSHOT_SECONDS": 15.0, "PRIME_SNAPSHOT_RETRY_SECONDS": 10.0, "PRIME_SNAPSHOT_ZONE_SECONDS": 60.0,
              "station_clock": types.SimpleNamespace(arm_in=lambda key, seconds, fn: calls.append(("countdown", key, seconds))),
              "PRIME_SNAPSHOT_CHANNELS_MAX": 3, "_prime_zone_lock": threading.Lock(), "_prime_snap_wake": threading.Event(), "_station_ring": lambda: ring or [], "_channel_ready_order": lambda: list(ring or []),
              "_prime_last_viewed": {"ch": ""}, "_prime_last_window": [],
              "_prime_window_for": lambda r, o, n: [r[(r.index(n) + k) % len(r)] for k in (1, 2, 3)] if n in r else []}
        exec(zone_fn + src[start:end], ns)
        return ns, calls

    def test_a_channel_in_the_zone_gets_a_snapshot_from_its_airing_position_but_the_one_on_screen_does_not(self):
        ns, calls = self._ns()
        ns["_prime_zone_add"](["05", "06", "07"])
        ns["_prime_snapshot_pass"]()
        shot = [c for c in calls if c[0] == "snapshot"]
        self.assertEqual([c[1] for c in shot], ["\\\\srv\\06.mkv", "\\\\srv\\07.mkv"])
        self.assertEqual(shot[0][2:], (100.0, 115.0))

    def test_a_snapshot_that_still_covers_the_next_seconds_is_not_read_again(self):
        ns, calls = self._ns(spans={"\\\\srv\\06.mkv": (95.0, 118.0)})
        ns["_prime_zone_add"](["06"])
        ns["_prime_snapshot_pass"]()
        self.assertEqual([c for c in calls if c[0] == "snapshot"], [])
        self.assertEqual([c for c in calls if c[0] == "countdown"], [("countdown", "snapshots", 118.0 - 100.0 - 7.5)],
                         "owner 2026-11-24: the pass wakes when the picture passes the snapshot's middle, not on a timer")

    def test_no_more_than_the_most_channels_are_kept_and_a_left_zone_frees_the_memory(self):
        ns, calls = self._ns()
        ns["_prime_zone_add"](["06", "07", "08", "09", "10"])
        ns["_prime_snapshot_pass"]()
        self.assertEqual(len([c for c in calls if c[0] == "snapshot"]), 3)
        for ch in list(ns["_prime_snapshot_zone"]):
            ns["_prime_snapshot_zone"][ch] = time.monotonic() - 1
        del calls[:]
        ns["_prime_snapshot_pass"]()
        self.assertEqual(ns["_prime_snapshot_zone"], {})
        self.assertIn(("drop", ()), calls)

    def test_the_channels_around_the_one_on_screen_stay_in_the_zone_without_the_viewer_moving(self):
        """Owner 2026-11-16: after sitting on a channel a while the first press up was slow because the zone had expired."""
        ns, calls = self._ns(ring=["05", "06", "07", "08", "09"])
        ns["_prime_snapshot_pass"]()
        self.assertEqual(list(ns["_prime_snapshot_zone"]), ["05", "06", "07", "08", "09"])
        self.assertEqual([c[1] for c in calls if c[0] == "snapshot"], ["\\\\srv\\06.mkv", "\\\\srv\\07.mkv", "\\\\srv\\08.mkv"])

    def test_the_nearest_channel_is_kept_first_when_the_window_moves(self):
        ns, _calls = self._ns()
        ns["_prime_zone_add"](["09", "10"])
        ns["_prime_zone_add"](["07", "08"])
        self.assertEqual(list(ns["_prime_snapshot_zone"]), ["07", "08", "09", "10"])

    def test_the_viewer_moving_puts_the_window_and_typed_digits_in_the_zone_and_the_worker_wakes_for_refreshes(self):
        src = open(_script("retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("_prime_zone_add(_window)", src[src.index("def _prime_note_viewer_at("):][:1500])
        self.assertIn("_prime_zone_add(_keys)", src[src.index("def _prime_note_typed_digits("):][:800])
        """Owner 2026-11-16: the snapshots have their own thread, so a slow priming pass never delays them."""
        self.assertIn("_prime_snap_wake.wait(PRIME_RECHECK_SECONDS)", src[src.index("def _prime_snapshot_worker():"):][:900])
        self.assertIn("_prime_snapshot_pass()", src[src.index("def _prime_snapshot_worker():"):][:900])
        self.assertNotIn("_prime_snapshot_pass()", src[src.index("def _prime_rush_pass():"):][:700])
        self.assertIn('name="PrimeSnapshot"', src)


class TestServerReadsTheAiringPartOfChannelsIntoItsMemory(unittest.TestCase):
    """Owner 2026-11-16: the User asks the server to read the airing part of each channel's file, from the exact position its index gives, so a tune's first read is answered from the server's memory; the server only reads video files inside shared folders."""

    def test_the_user_builds_one_range_per_other_streamed_channel_from_the_kept_index(self):
        src = open(_script("retro_tv_emulator.py"), encoding="utf-8").read()
        body = src[src.index("def _server_warm_ranges("):src.index("def _prime_snapshot_pass(")]

        class _Relay:
            @staticmethod
            def wants(p):
                return True

            @staticmethod
            def locate(p, t):
                return int(t * 1000)

            @staticmethod
            def known_size(p):
                return 10_000_000

        class _Map:
            @staticmethod
            def server_path_for(p):
                return "D:\\\\" + p.split("\\\\")[-1] if p.endswith(".mkv") else None

        class _Db:
            channels_db = {"05": {"server_locked": True}, "06": {"server_locked": True}, "07": {"server_locked": True}, "08": {"server_locked": False}}
        ns = {"db": _Db, "share_relay": _Relay, "_share_relay_on": lambda: True, "app_state": {"current_channel": "05"},
              "_channel_ready_order": lambda: ["05", "06", "07", "08"], "os": os, "_log_swallowed": lambda *a: None,
              "_viewer_near_channels": lambda: ["06", "07", "08"],
              "_get_probe_now_state": lambda ch: {"file": "\\\\\\\\srv\\\\" + ch + (".mkv" if ch == "06" else ".bin"), "seek": 100.0, "duration": 1800},
              "SERVER_WARM_AHEAD_SECONDS": 60.0}
        exec(body, ns)
        got = ns["_server_warm_ranges"](_Map)
        self.assertEqual(len(got), 1, "not the channel on screen, not a file the server did not send, not a channel that is not streamed")
        self.assertEqual(got[0], ["D:\\\\06.mkv", 100000, 165000 - 100000])
        self.assertEqual(ns["_server_warm_ranges"](None), [])
        ns["_viewer_near_channels"] = lambda: ["07"]
        self.assertEqual(ns["_server_warm_ranges"](_Map), [], "owner 2026-11-18 (A3): a streamed channel that is not next to the viewer is not read ahead on the server")

    def test_the_user_asks_every_warm_report_seconds_and_the_asking_is_wired_in(self):
        src = open(_script("retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("warm_provider=lambda: _server_warm_ranges(_file_map)", src)
        sync = open(os.path.join(SCRIPTS, "server", "server_sync.py"), encoding="utf-8").read()
        self.assertIn('"type": "warm"', sync)
        self.assertIn("time.monotonic() - warm_sent >= WARM_REPORT_S", sync)

    def test_the_server_reads_only_allowed_files_only_once_and_only_what_is_new(self):
        import tempfile
        import server_sync
        tmp = tempfile.mkdtemp()
        path = os.path.join(tmp, "a.mkv")
        with open(path, "wb") as fh:
            fh.write(os.urandom(5 * 1048576))
        reads = []
        b = server_sync.ScheduleBroadcaster(lambda: {}, warm_allowed=lambda p: p == path)
        real_open = open

        def spy_open(p, mode="r", *a, **k):
            fh = real_open(p, mode, *a, **k)
            if p == path:
                orig = fh.read
                fh.read = lambda n=-1: (lambda d: (reads.append(len(d)), d)[1])(orig(n))
            return fh
        with mock.patch("builtins.open", spy_open):
            b._warm_one(path, 1048576, 2 * 1048576)
            self.assertEqual(sum(reads), 2 * 1048576)
            del reads[:]
            b._warm_one(path, 1048576, 2 * 1048576)
            self.assertEqual(sum(reads), 0, "already held")
            b._warm_one(path, 2 * 1048576, 2 * 1048576)
            self.assertEqual(sum(reads), 1048576, "only the part past what is held")
            del reads[:]
            b._warm_one(os.path.join(tmp, "other.mkv"), 0, 1000)
            self.assertEqual(reads, [], "a file the check refuses is never opened")

    def test_an_ask_is_sanitised_rate_limited_and_the_newest_range_wins(self):
        import server_sync
        b = server_sync.ScheduleBroadcaster(lambda: {}, warm_allowed=lambda p: True)
        client = object()
        b._take_warm_ask(client, {"ranges": [["D:\\\\a.mkv", 0, 100], ["D:\\\\b.mkv", -5, 10], ["D:\\\\c.mkv", 0, 0], "junk", ["D:\\\\d.mkv", 0, 10 ** 12]]})
        self.assertEqual(sorted(b._warm_pending), ["D:\\\\a.mkv", "D:\\\\d.mkv"])
        self.assertEqual(b._warm_pending["D:\\\\d.mkv"][1], server_sync.WARM_RANGE_MAX_BYTES)
        b._take_warm_ask(client, {"ranges": [["D:\\\\e.mkv", 0, 5]]})
        self.assertNotIn("D:\\\\e.mkv", b._warm_pending, "a second ask inside the gap is ignored")
        self.assertIsNone(server_sync.ScheduleBroadcaster(lambda: {}).warm_allowed)

    def test_the_server_only_warms_video_files_that_exist_inside_a_shared_folder(self):
        import tempfile
        import server_files
        tmp = tempfile.mkdtemp()
        inside = os.path.join(tmp, "show.mkv")
        open(inside, "wb").close()
        text = os.path.join(tmp, "notes.txt")
        open(text, "wb").close()
        outside = os.path.join(tempfile.mkdtemp(), "x.mkv")
        open(outside, "wb").close()
        allowed = server_files.make_warm_allowed(shares_fn=lambda: {"Media": tmp})
        self.assertTrue(allowed(inside))
        self.assertFalse(allowed(text))
        self.assertFalse(allowed(outside))
        self.assertFalse(allowed(os.path.join(tmp, "missing.mkv")))
        self.assertFalse(allowed(os.path.join(tmp, "..", os.path.basename(os.path.dirname(outside)), "x.mkv")))

    def test_the_file_map_gives_back_the_servers_own_path_for_a_share_location(self):
        import server_remote_files
        m = server_remote_files.RemoteFileMap("srv", lambda: None)
        m.update([{"p": "D:\\\\Shows\\\\a.mkv", "s": "Media", "r": "Shows\\\\a.mkv"}])
        unc = server_remote_files.unc_path(server_remote_files.share_host("srv"), "Media", "Shows\\\\a.mkv")
        self.assertEqual(m.server_path_for(unc), "D:\\\\Shows\\\\a.mkv", "the server's own spelling")
        self.assertIsNone(m.server_path_for("\\\\\\\\srv\\\\Media\\\\none.mkv"))


class TestNoWindowFlashesAroundAnUpdate(unittest.TestCase):
    """Owner 2026-11-16: a blue box and a black console flashed while updating; the install bar stays hidden until it is drawn and every console tool the program starts is started without a window."""

    def _read(self, *parts):
        return open(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), *parts), encoding="utf-8").read()

    def test_a_build_with_no_console_gets_somewhere_for_print_and_stderr_to_go(self):
        src = self._read("retro_tv_emulator.py")
        guard = src[src.index('for _std_name in ("stdout", "stderr"):'):][:300]
        self.assertIn("os.devnull", guard)
        self.assertLess(src.index('for _std_name in ("stdout", "stderr"):'), src.index("if \"--caption-model-worker\" in sys.argv:"))

    def test_the_streaming_tasks_run_a_plain_script_file_and_are_made_again_when_old(self):
        import server_files
        self.assertEqual(server_files._task_program(), "powershell.exe")
        arguments = server_files._task_arguments("streaming_off.ps1")
        self.assertIn("-File", arguments)
        self.assertIn("(Join-Path $taskdir 'streaming_off.ps1')", arguments)
        self.assertNotIn("EncodedCommand", arguments)
        self.assertNotIn("conhost", arguments)

        class _Done:
            def __init__(self, out):
                self.returncode, self.stdout = 0, out
        with mock.patch.object(server_files.sys, "platform", "win32"):
            with mock.patch("subprocess.run", return_value=_Done("<Command>conhost.exe</Command><Description>retrotv-upkeep-v1</Description>".encode("utf-16-le"))):
                self.assertFalse(server_files.streaming_switch_ready(), "an old task, which Defender removes, is made again")
            with mock.patch("subprocess.run", return_value=_Done(("<Command>powershell.exe</Command><Description>%s</Description>" % server_files.UPKEEP_VERSION).encode("utf-16-le"))):
                self.assertTrue(server_files.streaming_switch_ready())

    def test_every_console_tool_the_update_and_the_program_start_hides_its_window(self):
        import re
        for name in (("scripts", "updater", "update_helper.py"), ("scripts", "updater", "auto_updater.py"), ("retro_tv_emulator.py",)):
            text = self._read(*name)
            for m in re.finditer(r'subprocess\.(?:run|Popen)\(\s*\[(?:"powershell\.exe"|"taskkill"|"powershell"|_windows_system_exe\("shutdown\.exe")', text):
                self.assertIn("CREATE_NO_WINDOW", text[m.start():m.start() + 700], "%s: %s" % (name[-1], text[m.start():m.start() + 60]))


