class TestSendLogsDoesNotStallThePicture(unittest.TestCase):
    def _ns(self):
        src = open(os.path.join(os.path.dirname(__file__), "..", "retro_tv_emulator.py"), encoding="utf-8").read()
        import send_logs_finisher
        ns = {"_send_logs_in_pieces": send_logs_finisher.in_pieces, "_cut_back_to_whole_line": send_logs_finisher.cut_back_to_whole_line}
        return ns, src

    def test_pieces_end_on_whole_lines_and_join_back_to_the_same_text(self):
        ns, _src = self._ns()
        text = "".join("line %d some text here\n" % i for i in range(5000))
        seen = []
        out = ns["_send_logs_in_pieces"](text, lambda piece: (seen.append(piece), piece)[1], piece_chars=4000)
        self.assertEqual(out, text)
        self.assertGreater(len(seen), 5)
        self.assertTrue(all(p.endswith("\n") for p in seen))

    def test_a_copy_cut_mid_line_is_cut_back_to_the_last_whole_line(self):
        import tempfile
        ns, _src = self._ns()
        with tempfile.TemporaryDirectory() as d:
            p = os.path.join(d, "a.txt")
            open(p, "wb").write(b"one\ntwo\nthr")
            ns["_cut_back_to_whole_line"](p)
            self.assertEqual(open(p, "rb").read(), b"one\ntwo\n")

    def test_the_app_log_lock_is_not_held_through_the_copy(self):
        _ns, src = self._ns()
        body = src[src.index("def _copy_logs_while_paused("):src.index("def _build_send_logs_zip(")]
        self.assertNotIn("lock.acquire", body)


class TestSendLogsFinishesAfterTheAppCloses(unittest.TestCase):
    def _src(self):
        return open(os.path.join(os.path.dirname(__file__), "..", "retro_tv_emulator.py"), encoding="utf-8").read()

    def test_the_finisher_posts_a_finished_zip_and_clears_the_job(self):
        import importlib.util, tempfile
        spec = importlib.util.spec_from_file_location("send_logs_finisher", _script("send_logs_finisher.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        with tempfile.TemporaryDirectory() as d:
            zp = os.path.join(d, "send_logs.zip")
            open(zp, "wb").write(b"PK")
            jp = os.path.join(d, "send_logs_job.json")
            mod.write_job(jp, {"state": "posting", "url": "https://x/y", "zip_path": zp, "message": "m", "timeout": 5})
            sent = []
            mod.post_zip = lambda url, path, msg, timeout: (sent.append((url, path, msg)) or (True, "HTTP 200"))
            self.assertTrue(mod.run(jp))
            self.assertEqual(sent, [("https://x/y", zp, "m")])
            self.assertFalse(os.path.exists(jp))
            self.assertFalse(os.path.exists(zp))

    def test_a_job_that_is_not_finished_is_left_for_the_next_start(self):
        import importlib.util, tempfile
        spec = importlib.util.spec_from_file_location("send_logs_finisher", _script("send_logs_finisher.py"))
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        with tempfile.TemporaryDirectory() as d:
            jp = os.path.join(d, "send_logs_job.json")
            mod.write_job(jp, {"state": "copied", "url": "https://x/y", "zip_path": os.path.join(d, "none.zip")})
            self.assertFalse(mod.run(jp))
            self.assertTrue(os.path.exists(jp))

    def test_the_app_starts_the_finisher_on_exit_and_does_not_wait_for_it(self):
        src = self._src()
        self.assertIn('if "--finish-send-logs" in sys.argv:', src)
        self.assertLess(src.index('if "--finish-send-logs" in sys.argv:'), src.index('if "--caption-model-worker" in sys.argv:'))
        body = src[src.index("def _hard_exit_process("):][:2600]
        self.assertIn('if globals().get("app_state", {}).get("_send_logs_inflight", False):\n        _launch_send_logs_finisher()', body)
        launch = src[src.index("def _launch_send_logs_finisher("):src.index("def _hard_exit_process(")]
        self.assertIn("CREATE_BREAKAWAY_FROM_JOB", launch)
        self.assertNotIn(".wait(", launch)
        self.assertNotIn(".communicate(", launch)

    def test_the_worker_writes_the_job_in_steps_and_the_next_start_resumes_it(self):
        src = self._src()
        body = src[src.index("def _execute_send_logs("):][:5200]
        for needle in ('"state": "copying"', '"state": "copied"', '"state": "posting"', "_send_logs_job_remove(_job_path)"):
            self.assertIn(needle, body)
        self.assertIn("threading.Timer(90.0, _resume_send_logs_job)", src)


class TestTrayCheckForUpdates(unittest.TestCase):
    """The server tray's Check for updates row: a Yes/No box, then the update helper's one bar (downloading, preparing, installing, install complete or update failed), all through the existing updater."""

    def setUp(self):
        sys.path.insert(0, os.path.join(SCRIPTS, "server"))
        sys.path.insert(0, os.path.join(SCRIPTS, "updater"))
        import importlib
        import server_tray
        import server_service
        import auto_updater
        import update_helper
        self.tray, self.service, self.updater = server_tray, server_service, auto_updater
        self.helper = importlib.reload(update_helper)

    def test_the_menu_has_the_row_between_open_and_stop(self):
        src = inspect.getsource(self.tray.ServerTray._loop)
        self.assertIn("Check for updates", src)
        self.assertLess(src.index("MENU_OPEN_APP, 2)"), src.index("MENU_CHECK_UPDATES, 4)"))
        self.assertLess(src.index("MENU_CHECK_UPDATES, 4)"), src.index("MENU_STOP, 3)"))
        self.assertIn("MENU_CHECK_UPDATES: self.on_check_updates", src)

    def test_the_service_runs_the_check_on_its_own_thread_not_the_tray_thread(self):
        src = inspect.getsource(self.service.run_service)
        self.assertIn("on_check_updates=lambda: threading.Thread(", src)
        self.assertIn("check_for_updates_from_tray", src)

    def test_the_tray_reuses_the_updater_and_has_no_download_or_install_copy(self):
        src = inspect.getsource(self.service.check_for_updates_from_tray)
        for needle in ("auto_updater.check_for_update(", "auto_updater.stage_update(", "auto_updater.launch_staged_update("):
            self.assertIn(needle, src)
        for copy in ("urlopen", "zipfile", "shutil.copy", "hashlib"):
            self.assertNotIn(copy, src)
        self.assertNotIn("restart", src.lower().split("question=true")[0].split("install it now")[-1])

    def _run(self, result, answers, stage=None, helper_error=None, app_open=False):
        import tempfile
        messages = []
        calls = []
        base = tempfile.mkdtemp()
        written = []
        service, updater = self.service, self.updater
        saved = (service._ask_yes_no, service._tray_message, service._app_is_open, updater.check_for_update, updater.stage_update, updater.launch_staged_update)
        try:
            def say(text, question=False, base_dir=None):
                messages.append((text, question))
                return answers.pop(0) if question else True

            def launch(base_dir, staged, command, parent_pid=None, progress_path=None, **kw):
                calls.append(("launch", progress_path, parent_pid))
                if helper_error:
                    raise updater.UpdateError(helper_error)
                return 4321

            def do_stage(base_dir, manifest, progress_callback=None, **kw):
                calls.append(("stage",))
                if stage is None:
                    raise updater.UpdateError("network down")
                progress_callback(5, 10)
                progress_callback(10, 10)
                return {"staged_path": stage, "version": manifest["version"]}
            service._tray_message = say
            service._ask_yes_no = lambda au, b, text: say(text, True)
            service._app_is_open = lambda b: app_open
            updater.check_for_update = lambda b, config=None, **kw: result
            updater.stage_update = do_stage
            updater.launch_staged_update = launch
            stop = threading.Event()
            service.check_for_updates_from_tray(base, stop)
            progress = updater._read_json(os.path.join(updater._update_dir(base), "tray_progress.json"), None)
            return messages, calls, stop, progress
        finally:
            service._ask_yes_no, service._tray_message, service._app_is_open, updater.check_for_update, updater.stage_update, updater.launch_staged_update = saved

    MANIFEST = {"version": "9.9.9", "url": "https://example.com/x.zip", "sha256": "0" * 64, "file_name": "x V9.9.9.zip"}

    def test_up_to_date_only_says_so(self):
        messages, calls, stop, progress = self._run({"available": False, "current_version": "2.0.1", "message": "You are up to date (2.0.1)."}, [])
        self.assertEqual(messages, [("You are up to date (2.0.1).", False)])
        self.assertEqual(calls, [])
        self.assertFalse(stop.is_set())

    def test_no_leaves_everything_alone(self):
        messages, calls, stop, progress = self._run({"available": True, "current_version": "2.0.1", "manifest": self.MANIFEST}, [False])
        self.assertEqual(len(messages), 1)
        self.assertTrue(messages[0][1])
        self.assertIn("9.9.9", messages[0][0])
        self.assertNotIn("restart", messages[0][0].lower())
        self.assertEqual(calls, [])
        self.assertFalse(stop.is_set())

    def test_yes_starts_the_helper_first_then_downloads_then_ends_the_service(self):
        messages, calls, stop, progress = self._run({"available": True, "current_version": "2.0.1", "manifest": self.MANIFEST}, [True], stage="/tmp/staged")
        self.assertEqual([c[0] for c in calls], ["launch", "stage"])
        self.assertTrue(calls[0][1].endswith("tray_progress.json"))
        self.assertEqual(progress, {"stage": "staged", "staged_path": "/tmp/staged"})
        self.assertTrue(stop.is_set())

    def test_a_failed_download_tells_the_helper_and_keeps_the_service_running(self):
        messages, calls, stop, progress = self._run({"available": True, "current_version": "2.0.1", "manifest": self.MANIFEST}, [True], stage=None)
        self.assertEqual(progress["stage"], "failed")
        self.assertIn("network down", progress["error"])
        self.assertFalse(stop.is_set())

    def test_a_helper_that_cannot_start_shows_update_failed_and_downloads_nothing(self):
        messages, calls, stop, progress = self._run({"available": True, "current_version": "2.0.1", "manifest": self.MANIFEST}, [True], helper_error="blocked")
        self.assertEqual([c[0] for c in calls], ["launch"])
        self.assertIn("Update failed", messages[-1][0])
        self.assertFalse(stop.is_set())

    def test_an_open_program_is_asked_to_close_first(self):
        messages, calls, stop, progress = self._run({"available": True, "current_version": "2.0.1", "manifest": self.MANIFEST}, [True], app_open=True)
        self.assertEqual(calls, [])
        self.assertIn("Close the Retro TV program", messages[-1][0])

    def test_the_helper_record_carries_the_progress_file_and_no_staged_folder(self):
        import tempfile
        base = tempfile.mkdtemp()
        os.makedirs(os.path.join(base, "logs"), exist_ok=True)
        original = self.updater._helper_command
        self.updater._helper_command = lambda b: [sys.executable, "-c", "import time; time.sleep(4)"]
        try:
            pid = self.updater.launch_staged_update(base, {"version": "9.9.9"}, ["x"], progress_path=os.path.join(base, "p.json"))
        finally:
            self.updater._helper_command = original
        self.assertTrue(pid)
        record = self.updater._read_json(os.path.join(self.updater._update_dir(base), "pending_update.json"))
        self.assertEqual(record["staged_path"], "")
        self.assertTrue(record["tray_progress"].endswith("p.json"))
        try:
            os.kill(pid, 9)
        except OSError:
            pass

    def test_the_one_bar_words_and_order(self):
        seen = []

        class Window:
            def update(self, label, fraction):
                seen.append((label, round(fraction, 3)))

            def fail(self, label):
                seen.append(("FAIL", label))

        bar = self.helper._TrayProgress(Window())
        bar.download("DOWNLOADING UPDATE...", 0.2)
        bar.update("WAITING FOR THE APP TO CLOSE...", 0.05)
        bar.update("PREPARING THE UPDATE...", 0.2)
        bar.update("INSTALLING UPDATE...", 0.5)
        self.helper.PROGRESS_DONE_HOLD_SECONDS = 0
        bar.finish()
        bar.starting()
        bar.fail("INSTALL FAILED - RESTORING THE OLD VERSION")
        early = self.helper._TrayProgress(Window())
        early.fail("x")
        labels = [label for label, _ in seen]
        self.assertEqual(labels, ["DOWNLOADING UPDATE...", "PREPARING INSTALL...", "PREPARING INSTALL...", "INSTALLING...", "INSTALL COMPLETE", "FAIL", "FAIL"])
        self.assertEqual(seen[-2:], [("FAIL", "INSTALL FAILED"), ("FAIL", "UPDATE FAILED")])
        fractions = [f for _, f in seen[:-2]]
        self.assertEqual(fractions, sorted(fractions))
        self.assertEqual(fractions[-1], 1.0)

    def test_the_helper_follows_the_download_and_returns_the_staged_folder(self):
        import tempfile
        path = os.path.join(tempfile.mkdtemp(), "p.json")
        seen = []

        class Window:
            def download(self, label, fraction):
                seen.append((label, fraction))
                states = [{"stage": "downloading", "fraction": 0.5}, {"stage": "preparing"}, {"stage": "staged", "staged_path": "/x/payload"}]
                with open(path, "w", encoding="utf-8") as fh:
                    json.dump(states[min(len(seen) - 1, 2)], fh)
        with open(path, "w", encoding="utf-8") as fh:
            json.dump({"stage": "downloading", "fraction": 0.0}, fh)
        self.helper.TRAY_FOLLOW_POLL_SECONDS = 0
        got = self.helper._follow_tray_download(Window(), path, os.getpid())
        self.assertEqual(got, os.path.abspath("/x/payload"))
        self.assertEqual(seen[0][0], "DOWNLOADING UPDATE...")
        self.assertEqual(seen[1], ("DOWNLOADING UPDATE...", 0.45 * 0.5))
        self.assertEqual(seen[2][0], "PREPARING INSTALL...")
        self.assertLessEqual(seen[2][1], self.helper.TRAY_UNPACK_BAR)

    def test_the_helper_shows_update_failed_when_the_service_reports_it_or_dies(self):
        import tempfile
        path = os.path.join(tempfile.mkdtemp(), "p.json")
        events = []

        class Window:
            def download(self, label, fraction):
                pass

            def fail(self, label):
                events.append(label)

            def close(self):
                events.append("close")
        self.helper.TRAY_FOLLOW_POLL_SECONDS = 0
        with open(path, "w", encoding="utf-8") as fh:
            json.dump({"stage": "failed", "error": "x"}, fh)
        with self.assertRaises(RuntimeError):
            self.helper._follow_tray_download(Window(), path, os.getpid())
        self.assertEqual(events, ["UPDATE FAILED", "close"])
        events.clear()
        with open(path, "w", encoding="utf-8") as fh:
            json.dump({"stage": "downloading", "fraction": 0.1}, fh)
        with self.assertRaises(RuntimeError):
            self.helper._follow_tray_download(Window(), path, 2 ** 22 + 12345)
        self.assertEqual(events, ["UPDATE FAILED", "close"])

