class TestGuideNeverLeavesTheGreyPreviewBoxAlone(unittest.TestCase):
    """Owner 2026-11-16: a grey preview-sized square showed on the old picture between channels 03, 04 and 05."""

    def test_the_async_guide_says_whether_it_drew(self):
        import pygame as _pg
        _pg.init()
        surface = _pg.Surface((320, 180))
        saved = (dict(ui._guide_frame_cache), dict(ui._guide_scaled_cache))
        try:
            class _Held:
                def held_by_another_thread(self):
                    return True
            real_lock = ui._guide_build_lock
            ui._guide_build_lock = _Held()
            ui._guide_frame_cache.update(canvas=None, preview_bounds=None, clock_box=None)
            self.assertIs(ui.render_tv_guide_async(surface, {}, None, {}), False)
            ui._guide_build_lock = real_lock
            canvas = _pg.Surface((320, 180))
            ui._guide_frame_cache.update(key="k", canvas=canvas, preview_bounds=(10, 10, 100, 60), clock_box=None, serial=7)
            ui._guide_scaled_cache.update(key=None, surf=None)
            self.assertIs(ui.render_tv_guide_async(surface, {}, None, {}), True)
        finally:
            ui._guide_build_lock = real_lock if "real_lock" in dir() else ui._guide_build_lock
            ui._guide_frame_cache.clear(); ui._guide_frame_cache.update(saved[0])
            ui._guide_scaled_cache.clear(); ui._guide_scaled_cache.update(saved[1])

