class TestThePulseReadsTheFileVlcIsPlaying(unittest.TestCase):
    """Owner log 2026-11-18 18:15: the counters were taken from the file before (the attempt starts about a second before VLC is handed the new file) and ch06 logged FROZEN VIDEO for 15 minutes while VLC played it."""

    def _run(self, engine, f):
        ns = {"_governor_feed": f, "vlc_engine": engine, "app_state": {"is_playing_video": True}, "log": logging.getLogger("t"),
              "_log_swallowed": lambda *a: None, "_note_playback_pulse": lambda *a: None, "_note_stream_buffer": lambda *a: None,
              "_log_stream_buffer_change": lambda *a: None, "performance_governor": None,
              "vlc": types.SimpleNamespace(MediaStats=lambda: types.SimpleNamespace(lost_pictures=0, lost_abuffers=0, displayed_pictures=0, played_abuffers=0))}
        exec(get_function_source("_governor_read_vlc_loss"), ns)
        return ns["_governor_read_vlc_loss"](0.0, False)

    def test_the_counters_follow_the_file_handed_to_vlc(self):
        class _Media:
            def __init__(self, name):
                self.name = name
            def get_stats(self, st):
                return True
            def release(self):
                pass
        handed = {"now": _Media("old")}
        player = types.SimpleNamespace(get_media=lambda: handed["now"])
        engine = types.SimpleNamespace(player=player, _closed=False, _wedged=False, _current_attempt_id=9, _media_handed=(9, 1.0))
        f = {"vlc_media": None, "vlc_media_key": None, "vlc_stats_logged": True,
             "loss": types.SimpleNamespace(update=lambda *a: (0, 0))}
        self._run(engine, f)
        self.assertEqual(f["vlc_media"].name, "old")
        engine._current_attempt_id = 10
        self._run(engine, f)
        self.assertEqual(f["vlc_media"].name, "old", "a new attempt that has not handed VLC its file yet keeps nothing new")
        handed["now"] = _Media("new")
        engine._media_handed = (10, 2.0)
        self._run(engine, f)
        self.assertEqual(f["vlc_media"].name, "new")
        self.assertIsNone(self._run(types.SimpleNamespace(player=player, _closed=False, _wedged=False), dict(f, vlc_media=None)))

    def test_every_hand_over_marks_the_file(self):
        play = MAIN_SRC
        self.assertEqual(play.count("self.player.set_media(media)\n                                    self._media_handed = (_attempt_id, time.monotonic())"), 2)
        self.assertEqual(play.count("self.player.set_media(media)"), 2)


