class TestDriveProfile(unittest.TestCase):
    """Each drive's measured speed is remembered and sizes the boot priming; keep-awake is where it is measured."""

    def _store(self, clock=None):
        import tempfile, drive_profile
        d = tempfile.mkdtemp()
        return drive_profile.DriveProfiles(os.path.join(d, "p.json"), clock=clock or time.time), os.path.join(d, "p.json")

    LIMITS = dict(default=6, fast_workers=8, slow_workers=2, fast_mb_s=150.0, slow_mb_s=40.0, fast_ms=30.0, slow_ms=400.0)

    def test_a_spin_up_is_never_remembered_as_the_drive_speed(self):
        store, _ = self._store()
        self.assertFalse(store.note_first_byte("F:\\", 5200.0))
        self.assertEqual(store.get("F:\\"), {})
        self.assertTrue(store.note_first_byte("F:\\", 12.0))
        self.assertEqual(store.get("F:\\")["first_byte_ms"], 12.0)

    def test_workers_follow_the_measured_speed(self):
        store, _ = self._store()
        self.assertEqual(store.workers_for("E:\\", **self.LIMITS), 6)
        store.note_throughput("E:\\", 400.0)
        store.note_first_byte("E:\\", 5.0)
        self.assertEqual(store.workers_for("E:\\", **self.LIMITS), 8)
        store.note_throughput("F:\\", 25.0)
        self.assertEqual(store.workers_for("F:\\", **self.LIMITS), 2)
        store.note_throughput("G:\\", 90.0)
        self.assertEqual(store.workers_for("G:\\", **self.LIMITS), 6)

    def test_the_slowest_drive_in_the_work_sets_the_count(self):
        store, _ = self._store()
        store.note_throughput("E:\\", 400.0)
        store.note_throughput("F:\\", 25.0)
        self.assertEqual(store.workers_for_roots(["E:\\", "F:\\"], **self.LIMITS), 2)
        self.assertEqual(store.workers_for_roots([], **self.LIMITS), 6)

    def test_the_table_survives_a_restart_and_goes_stale(self):
        import drive_profile
        now = [1000.0]
        store, path = self._store(clock=lambda: now[0])
        store.note_throughput("E:\\", 200.0)
        self.assertFalse(store.throughput_due("E:\\", 604800.0))
        now[0] += 700000.0
        self.assertTrue(store.throughput_due("E:\\", 604800.0))
        again = drive_profile.DriveProfiles(path)
        self.assertEqual(again.get("E:\\")["mb_s"], 200.0)

    def test_keep_awake_is_where_speed_is_measured_and_priming_reads_it(self):
        wake = get_function_source("_wake_drive_with_read")
        self.assertIn("note_first_byte", wake)
        self.assertIn("_measure_drive_speed(root, path)", wake)
        self.assertIn("_ready_airing_files_on(_root, deadline)", get_function_source("_keep_media_drives_awake_once"))
        self.assertIn("_boot_prime_workers(_work)", get_function_source("_prime_channels_pass_inner"))
        self.assertNotIn("BOOT_PRIME_WORKERS", get_function_source("_prime_channels_pass_inner"))

    def test_the_governor_holds_every_drive_number(self):
        import importlib
        gov = importlib.import_module("performance_governor")
        for name in ("DRIVE_PROFILE_SAMPLE_MB", "DRIVE_PROFILE_MAX_AGE_SECONDS", "DRIVE_READY_HEAD_MB", "DRIVE_READY_TAIL_MB",
                     "DRIVE_READY_RENEW_SECONDS", "DRIVE_READY_KEEP_FILES", "BOOT_PRIME_WORKERS_FAST", "BOOT_PRIME_WORKERS_SLOW", "DRIVE_PROFILE_FAST_MB_S",
                     "DRIVE_PROFILE_SLOW_MB_S", "DRIVE_PROFILE_FAST_FIRST_BYTE_MS", "DRIVE_PROFILE_SLOW_FIRST_BYTE_MS"):
            self.assertTrue(hasattr(gov, name), name)
        self.assertLess(gov.BOOT_PRIME_WORKERS_SLOW, gov.BOOT_PRIME_WORKERS)
        self.assertGreater(gov.BOOT_PRIME_WORKERS_FAST, gov.BOOT_PRIME_WORKERS)


