class TestAnyComputerOnTheNetworkMayWatch(unittest.TestCase):
    """Owner 2026-11-19: "server permissions, passwords, unwanted": no login, no pairing, no question on the server; a computer says which profile it watches and gets it, and the streaming account has one fixed password."""

    def _port(self):
        import socket
        with socket.socket() as probe:
            probe.bind(("127.0.0.1", 0))
            return probe.getsockname()[1]

    def _slot(self, tmp, name="a"):
        path = os.path.join(tmp, "slot_%s.json" % name)
        with open(path, "w", encoding="utf-8") as fh:
            json.dump({"channels": {"05": {"schedules": {}}}}, fh)
        return path

    def _wait(self, test, limit=25.0):
        end = time.time() + limit
        while time.time() < end and not test():
            time.sleep(0.05)
        return test()

    def test_the_streaming_password_is_one_fixed_password_in_the_program(self):
        import server_files
        self.assertEqual(server_files.SHARE_PASSWORD, "RetroTVshare1")
        script, _names = server_files.build_share_script(["D:\\"], [], "r.txt", upkeep_result_path="u.txt")
        self.assertIn("ConvertTo-SecureString 'RetroTVshare1'", script)
        self.assertIn("LocalSubnet", script)
        self.assertIn("ConvertTo-SecureString 'RetroTVshare1'", server_files.upkeep_command("u.txt"))
        self.assertNotIn("Get-Content", server_files.upkeep_command("u.txt"))
        self.assertEqual(server_files.UPKEEP_VERSION, "retrotv-upkeep-v3")
        src = open(os.path.join(SCRIPTS, "server", "server_files.py"), encoding="utf-8").read()
        self.assertIn("os.remove(script_path)", src[src.index("def grant_sharing"):])

    def test_a_computer_connects_and_streams_with_no_question(self):
        import server_sync
        with tempfile.TemporaryDirectory() as tmp:
            slot, port, got, states = self._slot(tmp), self._port(), [], []
            b = server_sync.ScheduleBroadcaster(lambda: {"a": slot}, host="127.0.0.1", port=port, poll_interval=0.05)
            b.start()
            c = server_sync.ScheduleClient("127.0.0.1", port=port, slot_id="a", on_schedule=got.append, on_status=states.append, timeout=1.0, retry_interval=0.2)
            c.start()
            try:
                self.assertTrue(self._wait(lambda: got))
            finally:
                c.stop(); b.stop()
            self.assertIn("connected", states)
            self.assertEqual(str(got[0].get("slot_id")), "a")

    def test_a_computer_gets_only_the_profile_it_watches(self):
        import server_sync
        with tempfile.TemporaryDirectory() as tmp:
            slot_a, slot_b, port, got = self._slot(tmp, "a"), self._slot(tmp, "b"), self._port(), []
            b = server_sync.ScheduleBroadcaster(lambda: {"a": slot_a, "b": slot_b}, host="127.0.0.1", port=port, poll_interval=0.05)
            b.start()
            raw = []
            c = server_sync.ScheduleClient("127.0.0.1", port=port, slot_id="b", on_schedule=got.append, timeout=1.0)
            real_recv = server_sync.recv_message
            with mock.patch.object(server_sync, "recv_message", lambda sock: (lambda m: (raw.append(m), m)[1])(real_recv(sock))):
                c.start()
                try:
                    self._wait(lambda: got)
                    time.sleep(0.6)
                finally:
                    c.stop(); b.stop()
            self.assertEqual({str(m.get("slot_id")) for m in raw if m.get("type") == "schedule"}, {"b"})

    def test_a_server_of_another_version_is_reported_as_needing_an_update(self):
        import server_sync, socket, threading
        for message in ({"protocol": "retro-tv-schedule-v1", "type": "hello", "nonce": "00"},
                        {"protocol": server_sync.PROTOCOL, "type": "ping", "utc_offset_s": 0}):
            port = self._port()
            srv = socket.socket(); srv.bind(("127.0.0.1", port)); srv.listen(1)
            def serve(srv=srv, message=message):
                conn, _ = srv.accept()
                server_sync._send_message(conn, message)
                time.sleep(1.0); conn.close()
            threading.Thread(target=serve, daemon=True).start()
            states = []
            c = server_sync.ScheduleClient("127.0.0.1", port=port, slot_id="a", on_status=states.append, timeout=1.0, retry_interval=0.2)
            c.start()
            try:
                self.assertTrue(self._wait(lambda: "outdated" in states, 5.0), message)
            finally:
                c.stop(); srv.close()

    def test_a_connection_that_never_says_its_profile_is_closed(self):
        import server_sync, socket
        with tempfile.TemporaryDirectory() as tmp:
            port = self._port()
            b = server_sync.ScheduleBroadcaster(lambda: {"a": self._slot(tmp)}, host="127.0.0.1", port=port, poll_interval=0.05)
            b.start()
            try:
                sock = None
                end = time.time() + 10.0
                while sock is None:
                    try:
                        sock = socket.create_connection(("127.0.0.1", port), 5.0)
                    except OSError:
                        if time.time() > end:
                            raise
                        time.sleep(0.1)
                with sock:
                    self.assertEqual(server_sync.recv_message(sock).get("type"), "hello")
                    server_sync._send_message(sock, {"protocol": server_sync.PROTOCOL, "type": "auth"})
                    sock.settimeout(5.0)
                    self.assertEqual(sock.recv(1), b"", "the server closes a connection that never says its profile")
                    self.assertFalse(b._clients)
            finally:
                b.stop()

    def test_nothing_of_the_pairing_is_left(self):
        self.assertFalse(os.path.exists(os.path.join(SCRIPTS, "server", "server_security.py")))
        import server_sync, server_service, performance_governor as g
        for name in ("PAIR_WAIT_S", "AUTH_ANSWER_S", "PAIR_DENY_COOLDOWN_S"):
            self.assertFalse(hasattr(server_sync, name), name)
        for name in ("make_owner_question", "ask_through_program", "ask_on_desktop", "APPROVAL_REQUEST_NAME", "SERVER_APPROVAL_TIMEOUT_S"):
            self.assertFalse(hasattr(server_service, name), name)
        self.assertFalse(hasattr(g, "SERVER_APPROVAL_TIMEOUT_MS"))
        params = inspect.signature(server_sync.ScheduleClient.__init__).parameters
        for name in ("device_id", "secret", "ask_pairing", "on_pair_code", "on_paired"):
            self.assertNotIn(name, params)
        params = inspect.signature(server_sync.ScheduleBroadcaster.__init__).parameters
        for name in ("security", "approve", "slot_names", "limiter"):
            self.assertNotIn(name, params)
        for text in ("server_security", "server_approve_pairing", "ServerApprovalWatch", "_SERVER_NOT_ACCEPTED_STATUSES", "server_pairings",
                     "WAITING FOR THE SERVER PC TO ACCEPT", "SERVER_APPROVAL_TIMEOUT_MS"):
            self.assertNotIn(text, MAIN_SRC, text)
        import ui as _ui
        self.assertNotIn("server_approve_pairing", inspect.getsource(_ui))


