class TestServerClockLogsEachChange(unittest.TestCase):
    """Owner 2026-11-18: the server's clock line is written each time a channel loses its clock and when it comes back."""

    def test_lost_and_back_are_each_written(self):
        import server_clock
        server_clock._clock_state.clear()
        rows = {"on": None}
        hub = types.SimpleNamespace(at=lambda ch, t: rows["on"], upcoming=lambda ch, t, n: [])
        clocks = server_clock.ChannelClocks(now_fn=lambda: 100.0)
        with self.assertLogs(server_clock.log, level="INFO") as seen:
            clocks.snapshot(hub, ["05"])
            clocks.snapshot(hub, ["05"])
