class TestUserKeepsTheServersTime(unittest.TestCase):
    """Owner 2026-11-18: a User follows the server's own clock; it catches up only at a channel change or between commercial clips, never seeks inside a show, and nothing of it reaches Regular mode."""

    def setUp(self):
        import broadcast_clock
        self.bc = broadcast_clock
        self.addCleanup(broadcast_clock.set_server_skew, None)

    def test_the_skew_moves_the_clock_and_none_puts_it_back(self):
        base = self.bc.now()
        self.bc.set_server_skew(120.0)
        moved = self.bc.now()
        self.assertAlmostEqual((moved - base).total_seconds(), 120.0, delta=1.0)
        self.bc.set_server_skew(None)
        self.assertAlmostEqual((self.bc.now() - base).total_seconds(), 0.0, delta=1.0)

    def test_the_server_stamps_its_time_on_every_ping_and_the_user_reads_it(self):
        import server_sync
        got = []
        c = server_sync.ScheduleClient("127.0.0.1", on_server_time=lambda s_, a: got.append((s_, a)))
        c._take_clock({"type": "ping", "server_time": 1000.0, "utc_offset_s": 0})
        c._take_clock({"type": "schedule", "clock": {"utc_offset_s": 0}, "slot_id": "x"})
        self.assertEqual(len(got), 1)
        self.assertEqual(got[0][0], 1000.0)
        self.assertIn('"server_time": station_clock.now_epoch()', inspect.getsource(server_sync.ScheduleBroadcaster._run))

    def _ns(self, locked=True):
        moves = []
        state = {}
        opened = []
        ns = {"collections": collections, "threading": threading, "SERVER_CLOCK_SAMPLES": 5, "SERVER_CLOCK_DRIFT_TOLERANCE_S": 2.0, "SERVER_CLOCK_MISMATCH_WARN_S": 60.0,
              "post_status_notice": lambda text, good=False: None, "time": time,
              "SLOT_TAIL_HOLD_MAX_SECONDS": 3.0, "SERVER_BREAK_FLASH_EACH_S": 0.5, "SERVER_BREAK_FLASH_TOTAL_S": 2.0, "SERVER_BREAK_RECENT_ADS_S": 3600.0,
              "broadcast_clock": types.SimpleNamespace(set_server_skew=lambda v: moves.append(v),
                                                       now=lambda: types.SimpleNamespace(timestamp=lambda: 1000.0)),
              "log": logging.getLogger("test-server-time"), "os": os, "_log_swallowed": lambda *a: None,
              "db": types.SimpleNamespace(channels_db={"07": {"server_locked": locked}}),
              "app_state": state, "pygame": types.SimpleNamespace(time=types.SimpleNamespace(get_ticks=lambda: 5000)),
              "vlc_engine": types.SimpleNamespace(play_file_segmented=lambda f, seek, gain=1.0, defer_unmute=False: opened.append((f, seek))),
              "_lookup_file_gain": lambda ch, f: 1.0, "_configured_transition_style": lambda: "black"}
        exec(MAIN_SRC[MAIN_SRC.index("_server_time_state = {"):MAIN_SRC.index("def _disconnect_remote_server(")], ns)
        return ns, moves, state, opened

    @staticmethod
    def _row(path, start, kind="commercial"):
        return {"path": path, "planned_start": start, "kind": kind}

    def test_the_first_ping_links_and_later_drift_waits_for_a_safe_moment(self):
        ns, moves, _s, _o = self._ns()
        ns["_on_server_time"](1010.0, 1000.0)
        self.assertEqual(moves, [10.0])
        for _ in range(4):
            ns["_on_server_time"](1016.0, 1000.0)
        self.assertEqual(moves, [10.0], "drift found while a show plays moves nothing")
        self.assertAlmostEqual(ns["_server_time_pending"](), 6.0)
        ns["_server_time_settle_at_channel_change"]()
        self.assertEqual(moves[-1], 16.0)
        self.assertEqual(ns["_server_time_pending"](), 0.0)

    def test_a_small_stray_is_left_alone(self):
        ns, moves, _s, _o = self._ns()
        ns["_on_server_time"](1000.0, 1000.0)
        for _ in range(5):
            ns["_on_server_time"](1001.5, 1000.0)
        self.assertEqual(ns["_server_time_pending"](), 0.0)

    def test_behind_the_server_whole_commercials_are_dropped_and_the_next_item_opens_at_its_start(self):
        ns, _m, _s, _o = self._ns()
        plan = ns["_server_break_plan"]
        rows = [self._row("a.mkv", 100.0), self._row("b.mkv", 130.0), self._row("show.mkv", 145.0, "episode")]
        pool = [("a.mkv", 30.0), ("b.mkv", 15.0)]
        self.assertEqual(plan(35.0, 100.0, rows, pool, [], 0.0), ("drop", 30.0, 1))
        self.assertEqual(plan(50.0, 100.0, rows, pool, [], 0.0), ("drop", 45.0, 2), "the whole break may go; the show still opens at its first second")
        self.assertIsNone(plan(10.0, 100.0, rows, pool, [], 0.0), "smaller than any commercial: it waits, never skips part of one")

    def test_a_fade_bumper_is_never_dropped(self):
        ns, _m, _s, _o = self._ns()
        rows = [self._row("fade.mkv", 100.0), self._row("a.mkv", 105.0), self._row("show.mkv", 135.0, "episode")]
        self.assertIsNone(ns["_server_break_plan"](40.0, 100.0, rows, [("a.mkv", 30.0)], [], 0.0))

    def test_ahead_of_the_server_one_whole_commercial_not_aired_lately_is_added(self):
        ns, _m, _s, _o = self._ns()
        plan = ns["_server_break_plan"]
        rows = [self._row("b.mkv", 100.0), self._row("show.mkv", 115.0, "episode")]
        pool = [("a.mkv", 30.0), ("b.mkv", 15.0), ("c.mkv", 10.0), ("d.mkv", 12.0)]
        self.assertEqual(plan(-20.0, 100.0, rows, pool, ["c.mkv"], 0.0), ("add", "d.mkv", 12.0),
                         "a is too long, b is in this break, c aired lately")

    def test_a_gap_smaller_than_any_commercial_is_a_short_flash_up_to_two_seconds_a_break(self):
        ns, _m, _s, _o = self._ns()
        plan = ns["_server_break_plan"]
        rows = [self._row("b.mkv", 100.0), self._row("show.mkv", 115.0, "episode")]
        pool = [("a.mkv", 30.0)]
        self.assertEqual(plan(-4.0, 100.0, rows, pool, [], 0.0), ("flash", 0.5))
        _kind, _secs = plan(-4.0, 100.0, rows, pool, [], 1.8)
        self.assertEqual(_kind, "flash")
        self.assertAlmostEqual(_secs, 0.2)
        self.assertIsNone(plan(-4.0, 100.0, rows, pool, [], 2.0), "the break's two seconds are used up; it waits")

    def test_applying_moves_the_clock_only_by_whole_items(self):
        ns, moves, state, opened = self._ns()
        ns["_on_server_time"](1000.0, 1000.0)
        self.assertFalse(ns["_server_break_apply"]("07", {"drop": 30.0, "count": 1}))
        self.assertEqual(moves[-1], 30.0)
        self.assertTrue(ns["_server_break_apply"]("07", {"until": 1000.0, "add": ("d.mkv", 12.0)}))
        self.assertEqual(moves[-1], 18.0)
        self.assertEqual(opened, [("d.mkv", 0)], "the added commercial opens at its first second")
        self.assertEqual(state["_slot_tail_hold"]["add"], ("d.mkv", 12.0))
        self.assertTrue(ns["_server_break_apply"]("07", {"until": 1000.5, "flash": 0.5, "budget_key": ("07", 1.0)}))
        self.assertEqual(moves[-1], 17.5)
        self.assertGreater(state["channel_switch_black_until"], 5000)
        self.assertEqual(ns["_server_break_flash_used"][("07", 1.0)], 0.5)

    def test_while_an_added_commercial_plays_the_channel_airs_it(self):
        ns, _m, _s, _o = self._ns()
        st = ns["_server_break_added_state"]({"add": ("d.mkv", 12.0), "started": 995.0, "block": "Evening"})
        self.assertEqual((st["mode"], st["file"], st["seek"], st["duration"], st["block"]), ("Commercial", "d.mkv", 5.0, 12.0, "Evening"))

    def test_a_channel_of_this_pc_never_moves_the_clock_in_a_break(self):
        ns, moves, _s, _o = self._ns(locked=False)
        ns["_on_server_time"](1000.0, 1000.0)
        for _ in range(5):
            ns["_on_server_time"](1010.0, 1000.0)
        self.assertIsNone(ns["_server_time_settle_in_break"]("07", {"file": "ad.mkv"}))
        self.assertEqual(moves, [0.0])

    def test_no_seek_skip_or_held_picture_is_left_in_the_catch_up(self):
        settle = get_function_source("_server_time_settle_in_break")
        self.assertNotIn("calculate_slotted_playback_state", settle)
        self.assertNotIn("_server_time_move", settle, "planning moves nothing; only _server_break_apply does")
        self.assertIn("never happens in Regular mode", get_function_source("_server_break_apply"))

    def test_the_hooks_are_where_they_belong(self):
        self.assertIn("_server_time_reset()", get_function_source("_disconnect_remote_server"))
        change = get_function_source("change_channel")
        self.assertIn("_server_time_settle_at_channel_change()", change)
        loop_part = MAIN_SRC[MAIN_SRC.index("_break_hold = _server_time_settle_in_break(ch, current_playback_state)") - 400:]
        self.assertIn('current_playback_state.get("mode") == "Commercial"', loop_part[:500])
        self.assertIn("_skip_advance_this_frame = _server_break_apply(_wd_ch_key, _break_hold)", MAIN_SRC)
        self.assertIn("current_playback_state = _server_break_added_state(_added_hold)", MAIN_SRC)
        self.assertIn("on_server_time=_on_server_time", MAIN_SRC)


class TestUserNamesTheFilesTheServerScansFirst(unittest.TestCase):
    """Owner 2026-11-18: with the program on the server PC closed, a watching User stands in for it: it names the watched channel's show on air, next shows and the files its schedule waits for, and the server measures those first."""

    def test_the_server_keeps_what_each_user_named_while_it_is_fresh(self):
        import server_sync
        b = server_sync.ScheduleBroadcaster.__new__(server_sync.ScheduleBroadcaster)
        b._lock = threading.Lock()
        b._watching = {object(): ("s1", "07", time.monotonic(), ["D:\\TV\\a.mkv", "D:\\TV\\b.mkv"]),
                       object(): ("s2", "09", time.monotonic(), ["D:\\TV\\c.mkv"]),
                       object(): ("s1", "08", -1e9, ["D:\\TV\\old.mkv"])}
        self.assertEqual(b.watching_next("s1"), [("07", ["D:\\TV\\a.mkv", "D:\\TV\\b.mkv"])])
        self.assertEqual(b.watching("s1"), {"07"})
        src = inspect.getsource(server_sync.ScheduleBroadcaster._read_watching)
        self.assertIn("[:WATCHING_NEXT_FILES]", src)
        self.assertIn("isinstance(f, str)", src)

    def test_the_user_sends_the_files_with_its_watching_report(self):
        import server_sync
        sent = []
        c = server_sync.ScheduleClient("127.0.0.1", watching_provider=lambda: "7",
                                       next_files_provider=lambda: ["D:\\TV\\%d.mkv" % i for i in range(40)])
        sock = object()
        c.sock = sock
        def _send(_sock, message):
            sent.append(message)
            c._stop.set()
        c._send = _send
        c._report_watching(sock)
        self.assertEqual(sent[0]["type"], "watching")
        self.assertEqual(sent[0]["channel"], "07")
        self.assertEqual(len(sent[0]["next"]), server_sync.WATCHING_NEXT_FILES)

    def test_the_scanner_takes_only_files_its_slot_schedules_on_air_first(self):
        import json, server_scanner
        with tempfile.TemporaryDirectory() as tmp:
            slot = os.path.join(tmp, "slot.json")
            with open(slot, "w", encoding="utf-8") as fh:
                json.dump({"channels": {"07": {"schedules": {"Full Day": [{"path": "D:\\TV\\A.mkv"}, {"path": "D:\\TV\\B.mkv"}]}}}}, fh)
            sc = server_scanner.FactsScanner(lambda: {"s1": slot}, lambda: False, lambda: None,
                                             next_files_fn=lambda slot_id: [("07", ["d:/tv/a.mkv", "C:\\Windows\\x.mkv", "D:\\TV\\B.mkv"])])
            self.assertEqual(sc._named_files({"s1": slot}, "s1"),
                             [("D:\\TV\\A.mkv", 0, True), ("D:\\TV\\B.mkv", 2, True)])
            first = sc._scheduled_lookup({"s1": slot})
            self.assertIs(sc._scheduled_lookup({"s1": slot}), first, "the slot file is read again only when it changes")
        self.assertIn("self._named_files(slot_paths, slot_id)", inspect.getsource(server_scanner.FactsScanner._add_slot_items))

    def test_the_program_names_the_on_air_next_and_waited_for_files_in_the_servers_spelling(self):
        hub = types.SimpleNamespace(at=lambda ch, now: {"path": "\\\\SRV\\tv\\on.mkv"},
                                    upcoming=lambda ch, now, n, kinds=None: [{"path": "\\\\SRV\\tv\\next.mkv"}, {"path": "\\\\SRV\\tv\\unshared.mkv"}])
        fmap = types.SimpleNamespace(server_path_for=lambda unc: {"\\\\SRV\\tv\\on.mkv": "D:\\TV\\on.mkv", "\\\\SRV\\tv\\next.mkv": "D:\\TV\\next.mkv",
                                                                  "\\\\SRV\\tv\\wait.mkv": "D:\\TV\\wait.mkv"}.get(unc))
