class TestFileChecksListAFolderOnceOnOneThreadPerDrive(unittest.TestCase):
    """Owner 2026-11-18 (audit A1): a file existence check used to start a thread of its own, and every file in use was checked again on its own every 30 s; now one long-lived thread per drive answers them, and one listing of a folder answers every file of it that is due."""

    def setUp(self):
        import media
        self.media = media
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, True)
        self.files = []
        for name in ("Show S01E01.mkv", "Show S01E02.mkv", "Show S01E03.mkv"):
            path = os.path.join(self.tmp, name)
            open(path, "w").close()
            self.files.append(path)
        self.addCleanup(self._forget)

    def _forget(self):
        with self.media._path_exists_cache_lock:
            for path in self.files + [os.path.join(self.tmp, "gone.mkv")]:
                self.media._path_exists_cache.pop(path, None)
            self.media._path_folder_index.pop(self.tmp, None)

    def test_one_listing_answers_the_asked_files_and_the_held_ones_that_are_due(self):
        media = self.media
        old = media._now_ms() - media._PATH_FOUND_TTL_MS
        media._store_path_status(self.files[2], media.PATH_PRESENT, old)
        listings = []
        real_listdir = os.listdir
        with patch.object(media.os, "listdir", lambda d: listings.append(d) or real_listdir(d)):
            got = media._check_path_statuses_now([self.files[0], os.path.join(self.tmp, "gone.mkv")])
        self.assertEqual(got, {self.files[0]: media.PATH_PRESENT, os.path.join(self.tmp, "gone.mkv"): media.PATH_MISSING})
        self.assertEqual(listings, [self.tmp], "one listing of the folder")
        self.assertGreater(media._path_exists_cache[self.files[2]][1], old, "the held file of the same folder was renewed by that listing")

    def test_a_lone_file_is_looked_up_by_itself(self):
        media = self.media
        listings = []
        with patch.object(media.os, "listdir", lambda d: listings.append(d) or []):
            self.assertEqual(media._bounded_os_path_exists(self.files[1]), media.PATH_PRESENT)
        self.assertEqual(listings, [])

    def test_a_hung_drive_holds_one_thread_and_the_batch_still_answers_in_time(self):
        media = self.media
        release = threading.Event()
        real = media._check_folder_paths
        hung_root = os.path.join(os.sep, "hung-drive-xyz")
        paths = [os.path.join(hung_root, "f%d" % i, "a.mkv") for i in range(15)]
        with patch.object(media, "_drive_root_of", lambda p: "HUNG:" if str(p).startswith(hung_root) else None), \
                patch.object(media, "_check_folder_paths", lambda folder, ps, now: (release.wait(5) and {}) if folder.startswith(hung_root) else real(folder, ps, now)), \
                patch.object(media, "_slow_path_check", lambda p, t: media.PATH_UNKNOWN), \
                patch.object(media, "_is_drive_responsive", lambda p: True):
            started = time.monotonic()
            got = media._check_path_statuses_now(paths, timeout_ms=300)
            took = time.monotonic() - started
            threads = [t for t in threading.enumerate() if t.name == "PathExistsProbe-HUNG:"]
            release.set()
        self.assertTrue(all(v == media.PATH_UNKNOWN for v in got.values()))
        self.assertLess(took, 2.0, "the whole batch waits one timeout, not one per file")
        self.assertEqual(len(threads), 1, "one thread for the hung drive, however many checks wait for it")

    def test_no_check_starts_a_thread_of_its_own_any_more(self):
        with open(_script("media.py"), encoding="utf-8") as fh:
            src = fh.read()
        self.assertNotIn('name="PathExistsProbe").start()', src)
        self.assertIn("for p, status in _check_path_statuses_now(paths).items():", src)
        self.assertIn("_check_path_statuses_now(todo)", src)


class TestDriveHealthUsesOneThreadPerDrive(unittest.TestCase):
    """Owner 2026-11-18 (audit A2): the drive health check used to start a new thread every DRIVE_RECHECK_INTERVAL_MS for each drive; each drive now has one long-lived thread that is woken for each check."""

    def test_many_checks_of_one_drive_share_one_thread(self):
        import media
        root = "HEALTHTEST-%d:" % os.getpid()
        done = []
        real = media._drive_probe_worker
        with patch.object(media, "_drive_probe_worker", lambda r: done.append(r) if r == root else real(r)):
            for _ in range(5):
                media._wake_drive_prober(root)
                deadline = time.monotonic() + 2.0
                want = len(done) + 1
                while len(done) < want and time.monotonic() < deadline:
                    time.sleep(0.01)
            threads = [t for t in threading.enumerate() if t.name == "_drive_probe_worker-%s" % root]
        self.assertEqual(done, [root] * 5)
        self.assertEqual(len(threads), 1)

    def test_the_monitor_wakes_the_drive_thread_and_starts_none(self):
        with open(_script("media.py"), encoding="utf-8") as fh:
            src = fh.read()
        loop = src[src.index("def _drive_health_monitor_loop():"):src.index("def _is_drive_responsive(path):")]
        self.assertNotIn("threading.Thread(", loop)
        self.assertEqual(loop.count("_wake_drive_prober(root)"), 2)
        import health_monitor
        self.assertTrue(any("_drive_probe_worker-D:\\".startswith(n) for n in health_monitor._NEVER_STUCK), "the waiting health thread is never reported as stuck")


