class TestScanSnapshotIsRebuiltOnlyWhenSomethingChanged(unittest.TestCase):
    """Owner 2026-11-18 (audit A4): the scan snapshot walked every channel's whole schedule every 5 to 15 s even with a fully scanned library; it is now rebuilt only when something it reads changed, and at least every SCAN_SNAPSHOT_MAX_SKIP_S."""

    def _run(self, inputs_seq, rounds):
        import performance_governor as gov
        clock = [0.0]
        builds = []

        class Shutdown:
            def __init__(self):
                self.n = 0
            def is_set(self):
                return self.n >= rounds
            def wait(self, seconds):
                clock[0] += seconds
                return False

        down = Shutdown()

        def idle(seconds, generation):
            clock[0] += seconds
            down.n += 1
            return False

        def build():
            builds.append(clock[0])
            return {"built_at": clock[0], "channels": {}}
        seq = list(inputs_seq)
        ns = {"db": object(), "time": types.SimpleNamespace(monotonic=lambda: clock[0]), "_app_shutting_down": down, "_scan_files_added_generation": [0], "_scan_work_generation": [0],
              "_background_activity": lambda name: __import__("contextlib").nullcontext(), "_build_scan_snapshot": build, "_scan_snapshot_lock": threading.Lock(),
              "_publish_channel_scan_progress": lambda fresh: None, "log": types.SimpleNamespace(warning=lambda *a: None), "_scan_idle_wait": idle,
              "SCAN_SNAPSHOT_INTERVAL_S": 5.0, "SCAN_SNAPSHOT_DUTY_FACTOR": 0.0, "SCAN_SNAPSHOT_MAX_REST_S": 0.0, "_scan_snapshot": {"built_at": 0.0, "channels": {}},
              "_scan_snapshot_inputs": lambda: seq.pop(0) if len(seq) > 1 else seq[0], "_snapshot_inputs_seen": [None, 0.0],
              "SCAN_SNAPSHOT_MAX_SKIP_S": gov.SCAN_SNAPSHOT_MAX_SKIP_S, "app_state": {}}
        exec(compile(get_function_source("_scan_snapshot_worker"), "w", "exec"), ns)
        ns["_scan_snapshot_worker"]()
        return builds, ns, clock

    def test_nothing_changed_means_no_rebuild_but_a_fresh_snapshot(self):
        builds, ns, clock = self._run(["same"], rounds=5)
        self.assertEqual(len(builds), 1)
        self.assertEqual(ns["_scan_snapshot"]["built_at"], clock[0] - 5.0, "the kept snapshot is marked fresh, so no reader rebuilds it on the spot")

    def test_a_change_rebuilds_at_once(self):
        builds, _ns, _clock = self._run(["a", "a", "b", "b"], rounds=4)
        self.assertEqual(len(builds), 2)

    def test_it_is_rebuilt_at_least_every_max_skip_seconds(self):
        import performance_governor as gov
        rounds = int(gov.SCAN_SNAPSHOT_MAX_SKIP_S / 5.0) + 2
        builds, _ns, _clock = self._run(["same"], rounds=rounds)
        self.assertEqual(len(builds), 2)

    def test_the_change_key_covers_every_input(self):
        body = get_function_source("_scan_snapshot_inputs")
        for needle in ("db.settings_change_count()", "media.path_status_generation()", "_scan_files_added_generation[0]", "total_changes",
                       "media.get_duration_hub", "media.get_file_facts_hub", "broadcast_clock.date()"):
            self.assertIn(needle, body)
        self.assertNotIn("_get_probe_now_state", body, "owner 2026-11-18: no scheduler run per channel on the scan thread")
        self.assertNotIn("calculate_slotted_playback_state", body)


