class TestServerReadsItsScheduleOncePerMoment(unittest.TestCase):
    """Owner 2026-11-18 (audit A8): the clocks sent to Users, the scan order and the scanner's show on air each read the hub on their own; one reading, kept SERVER_CLOCK_KEEP_S, now serves all three."""

    class _Hub:
        def __init__(self):
            self.reads = 0

        def at(self, channel, epoch):
            self.reads += 1
            return {"path": "D:\\a.mkv", "kind": "episode", "planned_start": 900.0, "used_length": 200.0}

        def upcoming(self, channel, after, count):
            return [{"path": "D:\\b.mkv", "kind": "episode", "planned_start": 1100.0, "used_length": 100.0}]

    def test_a_kept_reading_counts_down_from_the_moment_it_is_handed_out(self):
        import server_clock
        now = [1000.0]
        hub = self._Hub()
        clocks = server_clock.ChannelClocks(now_fn=lambda: now[0], keep_s=5.0)
        first = clocks.snapshot(hub, ["05"])
        now[0] = 1003.0
        again = clocks.snapshot(hub, ["05"])
        self.assertEqual(hub.reads, 1, "the second ask within the keep time reads nothing")
        self.assertEqual(first["05"]["now"]["remaining"], 100.0)
        self.assertEqual(again["05"]["now"]["remaining"], 97.0, "seconds left are worked out for the moment it is handed out")
        self.assertEqual(again["05"]["next"][0]["starts_in"], 97.0)
        now[0] = 1006.0
        clocks.snapshot(hub, ["05"])
        self.assertEqual(hub.reads, 2, "past the keep time the hub is read again")

    def test_a_kept_reading_whose_show_ended_is_never_handed_out(self):
        import server_clock
        now = [1000.0]
        hub = self._Hub()
        clocks = server_clock.ChannelClocks(now_fn=lambda: now[0], keep_s=500.0)
        clocks.snapshot(hub, ["05"])
        now[0] = 1100.5
        clocks.snapshot(hub, ["05"])
        self.assertEqual(hub.reads, 2)

    def test_no_keep_reads_every_time_as_before(self):
        import server_clock
        hub = self._Hub()
        clocks = server_clock.ChannelClocks(now_fn=lambda: 1000.0)
        clocks.snapshot(hub, ["05"])
        clocks.snapshot(hub, ["05"])
        self.assertEqual(hub.reads, 2)

    def test_the_scanners_show_on_air_comes_from_the_same_reading(self):
        import server_clock, server_scanner
        hub = self._Hub()
        clocks = server_clock.ChannelClocks(now_fn=lambda: 1000.0, keep_s=5.0)
        scanner = server_scanner.FactsScanner(lambda: {}, lambda: False, lambda: None, clocks=clocks)
        scanner._held_hub = (None, hub)
        at = scanner._hub_now(None, None, {"05": {"active": True}, "06": {"active": False}})
        self.assertEqual(at("5"), "D:\\a.mkv")
        self.assertEqual(at("06"), "")
        scanner._clock_files(None, {"05": {"active": True}}, ())
        self.assertEqual(hub.reads, 1, "the scan order used the same reading")


class TestServerSendsTheClocksOnlyWhenTheyChange(unittest.TestCase):
    """Owner 2026-11-18 (audit A7): the channel clocks went to every User every SERVER_CLOCKS_REFRESH_S seconds; they are now sent when a show, a start or what a show still lacks changed, and at once to a User that just connected."""

    def _broadcaster(self, clocks):
        import server_sync
        b = server_sync.ScheduleBroadcaster.__new__(server_sync.ScheduleBroadcaster)
        b._lock = threading.Lock()
        b._clocks_sent_at, b._clocks_shape, b._pending_clock_clients = {}, {}, set()
        b.clock_provider = lambda channels, slot_id: clocks[0]
        b.port = 0
        b._may_see = lambda client, slot_id: True
        sent = []
        b._broadcast = lambda message, clients=None: sent.append((message["channels"], None if clients is None else set(clients)))
        return b, sent

    def _clock(self, remaining, file="D:\\a.mkv"):
        return {"05": {"now": {"file": file, "start": 0.0, "end": 1000.0, "remaining": remaining, "starts_in": 0.0}, "next": []}}

    def test_only_a_change_or_a_new_user_is_sent(self):
        import server_sync
        clocks = [self._clock(900.0)]
        b, sent = self._broadcaster(clocks)
        self.addCleanup(setattr, server_sync, "SERVER_CLOCKS_REFRESH_S", server_sync.SERVER_CLOCKS_REFRESH_S)
        server_sync.SERVER_CLOCKS_REFRESH_S = 0.0
        b._send_clocks("a", {})
        self.assertEqual(len(sent), 1, "the first look sends")
        clocks[0] = self._clock(895.0)
        b._send_clocks("a", {})
        self.assertEqual(len(sent), 1, "only the seconds left moved: nothing is sent")
        b._pending_clock_clients.add("new user")
        b._send_clocks("a", {})
        self.assertEqual(sent[-1][1], {"new user"}, "a User that just connected gets them, and only it")
        self.assertEqual(b._pending_clock_clients, set())
        clocks[0] = self._clock(890.0, file="D:\\b.mkv")
        b._send_clocks("a", {})
        self.assertEqual((len(sent), sent[-1][1]), (3, None), "a new show goes to every User")

    def test_a_new_connection_waits_for_its_clocks(self):
        import server_sync
        admit = inspect.getsource(server_sync.ScheduleBroadcaster._admit)
        admit = admit[admit.index("self._clients.add(client)"):][:300]
        self.assertIn("self._pending_clock_clients.add(client)", admit)


