class TestRegularAndServerFirstLoadWaitsStaySeparate(unittest.TestCase):
    """Owner 2026-11-18: media added to a Regular channel sitting on Static goes to the loading background at once and has 7 s to play before Static and the reason; the server side keeps its own 10 s; the stall clock never counts the time the channel sat empty."""

    def _ns(self, profile=None, locked=False, editing=None):
        state = {"active_local_profile": profile, "current_channel": "05"}
        ns = {"app_state": state, "db": types.SimpleNamespace(channels_db={"05": {"server_locked": locked}}, config={"active_server_slot": editing}),
              "STALL_FORCES_STATIC_FIRST_LOAD_MS": 10000, "REGULAR_FIRST_LOAD_STATIC_MS": 7000}
        exec(get_function_source("_server_rules_apply"), ns)
        exec(get_function_source("_first_load_static_ms"), ns)
        return ns, state

    def test_regular_waits_seven_and_the_server_side_ten(self):
        import performance_governor as gov
        self.assertEqual((gov.REGULAR_FIRST_LOAD_STATIC_MS, gov.STALL_FORCES_STATIC_FIRST_LOAD_MS), (7000, 10000))
        self.assertEqual(self._ns()[0]["_first_load_static_ms"]("05"), 7000)
        self.assertEqual(self._ns(profile="2")[0]["_first_load_static_ms"]("05"), 10000, "a server profile on screen")
        self.assertEqual(self._ns(locked=True)[0]["_first_load_static_ms"]("05"), 10000, "a channel streamed from a server")
        self.assertEqual(self._ns(editing="server1")[0]["_first_load_static_ms"]("05"), 10000,
                         "owner 2026-11-23: a server profile being edited is server mode too")

    def test_media_arriving_on_empty_static_starts_a_fresh_load_clock(self):
        state = {"_last_new_frame_ticks": 0, "_had_first_frame_this_tune": True, "_static_hold_until_frame": True, "last_vlc_retry_at": 99}
        ns = {"app_state": state, "SILENT_STATIC_REASONS": {"no_media_scheduled", "channel_inactive", "awaiting_server_pick"},
              "_PROFILE_LOADING_REASONS": ("first_file_scanning", "visualizer_scanning", "not_scanned"),
              "_first_load_static_ms": lambda ch=None: 7000, "log": logging.getLogger("t"), "SCHEDULE_PENDING_REASON": "schedule_pending",
              "SERVER_SCHEDULE_GAP_REASON": "server_schedule_gap", "FIRST_MEDIA_STATIC_MS": 2000, "_channels_on_fault_static": set()}
        exec(get_function_source("_note_media_arrived"), ns)
        f = ns["_note_media_arrived"]
        self.assertFalse(f("05", {"mode": "Static", "reason": "no_media_scheduled"}, 1000))
        self.assertFalse(f("05", {"mode": "Static", "reason": "no_media_scheduled"}, 90000), "still empty: nothing starts")
        self.assertTrue(f("05", {"mode": "Static", "reason": "first_file_scanning"}, 91000))
        self.assertEqual((state["_last_new_frame_ticks"], state["_had_first_frame_this_tune"], state["_static_hold_until_frame"], state["last_vlc_retry_at"]),
                         (91000, False, False, 0))
        state["_had_first_frame_this_tune"] = True
        self.assertTrue(f("05", {"mode": "Video", "reason": None}, 95000), "owner 2026-11-20: the first show's open gets its own load wait")
        self.assertEqual((state["_last_new_frame_ticks"], state["_had_first_frame_this_tune"], state["_static_hold_until_frame"]), (95000, False, False),
                         "named inside the 7 s black wait: the black goes on into the open")
        f("05", {"mode": "Static", "reason": "first_file_scanning"}, 96000)
        self.assertTrue(f("05", {"mode": "Video", "reason": None}, 105000))
        self.assertEqual((state["_last_new_frame_ticks"], state["_static_hold_until_frame"]), (105000, True),
                         "owner 2026-11-21: fallen to Static after 7 s, the open stays under the Static, never back to black")
        self.assertFalse(f("05", {"mode": "Video", "reason": None}, 106000), "a show already on air keeps its clock")
        self.assertEqual(state["_last_new_frame_ticks"], 105000)
        self.assertFalse(f("06", {"mode": "Video", "reason": None}, 107000), "a channel change is not media arriving")
        f("06", {"mode": "Static", "reason": "picture_stalled"}, 108000)
        self.assertFalse(f("06", {"mode": "Video", "reason": None}, 109000), "only a scanning Static hands over a fresh clock")

    def test_the_wait_is_the_loading_background_and_silent(self):
        src = MAIN_SRC
        self.assertIn("_note_media_arrived(ch, current_playback_state, pygame.time.get_ticks())", src)
        self.assertIn('return _reason == SCHEDULE_PENDING_REASON or _regular_channel_still_loading(ch, _reason)', get_function_source("_channel_cover_hold"))
        self.assertIn("            and not _cover_hold\n", src)
        self.assertIn("if reason not in _PROFILE_LOADING_REASONS or _server_rules_apply(ch_key):", get_function_source("_regular_channel_still_loading"))


class TestAnEmptyFolderWalkLooksAgainAndSaysWhy(unittest.TestCase):
    """Owner log 2026-11-18 18:08: two adds found 0 files in 2 folders and Done closed the explorer with nothing added; the same add 9 s later found 1128. A walk that finds nothing while a drive was not answering, a folder could not be read or nothing was listed walks again; an add that still finds nothing keeps the explorer open with a banner, and the log names the folders and what was passed by."""

    def test_the_walker_counts_what_it_passed_by(self):
        import tempfile
        with tempfile.TemporaryDirectory() as root:
            os.makedirs(os.path.join(root, "Season 1"))
            open(os.path.join(root, "Season 1", "a.mkv"), "w").close()
            open(os.path.join(root, "notes.txt"), "w").close()
            tally = {}
            got = list(media.iter_files_resolving_shortcuts(root, valid_exts={".mkv"}, tally=tally))
            self.assertEqual([os.path.basename(p) for p in got], ["a.mkv"])
            self.assertEqual(tally.get("wrong_type"), 1)
            self.assertEqual(tally.get("entries"), 3)
            asleep = {}
            self.assertEqual(list(media.iter_files_resolving_shortcuts(root, is_drive_responsive=lambda p: False, tally=asleep)), [])
            self.assertEqual(asleep.get("asleep"), 1)

    def _ns(self, answers):
        state = {"file_explorer_expand_lock": threading.Lock()}
        calls = []

        def walker(p, ignored_dir_names=None, valid_exts=None, is_drive_responsive=None, tally=None):
            calls.append(p)
            is_drive_responsive(p)
            got = answers.pop(0) if answers else []
            if not got:
                tally["entries"] = tally.get("entries", 0)
            else:
                tally["entries"] = tally.get("entries", 0) + len(got)
            yield from got

        ns = {"app_state": state, "time": time, "os": os, "log": logging.getLogger("t"),
              "_is_drive_responsive": lambda p: True, "_FE_EMPTY_WALK_RETRIES": 2, "_FE_EMPTY_WALK_RETRY_SECONDS": 0.0,
              "_app_shutting_down": threading.Event(), "_FILE_WALK_ACTIVE": threading.Event(),
              "media": types.SimpleNamespace(iter_files_resolving_shortcuts=walker, note_paths_present=lambda found: None)}
        for name in ("_fe_walk_tally_text", "_fe_walk_picked_folders", "_fe_expand_worker"):
            exec(get_function_source(name), ns)
        return ns, state, calls

    def test_a_walk_that_listed_nothing_walks_again(self):
        ns, state, calls = self._ns([[], [os.path.normpath("/m/a.mkv")]])
        ns["_fe_expand_worker"](1, "add", ["/m"], {".mkv"})
        self.assertEqual(len(calls), 2)
        self.assertEqual(state["file_explorer_expand_result"][1], [os.path.normpath("/m/a.mkv")])

    def test_it_gives_up_after_the_governor_retries(self):
        ns, state, calls = self._ns([])
        with self.assertLogs("t", level="WARNING") as seen:
            ns["_fe_expand_worker"](1, "add", ["/m"], {".mkv"})
        self.assertEqual(len(calls), 3)
        self.assertIn("found no file to use in: /m", "\n".join(seen.output))

    def test_an_empty_add_keeps_the_explorer_open_with_a_banner(self):
        poll = get_function_source("_fe_poll_expand")
        at = poll.index('if op == "add" and not found:')
        block = poll[at:at + 400]
        self.assertIn('_fe_banner("NO FILE TO ADD WAS FOUND IN THE PICKED FOLDER(S)")', block)
        self.assertIn('app_state["file_explorer_done_requested"] = False', block)
        self.assertLess(at, poll.index("_fe_request_close()"))
        import performance_governor as _pg
        self.assertEqual((_pg.FILE_EXPLORER_EMPTY_WALK_RETRIES, _pg.FILE_EXPLORER_EMPTY_WALK_RETRY_SECONDS), (2, 2.0))


class TestServerMenuNeverHoldsTheControlsWithoutAWindowsBox(unittest.TestCase):
    """Owner 2026-11-18: Windows Security held the sharing task and the controls stayed locked up to 2 minutes with no box on screen; only a Windows box on its way or on screen locks them, Back lets them go, and a failure says why."""

    def _ns(self, ticks, state):
        notices = []
        ns = {"app_state": state, "log": logging.getLogger("t"), "post_status_notice": lambda text, good=False: notices.append(text),
              "_SERVER_PERMISSION_LOCKED_STATES": ("asking", "waiting_box"), "_boot_bar_const": lambda name, fallback: fallback,
              "db": types.SimpleNamespace(config={}, save_settings=lambda: None), "sys": types.SimpleNamespace(platform="linux"),
              "pygame_hwnd": None, "pygame": pygame}
        for name in ("_server_permission_tick", "_let_go_of_server_permission", "_server_permission_locked", "_is_server_permission_back"):
            exec(get_function_source(name), ns)
        return ns, notices

    def test_no_box_within_the_wait_lets_the_controls_go(self):
        state = {"_server_permission": {"state": "asking", "started_ms": 0, "layer": "ADV"}}
        ns, notices = self._ns(0, state)
        ns["_server_permission_tick"](7000)
        self.assertTrue(ns["_server_permission_locked"]())
        ns["_server_permission_tick"](8500)
        self.assertFalse(ns["_server_permission_locked"](), "past SERVER_PERMISSION_BOX_WAIT_SECONDS with no box the controls are free")
        self.assertIn("SERVER: SETTING UP SHARING, PLEASE WAIT", notices)

    def test_back_lets_the_controls_go(self):
        state = {"_server_permission": {"state": "waiting_box", "started_ms": 0}}
        ns, notices = self._ns(0, state)
        self.assertTrue(ns["_is_server_permission_back"](types.SimpleNamespace(type=pygame.KEYDOWN, key=pygame.K_ESCAPE)))
        ns["_let_go_of_server_permission"]()
        self.assertFalse(ns["_server_permission_locked"]())
        self.assertIn("SERVER: SHARING GOES ON IN THE BACKGROUND", notices)

    def test_a_finished_set_up_goes_on_only_where_the_viewer_still_is(self):
        state = {"_server_permission": {"state": "yes", "started_ms": 0, "layer": "ADV", "then": lambda: notices.append("OPENED")}, "show_menu": True, "menu_layer": "ADV"}
        ns, notices = self._ns(0, state)
        ns["_server_permission_tick"](100)
        self.assertEqual(notices, ["OPENED"])
        state.update({"_server_permission": {"state": "yes", "started_ms": 0, "layer": "ADV", "then": lambda: notices.append("OPENED")}, "show_menu": False})
        ns["_server_permission_tick"](100)
        self.assertEqual(notices[-1], "SERVER: SHARING IS READY")

    def test_the_upkeep_path_says_it_runs_with_no_box(self):
        import server_files
        src = inspect.getsource(server_files.grant_sharing)
        at = src.index('on_step("working")')
        self.assertLess(at, src.index("done, why = upkeep()"))
        self.assertIn('if name == "working" and _st["state"] == "asking":', get_function_source("_begin_server_permission"))
        self.assertIn("SERVER: COULD NOT SHARE FILES", get_function_source("_share_files_now"))
        self.assertIn('" \\u2014 "', get_function_source("_share_files_now"))


