class TestTheScreenNeverWaitsForFileFactsOrGain(unittest.TestCase):
    """Owner log 2026-11-20: the screen thread waited 16 s for the library inside a channel change while reading a file's facts; facts and gain reads on the screen thread never wait."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, ignore_errors=True)
        self.lib = ml.MediaLibrary(os.path.join(self.tmp, "library.sqlite3"))
        self.addCleanup(self.lib._conn.close)

    def test_facts_and_gain_go_on_while_the_database_is_busy(self):
        taken, release = threading.Event(), threading.Event()

        def hold():
            with self.lib._lock:
                taken.set()
                release.wait(5)
        worker = threading.Thread(target=hold, daemon=True)
        worker.start()
        self.assertTrue(taken.wait(2))
        probe = types.SimpleNamespace(keys=types.SimpleNamespace(resolve=lambda p: None), library=self.lib)
        facts, gain = ml.FileFactsHub(probe), ml.GainHub(probe)
        started = time.perf_counter()
        answer = facts.read("/m/new.mkv")
        gains = gain.read("/m/new.mkv")
        waited = time.perf_counter() - started
        release.set()
        worker.join(2)
        self.assertLess(waited, 0.5)
        self.assertFalse(answer["confirmed_unplayable"])
        self.assertIsNone(gains["gain"])
        self.assertNotIn(ml._hub_key("/m/new.mkv"), facts._memo, "nothing is remembered, so the next ask reads the library")
        self.assertIs(self.lib.path_facts_row("never-seen") , None, "a free database answers as usual")


class TestThePlaybackNeverWaitsBehindTheGuide(unittest.TestCase):
    """Owner log 2026-11-18: the guide's background writes held the library database up to 8 s and the screen thread waited behind them (3.7 s frames); the screen never waits now, the guide writes only what changed in small turns, and a channel's guide is worked out again only after its files get new lengths."""

    def setUp(self):
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, ignore_errors=True)
        self.lib = ml.MediaLibrary(os.path.join(self.tmp, "library.sqlite3"))
        self.addCleanup(self.lib._conn.close)

    def _held_elsewhere(self):
        taken, release = threading.Event(), threading.Event()

        def hold():
            with self.lib._lock:
                taken.set()
                release.wait(5)
        worker = threading.Thread(target=hold, daemon=True)
        worker.start()
        self.assertTrue(taken.wait(2))
        self.addCleanup(release.set)
        return release, worker

    def test_the_screen_thread_reads_the_last_answer_while_the_database_is_busy(self):
        self.lib.upsert_fields("key1", duration=1500.0)
        self.assertEqual(self.lib.get_entry("key1")["duration"], 1500.0)
        release, worker = self._held_elsewhere()
        started = time.perf_counter()
        busy = self.lib.get_entry("key1")
        waited = time.perf_counter() - started
        release.set()
        worker.join(2)
        self.assertLess(waited, 0.5, "the screen thread did not wait for the database")
        self.assertEqual(busy["duration"], 1500.0, "it used the answer it saw last")

    def test_a_length_the_screen_never_saw_is_not_made_up_while_the_database_is_busy(self):
        probe = types.SimpleNamespace(keys=types.SimpleNamespace(resolve=lambda p: None), library=self.lib)
        hub = ml.DurationHub(probe)
        release, worker = self._held_elsewhere()
        started = time.perf_counter()
        answer = hub.read("/m/new file.mkv")
        self.assertLess(time.perf_counter() - started, 0.5)
        release.set()
        worker.join(2)
        self.assertEqual(answer, (None, None), "no length this frame")
        self.assertNotIn(ml._hub_key("/m/new file.mkv"), hub._memo, "nothing is remembered, so the next ask reads the library")
        self.assertIn(ml._hub_key("/m/new file.mkv"), hub._recheck_queue, "the channel-ready thread asks again")

    def test_a_background_thread_still_waits_its_turn(self):
        self.lib.upsert_fields("key2", duration=900.0)
        release, worker = self._held_elsewhere()
        box = {}
        reader = threading.Thread(target=lambda: box.update(entry=self.lib.get_entry("key2")), daemon=True)
        reader.start()
        reader.join(0.3)
        self.assertTrue(reader.is_alive(), "a background read waits for its turn")
        release.set()
        reader.join(2)
        self.assertEqual(box["entry"]["duration"], 900.0)

    def test_the_guide_writes_only_rows_that_changed(self):
        hub = ml.ScheduleHub(self.lib)
        base = 1_800_000_000.0
        rows = [_future_row("a@1", i, "/m/%d.mkv" % i, base + i * 1000, 1000.0) for i in range(450)]
        self.assertEqual(hub.replace_future_rows("05", rows), 450)
        self.assertEqual(hub.replace_future_rows("05", rows), 0, "the same rows again write nothing")
        signature = hub.future_signature("05")
        moved = [dict(r) for r in rows]
        moved[400]["planned_start"] += 5.0
        self.assertEqual(hub.replace_future_rows("05", moved), 1, "only the row that moved is written")
        self.assertNotEqual(hub.future_signature("05"), signature, "the guide can tell its future changed")
        self.assertEqual(hub.replace_future_rows("05", moved[:300]), 0)
        self.assertEqual(len(hub.future_rows_between("05", 0, 4e12)), 300, "rows no longer planned are taken away")
        src = inspect.getsource(ml.ScheduleHub.replace_future_rows)
        self.assertIn("_FUTURE_ROWS_PER_TURN", src, "rows go in turns, the database let go between")
        self.assertNotIn('DELETE FROM hub_future_row WHERE channel = ?", (channel,)', src, "the channel's rows are never all deleted in one go")

    def test_a_new_length_is_remembered_for_the_guide(self):
        probe = types.SimpleNamespace(keys=types.SimpleNamespace(resolve=lambda p: None), library=self.lib)
        hub = ml.DurationHub(probe)
        before = time.monotonic() - 1
        hub.store_estimate("/m/show s01e02.mkv", 1500, "series average")
        changed = hub.lengths_changed_since(before)
        self.assertIn(ml._hub_key("/m/show s01e02.mkv"), changed)
        self.assertEqual(hub.lengths_changed_since(time.monotonic() + 1), {}, "nothing newer than now")

    def test_the_guide_waits_for_the_scans_to_settle(self):
        ns = {"media": types.SimpleNamespace(_duration_hub=None), "time": time, "_HUB_FUTURE_SETTLE_SECONDS": 20.0}
        exec(compile(get_function_source("_hub_future_lengths_due"), "<extracted:due>", "exec"), ns)
        due = ns["_hub_future_lengths_due"]
        info = {"schedules": {"Full Day": [{"path": "/m/a.mkv"}, {"path": "/m/b.mkv"}]}}
        self.assertFalse(due(info, 0.0), "no hub, nothing due")
        now = time.monotonic()
        ns["media"]._duration_hub = types.SimpleNamespace(lengths_changed_since=lambda since: {ml._hub_key("/m/a.mkv"): now - 30})
        self.assertTrue(due(info, 0.0), "a file of the channel got a length and the scans settled")
        ns["media"]._duration_hub = types.SimpleNamespace(lengths_changed_since=lambda since: {ml._hub_key("/m/a.mkv"): now - 2})
        self.assertFalse(due(info, 0.0), "a length that just came in waits for the run of scans to finish")
        ns["media"]._duration_hub = types.SimpleNamespace(lengths_changed_since=lambda since: {ml._hub_key("/m/other.mkv"): now - 30})
        self.assertFalse(due(info, 0.0), "another channel's file is not this channel's business")
        main = read(os.path.join(ROOT, "retro_tv_emulator.py"))
        self.assertNotIn("_HUB_FUTURE_REFRESH_SECONDS", main, "no timer works the guide out again")


class TestAShowLessFileNameJoinsTheShowOfItsFolder(unittest.TestCase):
    """Owner 2026-11-18: a file named only "Episode 4" belongs to the show of its folder: the name its folder mates share (all but one or two), else the folder's own name; it carries no season of its own."""

    def setUp(self):
        self._saved = dict(media._path_folder_index)
        self.addCleanup(self._restore)

    def _restore(self):
        touched = set(media._path_folder_index) | set(self._saved)
        media._path_folder_index.clear()
        media._path_folder_index.update(self._saved)
        for folder in touched:
            media._note_folder_files_changed(folder)

    def _index(self, folder, names):
        media._path_folder_index[folder] = {os.path.join(folder, n) for n in names}
        media._note_folder_files_changed(folder)

    def test_the_folder_name_names_it(self):
        path = os.path.join("v", "Shows", "Some Show", "Episode 4.mkv")
        self.assertEqual(media._flex_series_and_season({"path": path}), ("Some Show", None, 4))
        self.assertEqual(media._flex_series_and_season({"path": os.path.join("v", "Shows", "Some Show", "Season 2", "Episode 1.mkv")}),
                         ("Some Show", 2, 1), "a Season folder gives the season, never season 0")

    def test_the_name_its_folder_mates_share_names_it_and_its_season(self):
        folder = os.path.join("v", "Cartoons")
        self._index(folder, ["Rugrats S01E01.mkv", "Rugrats S01E02.mkv", "Rugrats S01E03.mkv", "Episode 4.mkv"])
        path = os.path.join(folder, "Episode 4.mkv")
        self.assertEqual(media._flex_series_and_season({"path": path}), ("Rugrats", 1, 4))
        self.assertEqual(media._guess_class(path), media._guess_class(os.path.join(folder, "Rugrats S01E02.mkv")),
                         "it guesses its length from the same season")

    def test_folder_mates_that_do_not_agree_name_nothing(self):
        folder = os.path.join("v", "Mixed")
        self._index(folder, ["Rugrats S01E01.mkv", "Cheers S01E02.mkv", "Frasier S01E03.mkv", "Episode 4.mkv"])
        self.assertEqual(media._flex_series_and_season({"path": os.path.join(folder, "Episode 4.mkv")})[0], "Mixed")

    def test_a_stray_season_less_file_guesses_with_its_own_show(self):
        rug = os.path.join("v", "Rugrats")
        doug = os.path.join("v", "Doug")
        self._index(rug, ["Rugrats S01E01.mkv", "Rugrats S01E02.mkv", "Rugrats S01E03.mkv", "Doug Episode 5.mkv"])
        self._index(doug, ["Doug Episode 4.mkv", "Doug Episode 6.mkv", "Doug Episode 7.mkv"])
        stray = media._guess_class(os.path.join(rug, "Doug Episode 5.mkv"))
        self.assertEqual(stray, media._guess_class(os.path.join(doug, "Doug Episode 4.mkv")),
                         "owner 2026-11-18: a Doug episode in a Rugrats folder guesses with the Doug files")
        self.assertEqual(media._episode_series_key({"path": os.path.join(rug, "Doug Episode 5.mkv")}), "doug", "and it airs in the Doug series")

    def test_a_file_with_its_own_show_name_keeps_it(self):
        folder = os.path.join("v", "Cartoons")
        self._index(folder, ["Rugrats S01E01.mkv", "Rugrats S01E02.mkv", "Rugrats S01E03.mkv"])
        self.assertEqual(media._flex_series_and_season({"path": os.path.join(folder, "Doug S02E05.mkv")})[:2], ("Doug", 2))
        self.assertEqual(media._flex_series_and_season({"path": os.path.join(folder, "Doug Episode 5.mkv")})[0], "Doug")


class TestTheGpuUploadNeverLeavesThePictureLocked(unittest.TestCase):
    """Owner log 2026-11-18: the virtual screen was found locked on Static with no running function holding it; the GPU upload reads the screen through its own lock and pixel address, so no pixel array can outlive the upload."""

    def _upload(self):
        import ast as _ast
        import pygame
        src = open(os.path.join(SCRIPTS, "GPU", "d3d11_gpu_frame.py"), encoding="utf-8").read()
        node = next(n for n in _ast.walk(_ast.parse(src)) if isinstance(n, _ast.FunctionDef) and n.name == "_upload_surface")
        calls = []

        class GPUFrameError(Exception):
            pass

        def fake_call(context, index, restype, argtypes, *args):
            calls.append((args, seen_locked[0]()))
        seen_locked = [lambda: None]
        ns = {"pygame": pygame, "call": fake_call, "GPUFrameError": GPUFrameError, "VOIDP": object, "UINT": object,
              "CTX_UpdateSubresource": 48}
        exec(compile(_ast.Module(body=[node], type_ignores=[]), "d3d11_gpu_frame.py", "exec"), ns)
        return ns["_upload_surface"], calls, seen_locked, GPUFrameError

    def test_the_upload_passes_the_pixels_and_unlocks(self):
        import pygame
        upload, calls, seen_locked, _err = self._upload()
        picture = pygame.Surface((40, 30), 0, 32)
        seen_locked[0] = picture.get_locked

        class Pipe:
            _context = "ctx"
        upload(Pipe(), "tex", picture)
        self.assertEqual(len(calls), 1)
        args, locked_during = calls[0]
        self.assertEqual(args[3], picture._pixels_address, "D3D reads the screen's own pixel memory")
        self.assertEqual(args[4], picture.get_pitch(), "with the screen's own row length")
        self.assertTrue(locked_during, "the screen is locked while D3D copies it")
        self.assertFalse(picture.get_locked(), "and unlocked the moment the copy is done")
        self.assertEqual(picture.get_locks(), (), "no pixel array is left holding it")

    def test_a_failed_upload_still_unlocks(self):
        import pygame
        upload, calls, seen_locked, err = self._upload()
        picture = pygame.Surface((40, 30), 0, 32)

        def boom():
            raise RuntimeError("device lost")
        seen_locked[0] = boom

        class Pipe:
            _context = "ctx"
        with self.assertRaises(RuntimeError):
            upload(Pipe(), "tex", picture)
        self.assertFalse(picture.get_locked(), "a failed copy never leaves the screen locked")
        with self.assertRaises(err):
            upload(Pipe(), "tex", pygame.Surface((8, 8), 0, 24))

    def test_no_pixel_array_in_the_upload(self):
        src = open(os.path.join(SCRIPTS, "GPU", "d3d11_gpu_frame.py"), encoding="utf-8").read()
        body = src[src.index("def _upload_surface"):src.index("def _update_constants")]
        self.assertNotIn("surfarray", body)
        self.assertIn("surface.unlock()", body)


class TestTheScreenThreadDoesNotRunTheSchedulerEveryFrame(unittest.TestCase):
    """Owner log 2026-11-18 13:57: with the hub holding nothing for a channel whose first file was still being measured, the screen thread ran the scheduler over all its new files every frame; now it asks itself only the first time and a background thread asks again every SCREEN_SCHEDULER_ASK_GAP_S."""

    def _ns(self, answers):
        calls = []
        clock = [100.0]

        class Hub:
            def show_facts(self, key, epoch, guard):
                return None

            def remember_show_facts(self, *a, **k):
                pass

            def forget_show_facts(self, key):
                pass
        fake_ml = types.ModuleType("media_library")
        fake_ml.shared_schedule_hub = lambda: Hub()

        def scheduler(ch, *a):
            calls.append((threading.current_thread() is threading.main_thread(), ch))
            return answers[min(len(calls) - 1, len(answers) - 1)]
        ns = {"app_state": {}, "_prime_context": threading.local(), "broadcast_clock": types.SimpleNamespace(now=lambda: types.SimpleNamespace(timestamp=lambda: 1.0)),
              "_hub_playback_guard": lambda key: None, "_hub_miss_log_once": lambda key: None, "_log_warn_throttled": lambda *a: None,
              "_scheduler_playback_state": scheduler, "threading": threading, "time": types.SimpleNamespace(monotonic=lambda: clock[0]),
              "SCREEN_SCHEDULER_ASK_GAP_S": 0.5, "_screen_scheduler_answers": {}, "_log_swallowed": lambda *a: None,
              "SCHEDULE_PENDING_REASON": "schedule_pending", "_app_shutting_down": threading.Event(),
              "_screen_ask": {"wanted": {}, "thread": None, "wake": threading.Event()}, "_scheduler_prepared": {}}
        self.addCleanup(ns["_app_shutting_down"].set)
        for name in ("calculate_slotted_playback_state", "_screen_scheduler_answer", "_hub_remember_state", "_schedule_pending_state",
                     "_ask_scheduler_for_screen", "_screen_ask_loop"):
            exec(get_function_source(name), ns)
        exec(STATION_DOOR_SRC, ns)
        return ns, calls, clock, fake_ml

    def _wait_calls(self, calls, count):
        deadline = time.monotonic() + 3
        while len(calls) < count and time.monotonic() < deadline:
            time.sleep(0.01)

    def test_a_static_answer_is_reused_and_asked_again_off_the_screen_thread(self):
        static = {"mode": "Static", "file": "", "seek": 0, "reason": "first_file_scanning"}
        show = {"mode": "Video", "file": "a.mkv", "seek": 1.0, "duration": 100.0}
        ns, calls, clock, fake_ml = self._ns([static, show])
        with patch.dict(sys.modules, {"media_library": fake_ml}):
            f = ns["calculate_slotted_playback_state"]
            self.assertEqual(f("05")["reason"], "schedule_pending", "the first frame draws the channel-change cover while the schedule is asked")
            self._wait_calls(calls, 1)
            deadline = time.monotonic() + 3
            while "05" not in ns["_screen_scheduler_answers"] and time.monotonic() < deadline:
                time.sleep(0.01)
            for _ in range(20):
                self.assertEqual(f("05"), static)
            self.assertEqual(calls, [(False, "05")], "the screen thread never asked the scheduler itself")
            clock[0] += 0.6
            f("05")
            self._wait_calls(calls, 2)
            self.assertEqual(calls[1], (False, "05"), "the next ask runs on a background thread")
            deadline = time.monotonic() + 3
            while ns["_screen_scheduler_answers"]["05"]["state"] != show and time.monotonic() < deadline:
                time.sleep(0.01)
            self.assertEqual(ns["_screen_scheduler_answers"]["05"]["state"], show)

    def test_other_threads_still_ask_the_scheduler_themselves(self):
        static = {"mode": "Static", "file": "", "seek": 0, "reason": "first_file_scanning"}
        ns, calls, clock, fake_ml = self._ns([static])
        out = []
        with patch.dict(sys.modules, {"media_library": fake_ml}):
            for _ in range(3):
                t = threading.Thread(target=lambda: out.append(ns["calculate_slotted_playback_state"]("05")))
                t.start(); t.join()
        self.assertEqual(len(calls), 3)


class TestAnOutOfDateHeldAnswerIsNeverAired(unittest.TestCase):
    """Owner log 2026-11-23 02:41: in every break a file that aired 16 minutes before was reopened for a moment."""

    def test_a_held_answer_whose_item_ran_out_draws_the_cover_and_is_asked_again(self):
        asked = []
        ns = {"time": types.SimpleNamespace(monotonic=lambda: 10.0), "SCREEN_SCHEDULER_ASK_GAP_S": 0.5, "SCHEDULE_PENDING_REASON": "schedule_pending",
              "_screen_scheduler_answers": {"05": {"state": {"mode": "Commercial", "file": "alpha.mp4", "seek": 4.0, "duration": 300.0, "seek_slot_offset": 0},
                                                   "at": 9.9, "epoch": 1000.0}},
              "_ask_scheduler_for_screen": lambda ch, hub: asked.append(ch)}
        for name in ("_screen_scheduler_answer", "_schedule_pending_state"):
            exec(get_function_source(name), ns)
        self.assertEqual(ns["_screen_scheduler_answer"]("05", None, 1100.0)["seek"], 104.0)
        self.assertEqual(asked, [])
        late = ns["_screen_scheduler_answer"]("05", None, 2004.0)
        self.assertEqual(late["reason"], "schedule_pending", "never the file that aired long before")
        self.assertEqual(asked, ["05"])

    def test_the_hub_has_no_gap_between_two_items(self):
        hub = ml.ScheduleHub.__new__(ml.ScheduleHub)
        hub._show_facts, hub._upcoming = {}, {}
        ad = {"mode": "Commercial", "file": "ad8.mp4", "seek": 0.0, "duration": 30.0, "block": "Morning", "seek_slot_offset": 0, "interior_cut": False}
        hub.remember_show_facts("05", ad, 1000.0, "g", upcoming=[(1000.0, ad), (1030.0, dict(ad, file="ad5.mp4", duration=15.0))])
        for at in (1028.99, 1029.5, 1029.97, 1029.999):
            self.assertEqual(hub.show_facts("05", at, "g")["file"], "ad8.mp4", at)
        self.assertEqual(hub.show_facts("05", 1030.0, "g")["file"], "ad5.mp4")


