class TestScanCapacityTest(unittest.TestCase):
    """The first-run scan capacity test finds how many scans stop getting faster, remembers it, and only ever lowers a governor lane."""

    def test_best_is_where_more_scans_stop_helping(self):
        import scan_capacity as sc
        steps = [{"workers": 1, "rate": 100.0, "cpu": 20.0}, {"workers": 2, "rate": 190.0, "cpu": 45.0},
                 {"workers": 3, "rate": 260.0, "cpu": 70.0}, {"workers": 4, "rate": 270.0, "cpu": 90.0}]
        self.assertEqual(sc.choose_best(steps, 0.15, 97.0)[0], 3)
        steps[2]["cpu"] = 98.0
        self.assertEqual(sc.choose_best(steps[:3] + [{"workers": 4, "rate": 400.0, "cpu": 99.0}], 0.15, 97.0)[0], 3)
        self.assertEqual(sc.choose_best([], 0.15, 97.0), (1, 0.0, 0.0))

    def test_measure_times_each_step_and_stops_when_told(self):
        import scan_capacity as sc
        now = [0.0]

        class _Proc:
            def __init__(self, ends): self.ends = ends; self.returncode = None
            def poll(self):
                if now[0] >= self.ends:
                    self.returncode = 0
                    return 0
                return None
            def kill(self): self.returncode = -9

        def clock(): return now[0]
        calls = []

        def spawn(kind, n):
            calls.append(n)
            return [_Proc(now[0] + 2.0 * (1 if n <= 2 else n / 2.0)) for _ in range(n)]

        real_sleep = time.sleep
        sc.time.sleep = lambda s: now.__setitem__(0, now[0] + 0.5)
        try:
            steps = sc.measure("audio", spawn, lambda: 50.0, 4, 100, lambda: False, 30.0, clock=clock)
            stopped = sc.measure("audio", spawn, lambda: 50.0, 4, 100, lambda: True, 30.0, clock=clock)
        finally:
            sc.time.sleep = real_sleep
        self.assertEqual([st["workers"] for st in steps], [1, 2, 3, 4])
        self.assertGreater(steps[1]["rate"], steps[0]["rate"])
        self.assertEqual(stopped, [])

    def test_one_spike_on_a_single_scan_does_not_make_the_processor_look_full(self):
        import scan_capacity as sc
        now = [0.0]
        readings = iter([20.0, 99.0, 25.0, 22.0, 24.0, 21.0, 23.0, 20.0, 20.0, 20.0, 20.0, 20.0])

        class _Proc:
            returncode = None
            def poll(self):
                if now[0] >= 0.8:
                    self.returncode = 0
                    return 0
                return None

        real_sleep = time.sleep
        sc.time.sleep = lambda s: now.__setitem__(0, now[0] + 0.1)
        try:
            steps = sc.measure("audio", lambda kind, n: [_Proc() for _ in range(n)], lambda: next(readings, 20.0), 1, 100, lambda: False, 30.0, clock=lambda: now[0])
        finally:
            sc.time.sleep = real_sleep
        self.assertLess(steps[0]["cpu"], 30.0)
        self.assertEqual(sc.choose_best(steps + [{"workers": 2, "rate": steps[0]["rate"] * 2.5, "cpu": 40.0}], 0.15, 97.0)[0], 2)

    def test_a_result_made_the_older_way_is_ignored_and_measured_again(self):
        import scan_capacity as sc
        d = tempfile.mkdtemp()
        path = os.path.join(d, "c.json")
        with open(path, "w", encoding="utf-8") as fh:
            fh.write('{"audio": {"workers": 1, "rate": 650.0, "cpu": 97.2, "measured_at": 1.0}}')
        store = sc.CapacityStore(path)
        self.assertEqual(store.workers(), {})
        self.assertTrue(store.never_measured("audio"))
        store.note("audio", 3, 2200.0, 90.0)
        self.assertEqual(sc.CapacityStore(path).workers(), {"audio": 3})

    def test_the_table_is_remembered_and_goes_stale(self):
        import scan_capacity as sc
        d = tempfile.mkdtemp()
        now = [100.0]
        store = sc.CapacityStore(os.path.join(d, "c.json"), clock=lambda: now[0])
        self.assertTrue(store.due("audio", 1000))
        store.note("audio", 3, 250.0, 88.0)
        self.assertFalse(store.due("audio", 1000))
        now[0] += 2000
        self.assertTrue(store.due("audio", 1000))
        self.assertEqual(sc.CapacityStore(os.path.join(d, "c.json")).workers(), {"audio": 3})

    def test_a_measured_capacity_only_lowers_a_lane(self):
        import importlib
        gov = importlib.import_module("performance_governor")
        before = gov.lane_ceiling("loudness_and_bake", "performance")
        try:
            gov.set_measured_capacity({"audio": before + 5})
            self.assertEqual(gov.lane_ceiling("loudness_and_bake", "performance"), before)
            gov.set_measured_capacity({"audio": 1})
            self.assertEqual(gov.lane_ceiling("loudness_and_bake", "performance"), 1)
            gov.set_measured_capacity({"video": 1})
            self.assertEqual(gov.lane_ceiling("loudness_and_bake", "performance"), before)
        finally:
            gov.set_measured_capacity({})

    def test_the_test_is_wired_and_never_runs_on_a_busy_pc(self):
        self.assertIn('name="ScanCapacity"', MAIN_SRC)
        loop = get_function_source("_scan_capacity_loop")
        self.assertIn("performance_governor.pc_is_quiet()", loop)
        self.assertIn("set_measured_capacity(store.workers())", loop)
        self.assertIn("_warm_loops_should_rest()", get_function_source("_run_scan_capacity_test_locked"))
        self.assertIn("BELOW_NORMAL_PRIORITY_CLASS", get_function_source("_spawn_capacity_scans"))


class TestCapacityTestIsTheLastStageOfTheFirstLoadingBar(unittest.TestCase):
    """On a first start the loading bar ends with the capacity test: the real load fills the first fifth, the test the rest, done at the test's end; a test still going at 120 seconds is stuck and is stopped (owner 2026-11-24: it stays in the boot load, never after a channel loads)."""

    def _ns(self, state, steps_done=0, steps_total=10):
        fn = get_function_source("_boot_capacity_credit")
        ns = {"app_state": state, "_scan_capacity_progress": {"steps_done": steps_done, "steps_total": steps_total},
              "_boot_bar_const": lambda name, fallback: fallback}
        exec(fn, ns)
        return ns["_boot_capacity_credit"]

    def test_nothing_is_credited_before_the_stage_starts_and_all_of_it_when_done(self):
        unit = {"w": 70.0, "start": None, "done": False}
        credit = self._ns({"_boot_capacity": unit})
        self.assertEqual(credit(100.0), (70.0, 0.0))
        unit["done"] = True
        self.assertEqual(credit(100.0), (70.0, 70.0))
        self.assertEqual(self._ns({})(100.0), (0.0, 0.0))

    def test_the_bar_follows_the_larger_of_the_time_used_and_the_steps_done(self):
        unit = {"w": 80.0, "start": 100.0, "done": False}
        by_time = self._ns({"_boot_capacity": unit}, steps_done=1, steps_total=10)
        self.assertAlmostEqual(by_time(160.0)[1], 40.0)
        by_steps = self._ns({"_boot_capacity": unit}, steps_done=9, steps_total=10)
        self.assertAlmostEqual(by_steps(102.0)[1], 72.0)
        self.assertAlmostEqual(by_time(240.0)[1], 80.0)

    def test_the_real_load_is_the_first_fifth_of_the_bar(self):
        src = get_function_source("_boot_capacity_plan")
        self.assertIn("share / (1.0 - share)", src)
        self.assertEqual(gov.BOOT_CAPACITY_BAR_SHARE, 0.8)
        self.assertEqual(gov.BOOT_CAPACITY_MAX_SECONDS, 120.0)

    def test_every_due_test_is_planned_for_the_loading_screen_the_caption_test_only_with_captions_on(self):
        """Owner logs 2026-11-24: beside a channel with live captions on the PC is never quiet, so the caption speed test waited for ever; every due test now runs on the loading screen."""
        plan = get_function_source("_boot_capacity_plan")
        self.assertIn("kinds = _boot_capacity_kinds(store)", plan)
        self.assertIn('"kinds": kinds', plan)
        import scan_capacity as sc
        tmp0 = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp0, True)
        st = sc.CapacityStore(os.path.join(tmp0, "c.json"))
        captions_on = [True]
        ns = {"_boot_bar_const": lambda name, default: default, "_captions_switched_on": lambda: captions_on[0],
              "performance_governor": types.SimpleNamespace(caption_memory_locked=lambda: False)}
        exec(get_function_source("_boot_capacity_kinds"), ns)
        kinds = ns["_boot_capacity_kinds"]
        self.assertEqual(kinds(st), ["captions", "audio", "video"])
        captions_on[0] = False
        self.assertEqual(kinds(st), ["audio", "video"])
        st.note("audio", 2, 50.0, 80.0)
        st.note("video", 2, 50.0, 80.0)
        self.assertEqual(kinds(st), [])
        captions_on[0] = True
        self.assertEqual(kinds(st), ["captions"])
        st.note("captions", 0, 1.2, 0.0)
        self.assertEqual(kinds(st), [])
        run = get_function_source("_boot_capacity_run")
        self.assertIn('kinds = list(unit.get("kinds", ()))', run)
        self.assertIn('_run_caption_speed_test(store, lambda: _app_shutting_down.is_set() or app_state.get("_boot_capacity_stop", False))', run)
        for name in ("_caption_speed_loop", "_scan_capacity_loop"):
            self.assertIn('while app_state.get("_boot_capacity") and not app_state["_boot_capacity"].get("done"):', get_function_source(name), name)
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp, True)
        store = sc.CapacityStore(os.path.join(tmp, "c.json"))
        self.assertTrue(store.never_measured("audio"))
        store.note("audio", 3, 50.0, 80.0)
        self.assertFalse(store.never_measured("audio"))
        self.assertTrue(store.never_measured("video"))

    def test_the_stage_runs_last_ends_at_the_limit_and_the_bar_counts_it(self):
        self.assertLess(MAIN_SRC.index("_boot_capacity_run()\n        except"), MAIN_SRC.index('_mark_boot_step("boot_prewarm")\n        _start_airing_warm'))
        run = get_function_source("_boot_capacity_run")
        self.assertIn("worker.join(timeout=limit_s)", run)
        self.assertNotIn("finishes beside the channel", run)
        self.assertIn('app_state["_boot_capacity_stop"] = True', run)
        self.assertLess(run.index('app_state["_boot_capacity_stop"] = True'), run.index('app_state["_boot_capacity_phase"] = False'))
        self.assertIn('app_state.get("_boot_capacity_stop", False)', get_function_source("_run_scan_capacity_test_locked"))
        self.assertIn("and not store.never_measured(k)]", get_function_source("_scan_capacity_loop"))
        self.assertIn("_boot_capacity_credit(now)", get_function_source("_boot_bar_target_percent"))

    def test_the_test_waits_for_the_media_engine_and_decks_before_it_starts(self):
        run = get_function_source("_boot_capacity_run")
        self.assertIn("set(_BOOT_BAR_QUICK_STEPS) <= set(app_state.get(\"_boot_steps_done\", set()))", run)
        self.assertLess(run.index("_wait_limit"), run.index("unit[\"start\"] = time.time()"))
        self.assertEqual(gov.BOOT_CAPACITY_WAIT_FOR_BOOT_SECONDS, 20.0)

    def test_the_boot_stage_is_not_stopped_by_the_busy_pc_check_but_later_runs_are(self):
        self.assertIn('not app_state.get("_boot_capacity_phase") and _warm_loops_should_rest()', get_function_source("_run_scan_capacity_test_locked"))

    def test_two_capacity_tests_never_run_together_and_every_decision_is_logged(self):
        body = get_function_source("_run_scan_capacity_test")
        self.assertIn("_scan_capacity_running[0]", body)
        self.assertNotIn("Lock()", get_function_source("_run_scan_capacity_test"))
        loop = get_function_source("_scan_capacity_loop")
        for text in ("[SCAN CAPACITY] watching", "due but waiting", "nothing is due to be measured"):
            self.assertIn(text, loop)

    def test_measure_reports_each_finished_step(self):
        import scan_capacity as sc
        seen = []
        class Proc:
            returncode = 0
            def poll(self): return 0
        steps = sc.measure("audio", lambda kind, n: [Proc() for _ in range(n)], lambda: 10.0, 3, 10, lambda: False, 5.0,
                           clock=iter([0.0, 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0, 5.0]).__next__, on_step=lambda k, w, n: seen.append((k, w, n)))
        self.assertEqual(seen, [("audio", 1, 1), ("audio", 2, 2), ("audio", 3, 3)])
        self.assertEqual(len(steps), 3)


