class TestSharedFileChecklist(unittest.TestCase):
    """The one checklist (file_profile) of what a file needs before it counts as fully scanned, and the burned-in item of it in the main app."""

    def _fp(self):
        import file_profile
        return file_profile

    def _entry(self, **extra):
        entry = {"header_probed_at": 1.0, "duration": 1300.0, "picture_box": {"rect": [0, 0, 1, 1]},
                 "picture_box_detector_version": 9, "gain": 1.0, "gain_scan_version": 3, "subtitle_streams": []}
        entry.update(extra)
        return entry

    def _missing(self, entry, **kwargs):
        args = dict(is_audio=False, box_version=9, gain_version=3, burned_verdict=False)
        args.update(kwargs)
        return self._fp().missing(entry, **args)

    def test_a_file_with_everything_has_nothing_missing(self):
        self.assertEqual(self._missing(self._entry()), [])

    def test_a_file_without_a_header_lacks_only_the_header_first(self):
        self.assertEqual(self._missing({}), ["header"])
        self.assertEqual(self._missing(self._entry(duration=0)), ["header"])

    def test_each_item_is_reported_in_reading_order(self):
        entry = self._entry(picture_box=None, gain=None)
        self.assertEqual(self._missing(entry, burned_verdict=None), ["box", "gain", "burned"])

    def test_an_older_detector_or_loudness_version_counts_as_missing(self):
        self.assertEqual(self._missing(self._entry(picture_box_detector_version=8)), ["box"])
        self.assertEqual(self._missing(self._entry(gain_scan_version=2)), ["gain"])
        self.assertEqual(self._missing(self._entry(gain_scan_version=0)), [])

    def test_a_song_needs_no_picture_box_and_no_burned_in_check(self):
        entry = self._entry(picture_box=None)
        self.assertEqual(self._missing(entry, is_audio=True, burned_verdict=None), [])

    def test_a_file_with_caption_text_of_its_own_is_never_searched_for_burned_in(self):
        text = self._entry(subtitle_streams=[{"index": 2, "lang": "eng", "codec": "subrip", "is_text": True}])
        self.assertEqual(self._missing(text, burned_verdict=None), [])
        image = self._entry(subtitle_streams=[{"index": 2, "lang": "eng", "codec": "hdmv_pgs_subtitle", "is_text": False}])
        self.assertEqual(self._missing(image, burned_verdict=None), ["burned"])
        self.assertEqual(self._missing(self._entry(), burned_verdict=None, sidecar_found=True), [])

    def test_burned_in_can_be_left_off_the_list(self):
        self.assertEqual(self._missing(self._entry(), burned_verdict=None, want_burned=False), [])

    def test_the_server_scanner_asks_the_shared_checklist(self):
        src = open(os.path.join(SCRIPTS, "server", "server_scanner.py"), encoding="utf-8").read()
        self.assertIn("file_profile.missing(", src)
        self.assertNotIn('need.append("box")', src)

    def test_the_main_app_bar_and_lane_include_the_burned_in_item(self):
        for name in ("_scan_file_is_done", "_scan_file_is_finished"):
            self.assertIn("_scan_burned_in_reported(", get_function_source(name))
        lane = get_function_source("_picture_box_scan_worker")
        self.assertIn("_pipeline_stage_burned_in(_norm_p)", lane)
        self.assertIn("_scan_burned_in_reported(_norm_p, [0])", lane)

    def _burned_ns(self, captions_on=True, entry=None, verdict=None, owned=False, sidecar=False, video="/m/a.mkv"):
        scans = []

        class _Lib:
            def get_cached(self, path):
                return entry
            def get_burned_in_verdict(self, path):
                return verdict
            def detect_burned_in_if_needed(self, path):
                scans.append(path)
                return False

        ns = {"os": os, "file_profile": self._fp(), "_scan_burned_in_done": set(), "db": object(),
              "media": types.SimpleNamespace(VIDEO_DISPLAY_EXTS=(".mkv", ".mp4"), _find_sidecar_caption_file=lambda p: sidecar),
              "_setting_on": lambda key: captions_on, "_get_probe_library": lambda: _Lib(),
              "_log_swallowed": lambda where, error: None,
              "server_remote_files": types.SimpleNamespace(server_owns=lambda p: owned)}
        src = MAIN_SRC
        i = src.index("def _scan_burned_in_wanted")
        j = src.index("def _scan_file_is_done")
        ns["__builtins__"] = __builtins__
        import sys as _sys
        _had = _sys.modules.get("server_remote_files")
        self.addCleanup(lambda: _sys.modules.__setitem__("server_remote_files", _had) if _had is not None else _sys.modules.pop("server_remote_files", None))
        _sys.modules["server_remote_files"] = ns["server_remote_files"]
        exec(compile(src[i:j], "<extracted>", "exec"), ns)
        return ns, scans

    def test_nothing_is_scanned_for_burned_in_while_captions_are_off(self):
        ns, scans = self._burned_ns(captions_on=False, entry={})
        self.assertTrue(ns["_scan_burned_in_reported"]("/m/a.mkv", [1]))
        self.assertTrue(ns["_pipeline_stage_burned_in"]("/m/a.mkv"))
        self.assertEqual(scans, [])

    def test_a_video_without_a_verdict_is_scanned_once_and_then_reported(self):
        ns, scans = self._burned_ns(entry={})
        self.assertFalse(ns["_scan_burned_in_reported"]("/m/a.mkv", [1]))
        self.assertFalse(ns["_scan_burned_in_reported"]("/m/a.mkv", [0]))
        ns["_scan_burned_in_missing"] = lambda p: bool(scans == [])
        self.assertTrue(ns["_pipeline_stage_burned_in"]("/m/a.mkv"))
        self.assertEqual(scans, ["/m/a.mkv"])
        self.assertTrue(ns["_scan_burned_in_reported"]("/m/a.mkv", [0]))

    def test_a_stored_verdict_a_caption_file_and_a_server_file_need_no_scan(self):
        for kwargs in ({"verdict": True}, {"sidecar": True}, {"owned": True}):
            ns, scans = self._burned_ns(entry={}, **kwargs)
            self.assertTrue(ns["_scan_burned_in_reported"]("/m/a.mkv", [1]), kwargs)
            self.assertEqual(scans, [])

    def test_a_song_is_never_scanned_for_burned_in(self):
        ns, scans = self._burned_ns(entry={})
        self.assertTrue(ns["_scan_burned_in_reported"]("/m/s.mp3", [0]))
        self.assertEqual(scans, [])


class TestHubRowsStayWithTheirSetup(unittest.TestCase):
    """Regular, Server and User rows for the same channel number never mix in the hub, while Regular rows keep the keys they always had."""

    def setUp(self):
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp, True)
        self.hub = ml.ScheduleHub(ml.MediaLibrary(os.path.join(tmp, "library.sqlite3")))
        self.setup = [""]
        ml.set_schedule_scope(lambda: self.setup[0])
        self.addCleanup(ml.set_schedule_scope, None)

    def _rows(self, name):
        return [{"position": 0, "path": "/m/%s.mkv" % name, "kind": "episode", "pass_no": 1,
                 "planned_start": 1000.0, "used_length": 1500.0, "length_source": "measured"}]

    def test_channel_05_of_each_setup_keeps_its_own_show(self):
        self.hub.put_rows("05", "Morning", self._rows("regular"))
        self.setup[0] = "profile:2:"
        self.assertIsNone(self.hub.at("05", 1100.0))
        self.hub.put_rows("05", "Morning", self._rows("server"))
        self.assertEqual(self.hub.at("05", 1100.0)["path"], "/m/server.mkv")
        self.setup[0] = ""
        self.assertEqual(self.hub.at("05", 1100.0)["path"], "/m/regular.mkv")

    def test_a_regular_row_is_still_filed_under_the_plain_channel_number(self):
        self.hub.put_rows("05", "Morning", self._rows("regular"))
        found = self.hub.library._conn.execute("SELECT channel FROM hub_schedule_row").fetchall()
        self.assertEqual([r[0] for r in found], ["05"])

    def test_the_server_reads_one_slots_rows_whatever_this_program_is_showing(self):
        import server_clock
        self.setup[0] = "profile:2:"
        self.hub.put_rows("05", "Morning", self._rows("server"))
        self.setup[0] = ""
        self.hub.put_rows("05", "Morning", self._rows("regular"))
        clocks = server_clock.ChannelClocks(now_fn=lambda: 1100.0)
        self.assertEqual(clocks.snapshot(self.hub, ["05"], slot_id="2")["05"]["now"]["file"], "/m/server.mkv")
        self.assertEqual(clocks.snapshot(self.hub, ["05"])["05"]["now"]["file"], "/m/regular.mkv")
        self.assertEqual(clocks.snapshot(self.hub, ["05"], slot_id="9"), {})

    def test_returned_rows_name_the_plain_channel(self):
        self.setup[0] = "user:pc:3:"
        self.hub.put_rows("05", "Morning", self._rows("user"))
        self.assertEqual(self.hub.rows("05")[0]["channel"], "05")


class TestServerChannelClocks(unittest.TestCase):
    """The server's clock for every channel: the show on air counts down from its full length, the next shows follow, and the scanner reads those files first."""

    def _hub(self, rows_by_channel, sets=None):
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp, True)
        lib = ml.MediaLibrary(os.path.join(tmp, "library.sqlite3"))
        hub = ml.ScheduleHub(lib)
        for channel, rows in rows_by_channel.items():
            hub.put_rows(channel, "Morning", rows)
        return hub

    def _rows(self, count, start=1000.0, length=1500.0, gap=0.0, prefix="e"):
        return [{"position": i, "path": "/m/%s%d.mkv" % (prefix, i), "kind": "episode", "pass_no": 1,
                 "planned_start": start + i * (length + gap), "used_length": length, "length_source": "measured"} for i in range(count)]

    def test_the_show_on_air_counts_down_from_its_full_length_and_the_next_two_follow(self):
        import server_clock
        hub = self._hub({"05": self._rows(5)})
        clock = server_clock.build_clock(hub, "05", 1000.0)
        self.assertEqual(clock["now"]["file"], "/m/e0.mkv")
        self.assertEqual(clock["now"]["remaining"], 1500.0)
        self.assertEqual([s["file"] for s in clock["next"]], ["/m/e1.mkv", "/m/e2.mkv"])
        self.assertEqual(clock["next"][0]["starts_in"], 1500.0)
        later = server_clock.build_clock(hub, "05", 1000.0 + 600.0)
        self.assertEqual(later["now"]["remaining"], 900.0)
        rolled = server_clock.build_clock(hub, "05", 1000.0 + 1500.0)
        self.assertEqual(rolled["now"]["file"], "/m/e1.mkv")
        self.assertEqual(rolled["now"]["remaining"], 1500.0)

    def test_a_channel_with_nothing_on_air_has_no_clock(self):
        import server_clock
        hub = self._hub({"05": self._rows(2)})
        self.assertIsNone(server_clock.build_clock(hub, "05", 99999.0))
        self.assertIsNone(server_clock.build_clock(hub, "09", 1000.0))

    def test_a_show_the_hub_has_already_aired_is_not_listed_as_next(self):
        import server_clock
        hub = self._hub({"05": self._rows(4)})
        self.assertTrue(hub.mark("05", "Morning", 1, "aired"))
        clock = server_clock.build_clock(hub, "05", 1000.0)
        self.assertEqual([s["file"] for s in clock["next"]], ["/m/e2.mkv", "/m/e3.mkv"])

    def test_the_files_come_in_the_order_they_are_needed_with_watched_channels_first(self):
        import server_clock
        hub = self._hub({"05": self._rows(4, prefix="a"), "06": self._rows(4, prefix="b")})
        clocks = server_clock.ChannelClocks(now_fn=lambda: 1000.0)
        found = clocks.files_in_order(hub, ["05", "06"], watched=["06"])
        self.assertEqual([p for _c, _r, p in found][:2], ["/m/b0.mkv", "/m/a0.mkv"])
        self.assertEqual([r for _c, r, _p in found], [0, 0, 1, 1, 2, 2])
        self.assertEqual(len({p for _c, _r, p in found}), 6)

    def test_the_scanner_reads_the_clock_files_before_the_lineup_order(self):
        src = open(os.path.join(SCRIPTS, "server", "server_scanner.py"), encoding="utf-8").read()
        self.assertIn("self._clock_files(probe, channels, watched, slot_id)", src)
        self.assertLess(src.index("self._clock_files(probe, channels, watched, slot_id)"), src.index("for item in items:\n            if item[5] not in seen:"))
        service = open(os.path.join(SCRIPTS, "server", "server_service.py"), encoding="utf-8").read()
        self.assertIn("clocks=_channel_clocks,", service)
        self.assertIn("_channel_clocks = server_clock.ChannelClocks(keep_s=server_clock.KEEP_S,", service)

    def test_a_scanner_without_clocks_reads_nothing_from_them(self):
        import server_scanner
        scanner = server_scanner.FactsScanner(lambda: {}, lambda: False, lambda: None)
        self.assertEqual(scanner._clock_files(None, {"05": {}}, ()), [])

    def test_the_number_of_next_shows_is_in_the_governor(self):
        self.assertEqual(gov.SERVER_CLOCK_NEXT_SHOWS, 2)


class TestHubToUserTransfer(unittest.TestCase):
    """The server's hub reaches each User's own hub: the whole file list once, then only what changed, with the channel clocks beside it, and a User whose list does not match the server's asks for it again."""

    _port = TestAnyComputerOnTheNetworkMayWatch._port
    _slot = TestAnyComputerOnTheNetworkMayWatch._slot
    _wait = TestAnyComputerOnTheNetworkMayWatch._wait

    def _entry(self, name, gain=None):
        entry = {"p": "D:\\m\\%s.mkv" % name, "s": "D", "r": "m\\%s.mkv" % name, "size": 10, "mtime": 1.0, "key": "k" + name}
        entry["f"] = {"duration": 1300.0} if gain is None else {"duration": 1300.0, "gain": gain}
        return entry

    def _run(self, tmp, files, clocks=None, slot_name="a"):
        import server_sync
        self.addCleanup(setattr, server_sync, "SERVER_FILES_REFRESH_S", server_sync.SERVER_FILES_REFRESH_S)
        self.addCleanup(setattr, server_sync, "SERVER_CLOCKS_REFRESH_S", server_sync.SERVER_CLOCKS_REFRESH_S)
        server_sync.SERVER_FILES_REFRESH_S = 0.05
        server_sync.SERVER_CLOCKS_REFRESH_S = 0.05
        slot, port = self._slot(tmp, slot_name), self._port()
        got_files, got_clocks = [], []
        b = server_sync.ScheduleBroadcaster(lambda: {slot_name: slot}, host="127.0.0.1", port=port, poll_interval=0.05,
                                            files_provider=lambda channels: list(files), clock_provider=(lambda channels, slot_id=None: clocks) if clocks is not None else None)
        c = server_sync.ScheduleClient("127.0.0.1", port=port, slot_id=slot_name, timeout=1.0,
                                       on_files=got_files.append, on_clocks=got_clocks.append)
        b.start(); c.start()
        self.addCleanup(b.stop); self.addCleanup(c.stop)
        return b, c, got_files, got_clocks

    def test_the_first_list_is_whole_and_a_change_sends_only_what_changed(self):
        with tempfile.TemporaryDirectory() as tmp:
            files = [self._entry("a"), self._entry("b"), self._entry("c")]
            b, c, got, _clocks = self._run(tmp, files)
            self.assertTrue(self._wait(lambda: got))
            self.assertEqual([e["p"] for e in got[0]["files"]], sorted(e["p"] for e in files))
            self.assertIsNone(got[0]["changed"])
            files[1] = self._entry("b", gain=2.5)
            self.assertTrue(self._wait(lambda: len(got) >= 2))
            self.assertEqual(got[1]["changed"], {"D:\\m\\b.mkv"})
            self.assertEqual(len(got[1]["files"]), 3)
            self.assertEqual({e["p"]: e["f"].get("gain") for e in got[1]["files"]}["D:\\m\\b.mkv"], 2.5)

    def test_a_file_that_left_the_list_leaves_the_users_list(self):
        with tempfile.TemporaryDirectory() as tmp:
            files = [self._entry("a"), self._entry("b")]
            b, c, got, _clocks = self._run(tmp, files)
            self.assertTrue(self._wait(lambda: got))
            del files[0]
            self.assertTrue(self._wait(lambda: len(got) >= 2))
            self.assertEqual([e["p"] for e in got[-1]["files"]], ["D:\\m\\b.mkv"])

    def test_the_channel_clocks_arrive_with_the_moment_they_were_received(self):
        with tempfile.TemporaryDirectory() as tmp:
            clock = {"05": {"now": {"file": "D:\\m\\a.mkv", "length": 1500.0, "remaining": 900.0}, "next": []}}
            b, c, _files, got = self._run(tmp, [self._entry("a")], clocks=clock)
            self.assertTrue(self._wait(lambda: got))
            self.assertEqual(got[0]["channels"], clock)
            self.assertIsInstance(got[0]["received_at"], float)

    def test_a_user_asks_for_the_whole_list_again_when_its_copy_is_not_the_servers(self):
        with tempfile.TemporaryDirectory() as tmp:
            files = [self._entry("a"), self._entry("b")]
            b, c, got, _clocks = self._run(tmp, files)
            self.assertTrue(self._wait(lambda: got))
            c._held_digest = "not what the server has"
            c._take_files({"type": "files_delta", "slot_id": "a", "digest": "x", "base": "stale", "seq": 0, "total": 1, "files": [], "removed": []})
            self.assertTrue(self._wait(lambda: len(got) >= 2))
            self.assertIsNone(got[-1]["changed"])
            self.assertEqual(len(got[-1]["files"]), 2)

    def test_a_list_that_does_not_match_the_servers_digest_is_not_used(self):
        import server_sync
        used, c = [], server_sync.ScheduleClient("127.0.0.1", slot_id="a", on_files=lambda m: used.append(m))
        c._take_files({"type": "files", "slot_id": "a", "digest": "wrong", "seq": 0, "total": 1, "files": [self._entry("a")]})
        self.assertEqual(used, [])
        good = [self._entry("a")]
        c._take_files({"type": "files", "slot_id": "a", "digest": server_sync.files_digest(good), "seq": 0, "total": 1, "files": good})
        self.assertEqual(len(used), 1)

    def test_a_user_asks_again_only_so_many_times_a_minute(self):
        import server_sync
        c = server_sync.ScheduleClient("127.0.0.1", slot_id="a")
        for _ in range(10):
            c._ask_for_fresh_list("test")
        self.assertEqual(len(c._resync_times), server_sync.CLIENT_RESYNC_MAX_PER_MIN)

    def test_only_the_changed_files_have_their_facts_saved_again(self):
        import server_remote_files as srf
        saved = []
        original = srf.RemoteFileMap.__dict__["_save_facts"]
        self.addCleanup(setattr, srf.RemoteFileMap, "_save_facts", original)
        srf.RemoteFileMap._save_facts = staticmethod(lambda library, unc, entry, mismatches=None: saved.append(entry["p"]) or True)
        file_map = srf.RemoteFileMap("srv", lambda: object())
        entries = [self._entry("a"), self._entry("b")]
        file_map.update(entries)
        self.assertEqual(sorted(saved), ["D:\\m\\a.mkv", "D:\\m\\b.mkv"])
        del saved[:]
        file_map.update(entries, {"D:\\m\\b.mkv"})
        self.assertEqual(saved, ["D:\\m\\b.mkv"])

    def test_the_numbers_are_in_the_governor_and_the_old_digest_helper_is_gone(self):
        self.assertEqual((gov.SERVER_CLOCKS_REFRESH_S, gov.CLIENT_RESYNC_MAX_PER_MIN), (5.0, 3))
        self.assertNotIn("digest_of", open(os.path.join(SCRIPTS, "server", "server_files.py"), encoding="utf-8").read())
        main = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn("on_clocks=_on_remote_clocks", main)
        self.assertIn('app_state["server_channel_clocks"]', main)


class TestUserChecksItsHubAgainstTheServer(unittest.TestCase):
    """Part of the server/user switch: a User compares its own hub with the server's channel clocks, drops what differs, applies the server's schedule again when it keeps differing, and tells the viewer while the server is still preparing the channel's files."""

    def _show(self, name="a", start=1000.0, length=1500.0, missing=None):
        show = {"file": "D:\\m\\%s.mkv" % name, "kind": "episode", "length": length, "start": start, "end": start + length}
        if missing is not None:
            show["missing"] = missing
        return show

    def _row(self, name="a", start=1000.0, length=1500.0):
        return {"path": "D:\\m\\%s.mkv" % name, "planned_start": start, "used_length": length}

    def _state(self, channels, received=100.0):
        return {"received_at": received, "channels": channels}

    def _checkin(self, **kwargs):
        import server_checkin
        return server_checkin.ServerCheckin(mono=lambda: 105.0, **kwargs)

    def test_the_same_show_at_the_same_time_agrees(self):
        import server_checkin as sc
        self.assertEqual(sc.judge(self._row(), self._show(), sc.same_path), sc.AGREE)
        self.assertEqual(sc.judge(self._row(start=1003.0), self._show(), sc.same_path), sc.AGREE)
        self.assertEqual(sc.judge(self._row(name="A"), self._show(), sc.same_path), sc.AGREE)

    def test_another_file_or_another_start_does_not(self):
        import server_checkin as sc
        self.assertEqual(sc.judge(self._row(name="b"), self._show(), sc.same_path), sc.OTHER_FILE)
        self.assertEqual(sc.judge(self._row(start=1100.0), self._show(), sc.same_path), sc.OFFSET)
        self.assertEqual(sc.judge(None, self._show(), sc.same_path), sc.NO_LOCAL)
        self.assertEqual(sc.judge(self._row(), None, sc.same_path), sc.NO_CLOCK)

    def test_a_difference_is_reported_and_nothing_is_dropped_or_applied_again(self):
        import server_checkin as sc
        checkin = self._checkin()
        state = self._state({"05": {"now": self._show(), "next": []}})
        for _ in range(5):
            result = checkin.step(state, lambda ch: self._row(name="b"), sc.same_path)
            self.assertEqual(result["verdicts"], {"05": sc.OTHER_FILE})
            self.assertNotIn("forget", result)
            self.assertNotIn("reapply", result)
        main = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        loop = main[main.index("def _server_checkin_loop("):main.index('name="ServerCheckin"')]
        self.assertNotIn("forget_show_facts", loop)
        self.assertNotIn("_apply_remote_schedule_message", loop)

    def test_clocks_that_stop_coming_are_called_stale_once(self):
        import server_checkin as sc
        checkin = sc.ServerCheckin(stale_s=20.0, mono=lambda: 200.0)
        old = self._state({"05": {"now": self._show(), "next": []}}, received=100.0)
        first = checkin.step(old, lambda ch: None, sc.same_path)
        self.assertEqual((first["stale"], first["became_stale"], first["verdicts"]), (True, True, {}))
        self.assertFalse(checkin.step(old, lambda ch: None, sc.same_path)["became_stale"])
        self.assertTrue(checkin.step(None, lambda ch: None, sc.same_path)["stale"])

    def test_what_the_server_lacks_for_the_watched_channel_is_reported(self):
        import server_checkin as sc
        clocks = {"05": {"now": self._show(missing=["gain"]), "next": [self._show("b", missing=["box", "gain"]), self._show("c", missing=["header"])]},
                  "06": {"now": self._show("z", missing=["header"]), "next": []}}
        result = self._checkin().step(self._state(clocks), lambda ch: self._row(), sc.same_path, watched="05")
        self.assertEqual(result["preparing"], ["box", "gain"])
        self.assertEqual(self._checkin().step(self._state(clocks), lambda ch: self._row(), sc.same_path, watched=None)["preparing"], [])
        done = {"05": {"now": self._show(missing=[]), "next": []}}
        self.assertEqual(self._checkin().step(self._state(done), lambda ch: self._row(), sc.same_path, watched="05")["preparing"], [])

    def test_the_main_app_runs_the_check_in_beside_the_client(self):
        main = open(os.path.join(ROOT, "retro_tv_emulator.py"), encoding="utf-8").read()
        self.assertIn('name="ServerCheckin"', main)
        self.assertIn("server_checkin.ServerCheckin()", main)
        self.assertIn("SERVER IS PREPARING THIS CHANNEL'S FILES", main)
        self.assertEqual((gov.SERVER_CHECKIN_EVERY_S, gov.SERVER_CHECKIN_START_TOLERANCE_S, gov.SERVER_CLOCKS_STALE_S, gov.SERVER_PREPARING_NOTICE_EVERY_S),
                         (10.0, 8.0, 20.0, 60.0))
        self.assertFalse(hasattr(gov, "SERVER_CHECKIN_REAPPLY_AFTER"))


class TestServerStopAndHeartbeat(unittest.TestCase):
    """Stop Server checks that streaming really went off, and a service whose loop stopped turning is ended and started again."""

    def test_stopping_streaming_tries_again_once_and_says_so_when_it_cannot(self):
        import server_files
        calls = []
        self.assertTrue(server_files.stop_streaming_verified(None, switch=lambda on, log: calls.append(on) or True))
        self.assertEqual(calls, [False])
        calls.clear()
        results = iter([False, True])
        self.assertTrue(server_files.stop_streaming_verified(None, switch=lambda on, log: calls.append(on) or next(results)))
        self.assertEqual(calls, [False, False])
        self.assertFalse(server_files.stop_streaming_verified(None, switch=lambda on, log: False))

    def test_the_tray_stop_uses_the_verified_switch_off(self):
        src = open(os.path.join(SCRIPTS, "server", "server_service.py"), encoding="utf-8").read()
        self.assertIn("server_files.stop_streaming_verified(log)", src)
        self.assertNotIn("server_files.set_streaming(False, log)\n        finally", src)

    def test_a_heartbeat_has_an_age_and_a_missing_one_is_none(self):
        import server_service
        with tempfile.TemporaryDirectory() as tmp:
            os.makedirs(os.path.join(tmp, "logs"), exist_ok=True)
            self.assertIsNone(server_service.heartbeat_age(tmp))
            server_service.write_heartbeat(tmp, now=1000.0)
            self.assertEqual(server_service.heartbeat_age(tmp, now=1042.0), 42.0)

    def test_a_service_with_an_old_heartbeat_is_ended_and_started_again(self):
        import server_service
        with tempfile.TemporaryDirectory() as tmp:
            os.makedirs(os.path.join(tmp, "logs"), exist_ok=True)
            server_service.write_heartbeat(tmp, now=time.time() - server_service.SERVER_HEARTBEAT_STALE_S - 5)
            stopped, launched = [], []
            originals = {name: getattr(server_service, name) for name in ("_read_pid", "_pid_alive", "stop_service", "set_autostart", "start_is_held", "_service_command")}
            self.addCleanup(lambda: [setattr(server_service, n, f) for n, f in originals.items()])
            server_service._read_pid = lambda base: 999999
            server_service._pid_alive = lambda pid: True
